  ["_CeladonGymEndBattleText7"] = "Oh!\nEsplêndido!",
  ["_CeladonGymEndBattleText8"] = "Oh!\nFui derrotada!",
  ["_CeladonGymErikaPostBattleAdviceText"] = "Então você está\ncatalogando todos\vPOKéMON? Devo lhe\vdizer que fico\vimpressionada com\visso.\fEu jamais pegaria\num POKéMON que eu\vnão considerasse\vbonito.",
