  ["_CeladonGymErikaReceivedRainbowBadgeText"] = "Oh! Eu\nadmito a derrota.\fVocê é realmente\npoderoso.\fDevo conferir-lhe\na INSÍGNIA \vARCO-ÍRIS.",
  ["_CeladonGymRainbowBadgeInfoText"] = "A INSÍGNIA\nARCO-ÍRIS vai\vfazer todos os\vPOKéMON até o {SLOT:BB}50\vte obedecerem.\fTambém permitirá\nque seus POKéMON\vusem a técnica\voculta FORÇA\vdentro e fora das\vbatalhas.\fPor favor, também\nfique com isso.",
