  ["_CeladonMansion1FGrannyText"] = "Meus queridos\nPOKéMON me fazem\vcompanhia.\fMEOWTH até traz\nalguns trocados\vpra casa!",
  ["_CeladonMansion1FManagersSuiteSignText"] = "MANSÃO DE CELADON\nSuíte da Gerente",
