  ["_CeladonMansion3FGameScriptPCText"] = "É o roteiro!\nMelhor eu não\volhar o final!",
  ["_CeladonMansion3FGraphicArtistText"] = "Eu sou o artista\ngráfico!\vEu desenhei você!",
  ["_CeladonMansion3FPlayingGamePCText"] = "Alguém estava\njogando algo em\vvez de trabalhar!",
  ["_CeladonMansion3FProgrammerText"] = "Eu? Eu sou o\nprogramador!",
  ["_CeladonMansion3FWriterText"] = "Eu escrevi a\nhistória!\fA ERIKA não é\numa gracinha?\fEu também gosto\nmuito da MISTY!\fAh, e a SABRINA...\ncomo eu adoro ela!",
  ["_CeladonMansionRoofHouseHikerText"] = "Eu sei de tudo\nsobre o mundo\vPOKéMON em\vseu GAME BOY!\fSe encontre com\nseus amigos para\vtrocar POKéMON!",
  ["_CeladonMansionRoofHouseSignText"] = "EU SEI DE TUDO!",
  ["_CeladonMart1FCurrentFloorSignText"] = "1º ANDAR:\nBALCÃO DE SERVIÇO",
  ["_CeladonMart1FDirectorySignText"] = "1º ANDAR:\nBALCÃO DE SERVIÇO\f2º ANDAR:\nLOJA DO TREINADOR\f3º ANDAR:\nLOJA DE JOGOS\f4º ANDAR:\nLOJA DE PRESENTES\f5º ANDAR:\nFARMÁCIA\fTERRAÇO: MÁQUINAS\nDE BEBIDAS",
  ["_CeladonMart1FReceptionistText"] = "Olá! Bem-vindo ao\nCENTRO COMERCIAL\vDE CELADON.\fO quadro a direita\ndescreve a dispo-\vsição das lojas.",
  ["_CeladonMart2FCurrentFloorSignText"] = "Os Melhores Itens\npara Treinadores!\f2º ANDAR:\nLOJA DO TREINADOR",
  ["_CeladonMart2FGirlText"] = "Quando for fazer\ncaçadas longas,\vé bom comprar\valguns REVIVER.",
  ["_CeladonMart2FMiddleAgedManText"] = "Use SUPERREPELENTE\npara afastar os\vPOKéMON fracos...\fEle dura mais que\no REPELENTE comum!",
  ["_CeladonMart3FClerkReceivedTM18Text"] = "{PLAYER} recebeu\n{RAM:wStringBuffer}!",
  ["_CeladonMart3FClerkTM18ExplanationText"] = "MT18 ensina o\nCONTRA-ATACAR!\vEle causa o dobro\vde dano que o seu\vPOKéMON receber!",
  ["_CeladonMart3FClerkTM18NoRoomText"] = "Sua mochila está\nsem espaço!",
  ["_CeladonMart3FClerkTM18PreReceiveText"] = "Ah, olá! Eu já\nterminei POKéMON!\fVocê ainda não?\nEntão isso pode\vser útil!",
  ["_CeladonMart3FCurrentFloorSignText"] = "Um RPG! Não tenho\ntempo pra isso!",
  ["_CeladonMart3FFightingGameText"] = "Um quebra-cabeças!\nParece viciante!",
  ["_CeladonMart3FGameBoyKid1Text"] = "POKéMON capturados\nsão registrados\vcom o NºID e TO,\vo nome do Treina-\vdor Original que\vos capturou!",
  ["_CeladonMart3FGameBoyKid2Text"] = "Tudo certo!\fMeu amigo vai\ntrocar comigo seu\vKANGASKHAN pelo\vmeu GRAVELER!",
  ["_CeladonMart3FGameBoyKid3Text"] = "Vamos lá,\nGRAVELER!\fEu amo GRAVELER!\nColeciono todos!\fHã?\fGRAVELER se\ntransformou em\voutro POKéMON!",
  ["_CeladonMart3FLittleBoyText"] = "Você pode identi-\nficar os POKéMON\vque você pegou em\vtrocas pelos seus\vNúmeros ID!",
  ["_CeladonMart3FPokemonPosterText"] = "Vermelho e Azul!\nAmbos são POKéMON!",
  ["_CeladonMart3FPuzzleGameText"] = "Um jogo esportivo!\nPapai iria gostar!",
  ["_CeladonMart3FRPGText"] = "É um Super\nNintendo!",
  ["_CeladonMart3FSNESText"] = "3º ANDAR:\nLOJA DE JOGOS",
  ["_CeladonMart3FSportsGameText"] = "Um RPG! Não tenho\ntempo pra isso!",
  ["_CeladonMart4FCurrentFloorSignText"] = "Demonstre seus\nsentimentos com\vpresentes!\f4º ANDAR:\nLOJA DE PRESENTES\fEvolução Especial!\nPEDRAs Elementais\vem oferta hoje!",
  ["_CeladonMart4FSuperNerdText"] = "Vou comprar uma\nPOKéBONECA para\vminha amiga!",
  ["_CeladonMart4FYoungsterText"] = "Fiquei sabendo de\nalgo útil.\fVocê pode fugir de\nPOKéMON selvagens\vdistraindo-os com\vuma POKéBONECA!",
  ["_CeladonMart5FCurrentFloorSignText"] = "5º ANDAR:\nFARMÁCIA",
  ["_CeladonMart5FGentlemanText"] = "Os aprimoradores\nde desempenho dos\vPOKéMON só são\vvendidos aqui.\fUse o CÁLCIO\npara aumentar o\vESPECIAL.\fE use CARBOIDRATOS\npara aumentar a\vVELOCIDADE.",
  ["_CeladonMart5FSailorText"] = "Estou aqui pelos\naprimoradores de\vdesempenho.\fPROTEÍNA vai\naumentar o poder\vde ATAQUE.\fFERRO aumenta\na sua DEFESA!",
  ["_CeladonMartRoofCurrentFloorSignText"] = "TERRAÇO: MÁQUINAS\nDE BEBIDAS",
  ["_CeladonMartRoofLittleGirlGiveHerADrinkText"] = "Estou com sede!\nEu quero alguma\vcoisa para beber!\fDar um bebiba\npara ela?",
  ["_CeladonMartRoofLittleGirlGiveHerWhichDrinkText"] = "Dar qual bebida\npara ela?",
  ["_CeladonMartRoofLittleGirlImNotThirstyText"] = "Não, obrigada!\nJá não estou com\vtanta sede assim!",
  ["_CeladonMartRoofLittleGirlImThirstyText"] = "Estou com sede!\nEu quero alguma\vcoisa para beber!",
  ["_CeladonMartRoofLittleGirlNoRoomText"] = "Você não tem\nespaço pra isso!",
  ["_CeladonMartRoofLittleGirlReceivedTM13Text"] = "{PLAYER} recebeu\n{RAM:wStringBuffer}!",
  ["_CeladonMartRoofLittleGirlReceivedTM48Text"] = "{PLAYER} recebeu\n{RAM:wStringBuffer}!",
  ["_CeladonMartRoofLittleGirlReceivedTM49Text"] = "{PLAYER} recebeu\na MT49!",
  ["_CeladonMartRoofLittleGirlTM13ExplanationText"] = "\f{RAM:wStringBuffer} contém\nRAIO CONGELANTE!\fPode congelar o\nalvo às vezes!",
  ["_CeladonMartRoofLittleGirlTM48ExplanationText"] = "\f{RAM:wStringBuffer} contém\nDESLIZE DE PEDRAS!\fPode assustar o\nalvo às vezes!",
  ["_CeladonMartRoofLittleGirlTM49ExplanationText"] = "\fMT49 contém\nTRIATAQUE!",
  ["_CeladonMartRoofLittleGirlYayFreshWaterText"] = "Eba!\fÁGUA MINERAL!\fObrigada!\fVou te dar isso\nem troca!",
  ["_CeladonMartRoofLittleGirlYayLemonadeText"] = "Eba!\fLIMONADA!\fObrigada!\fVou te dar isso\nem troca!",
  ["_CeladonMartRoofLittleGirlYaySodaPopText"] = "Eba!\fREFRIGERANTE!\fObrigada!\fVou te dar isso\nem troca!",
  ["_CeladonMartRoofSuperNerdText"] = "Minha irmã é uma\ntreinadora, acre-\vdite se quiser.\fMas ela é tão\nimatura, que me\vdeixa louco!",
  ["_CeladonPokecenterBeautyText"] = "Eu vim de FUCHSIA\nladeira acima na\vROTA DO CICLISMO!",
  ["_CeladonPokecenterGentlemanText"] = "POKéFLAUTA acorda\nPOKéMON com um\vsom que somente\veles podem ouvir!",
  ["_CeruleanBadgeHouseBoulderBadgeText"] = "O ATAQUE de todos\nPOKéMON aumentará\vum pouco.\fTambém te permite\nusar CLARÃO em\vqualquer momento.",
  ["_CeruleanBadgeHouseCascadeBadgeText"] = "POKéMON até o {SLOT:BB}30\nvão te obedecer.\fUm pouco mais, e\nficarão rebeldes!\fTambém te permite\nusar CORTAR fora\vdas batalhas.",
  ["_CeruleanBadgeHouseEarthBadgeText"] = "Todos os POKéMON\nirão te obedecer!",
  ["_CeruleanBadgeHouseMarshBadgeText"] = "POKéMON até o {SLOT:BB}70\nvão te obedecer.\fUm pouco mais, e\nficarão rebeldes!",
  ["_CeruleanBadgeHouseMiddleAgedManText"] = "INSÍGNIAS POKéMON\nsão conquistadas\vapenas pelos mais\vhabilidosos dos\vtreinadores.\fVejo que você tem\npelo menos uma.\fEssas INSÍGNIAS\ntambém guardam\valguns segredos\vincríveis!",
  ["_CeruleanBadgeHouseMiddleAgedManVisitAnyTimeText"] = "Venha me visitar\nsempre que quiser.",
  ["_CeruleanBadgeHouseMiddleAgedManWhichBadgeText"] = "Então...\fVocê vai querer\nver a descrição\vde qual INSÍGNIA?",
  ["_CeruleanBadgeHouseRainbowBadgeText"] = "POKéMON até o {SLOT:BB}50\nvão te obedecer.\fUm pouco mais, e\nficarão rebeldes!\fTambém te permite\nusar FORÇA fora\vdas batalhas.",
  ["_CeruleanBadgeHouseSoulBadgeText"] = "A DEFESA de todos\nPOKéMON aumentará\vum pouco.\fTambém te permite\nusar SURFAR fora\vdas batalhas.",
  ["_CeruleanBadgeHouseThunderBadgeText"] = "A VELOCIDADE de\ntodos os POKéMON\vsubirá um pouco.\fTambém te permite\nusar VOAR fora\vdas batalhas.",
  ["_CeruleanBadgeHouseVolcanoBadgeText"] = "O poder ESPECIAL\ndos seus POKéMON\vsubirá um pouco.",
  ["_CeruleanCityBikeShopSign"] = "Atravesse gramados\ne cavernas como\vnunca!\fLOJA DE BICICLETAS",
  ["_CeruleanCityCooltrainerF1SlowbroPunchText"] = "SLOWBRO, PORRADA!\n...Errou de novo!",
  ["_CeruleanCityCooltrainerF1SlowbroUseSonicboomText"] = "OK! SLOWBRO! Use\no ESTOURO SÔNICO!\vQualé, SLOWBRO,\vpreste atenção!",
  ["_CeruleanCityCooltrainerF1SlowbroWithdrawText"] = "SLOWBRO, RETIRADA!\nNão! Está errado!\fÉ tão difícil\ncontrolar alguns\vPOKéMON!\fA obediência dos\nPOKéMON depende\vda sua habilidade\vcomo treinador!",
  ["_CeruleanCityCooltrainerF2Text"] = "Eu quero uma\nBICICLETA verme-\vlha e reluzente!\fVou guardar ela\nem casa, assim\vnão vai sujar!",
  ["_CeruleanCityCooltrainerMText"] = "Você também é um\ntreinador? Cole-\vcionar, batalhar,\vé uma vida dura.",
  ["_CeruleanCityGuardText"] = "Os moradores daqui\nforam roubados.\fÉ óbvio que a\nEQUIPE ROCKET\vestá por trás\vdesse hediondo\vato criminoso!\fAté mesmo nossa\nforça policial\vtêm problemas com\vesses ROCKETs!",
  ["_CeruleanCityGymSign"] = "GINÁSIO POKéMON\nDE CERULEAN\vLÍDER: MISTY\fA Sereia Durona!",
  ["_CeruleanCityRivalDefeatedText"] = "Ei!\nPega leve!\vVocê já venceu!",
  ["_CeruleanCityRivalIWentToBillsText"] = "{RIVAL}: Ei,\nadivinha só?\fFui até o BILL\ne ele me mostrou\valguns dos seus\vPOKéMON raros!\fIsso adicionou\nvárias páginas\vnovas na minha\vPOKéDEX!\fAfinal, BILL é\nmundialmente\vfamoso como o\vPOKéMANÍACO!\fFoi ele o criador\ndo Sistema de\vArmazenamento de\vPOKéMON no PC!\fJá que você está\nusando o sistema\vdele, deveria\vir agradecer!\fBem, eu tenho\nque ir nessa!\vFalou aí!",
  ["_CeruleanCityRivalPreBattleText"] = "{RIVAL}: E aí!\n{PLAYER}!\fVocê está tendo\nmuito trabalho\vaí atrás?\fEu estou ótimo!\nCapturei vários\vPOKéMON que são\vfortes e astutos!\fVamos lá, me\nmostre quais você\vpegou, {PLAYER}!",
  ["_CeruleanCityRivalVictoryText"] = "Heh!\nVocê não é páreo\vpara mim!",
  ["_CeruleanCityRocketIBetterGetMovingText"] = "\fÉ melhor eu me\nmandar! Tchau!",
  ["_CeruleanCityRocketIGiveUpText"] = "Pare!\nEu desisto! Vou\vsair quietinho!",
  ["_CeruleanCityRocketIllReturnTheTMText"] = "OK! Vou devolver a\nMT que eu roubei!",
  ["_CeruleanCityRocketReceivedTM28Text"] = "{PLAYER} recuperou\na MT28!",
  ["_CeruleanCityRocketTM28NoRoomText"] = "Arrange espaço pra\nisso aqui!\fNão posso fugir\nantes de te\ventregar isso!",
  ["_CeruleanCityRocketText"] = "Ei! Cai fora!\nIsso aqui não é o\vseu quintal, não!\vHã? Eu?\fSou apenas um\ninocente cidadão\vde passagem! Não\vacredita em mim?",
  ["_CeruleanCitySignText"] = "CIDADE DE CERULEAN\nUma Misteriosa,\vAura Azul a Rodeia",
  ["_CeruleanCitySlowbroIgnoredOrdersText"] = "SLOWBRO ignorou\nas ordens...",
  ["_CeruleanCitySlowbroIsLoafingAroundText"] = "SLOWBRO está se\nespreguiçando...",
  ["_CeruleanCitySlowbroTookASnoozeText"] = "SLOWBRO tirou\numa soneca...",
  ["_CeruleanCitySlowbroTurnedAwayText"] = "SLOWBRO virou\na cara...",
  ["_CeruleanCitySuperNerd1Text"] = "Esse arbusto em\nfrente da loja\vestá no caminho.\fDeve ter algum\njeito de dar\va volta.",
  ["_CeruleanCitySuperNerd2Text"] = "Você está fazendo\numa enciclopédia\vsobre POKéMON?\vIsso parece\vser divertido.",
  ["_CeruleanCitySuperNerd3Text"] = "Essa é a CAVERNA\nDE CERULEAN!\vOs POKéMON que\vvivem aqui são\vterrivelmente\vpoderosos!\fApenas o campeão\nda LIGA POKéMON é\vpermitido entrar\vnesse lugar!",
  ["_CeruleanCityTrainerTipsText"] = "Atravesse gramados\ne cavernas como\vnunca!\fLOJA DE BICICLETAS",
  ["_CeruleanGymAfterBattleText1"] = "Precisa enfrentar\noutros treinado-\vres para saber\vo quão bom você\vrealmente é.",
  ["_CeruleanGymAfterBattleText2"] = "MISTY continuará a\nse aperfeiçoar!\fEla não perderá\npra alguém assim\vcomo você!",
  ["_CeruleanGymBattleText1"] = "Sou mais que sufi-\nciente pra você!\fMISTY pode\nesperar!",
  ["_CeruleanGymBattleText2"] = "Tibum!\fSerei o primeiro!\nVamos começar!",
  ["_CeruleanGymEndBattleText1"] = "Você\nme surpreendeu!",
  ["_CeruleanGymEndBattleText2"] = "Não\npode ser!",
  ["_CeruleanGymGymGuideBeatMistyText"] = "Você venceu a\nMISTY! O que foi\vque eu disse?\fVocê e eu garoto,\nsomos uma bela\vde uma equipe!",
  ["_CeruleanGymGymGuideChampInMakingText"] = "E aí! Campeão em\nconstrução!\fAqui vai o meu\nconselho!\fA LÍDER, MISTY,\né profissional em\vPOKéMON de ÁGUA!\fVocê pode drenar a\nágua deles com\vseus POKéMON do\vtipo planta!\fOu, torrar eles\ncom eletricidade!",
  ["_CeruleanGymMistyCascadeBadgeInfoText"] = "A INSÍGNIA CASCATA\nfará todos os\vPOKéMON até o {SLOT:BB}30\vte obedecerem!\fIsso inclui até\nos forasteiros,\vque você recebeu\vcom trocas!\fE tem mais, você\npoderá usar a\vtécnica CORTAR a\vqualquer hora!\fPoderá CORTAR os\narbustos e abrir\vnovos caminhos!\fVocê também pode\nficar com a minha\vMT predileta!",
  ["_CeruleanGymMistyPreBattleText"] = "Oi, você é novo\npor aqui!\fTreinadores que\nquerem ser pro-\vfissionais, devem\vter uma filosofia\vsobre POKéMON!\fComo é sua aborda-\ngem quando você\vcaptura POKéMON?\fMinha filosofia é\na total ofensiva\vusando POKéMON do\vtipo ÁGUA!",
  ["_CeruleanGymMistyReceivedCascadeBadgeText"] = "Uau!\nVocê é demais!\fTudo bem!\fVocê pode ficar\ncom a INSÍGNIA\vCASCATA para\vmostrar que\vme derrotou!",
  ["_CeruleanGymMistyReceivedTM11Text"] = "{PLAYER} recebeu\na MT11!",
  ["_CeruleanGymMistyTM11ExplanationText"] = "MT11 ensina\nJATO DE BOLHAS!\fEnsine para um\nPOKéMON aquático!",
  ["_CeruleanGymMistyTM11NoRoomText"] = "Você não tem\nespaço pra isso!",
  ["_CeruleanMartCooltrainerFText"] = "Você já viu algum\nDOCE RARO?\fEle faz um POKéMON\nsubir um nível!",
  ["_CeruleanMartCooltrainerMText"] = "Use REPELENTEs\npara manter os\vinsetos e POKéMON\vfracos bem longe.\fDeixe seu POKéMON\nmais forte no\vtopo da lista\vpara melhores\vresultados!",
  ["_CeruleanPokecenterGentlemanText"] = "Já ouviu falar\nsobre o BILL?\fTodo mundo o chama\nde POKéMANÍACO!\fAcho que só estão\ncom inveja do\vBILL, entretanto.\fQuem não iria se\ngabar dos seus\vPOKéMON raros?",
  ["_CeruleanPokecenterGuyText"] = "BILL tem vários\nPOKéMON!\fEle coleciona uns\nbem raros também!",
  ["_CeruleanPokecenterSuperNerdText"] = "Aquele BILL!\fOuvi dizer que\nele fará de tudo\vpara conseguir\vPOKéMON raros!",
  ["_CeruleanTradeHouseGrannyText"] = "Meu marido adora\ntrocar POKéMON.\fSe você for um\ncolecionador, que\vtal fazer uma\vtroca com ele?",
  ["_CeruleanTrashedHouseFishingGuruTheyStoleATMText"] = "Esses malditos\nROCKETs!\fOlha o que\nfizeram aqui!\fRoubaram minha MT\npara ensinar os\vPOKéMON como\vCAVAR buracos!\fIsso me deu um\nbaita prejuízo!",
  ["_CeruleanTrashedHouseFishingGuruWhatsLostIsLostText"] = "O que está perdido\nestá perdido!\fEu decidi que vou\nensinar o DIGLETT\va CAVAR sem a MT!",
  ["_CeruleanTrashedHouseGirlText"] = "A EQUIPE ROCKET\ndeve estar que-\vrendo CAVAR para\ventrar em alguma\vfalcatrua!",
  ["_CeruleanTrashedHouseWallHoleText"] = "A EQUIPE ROCKET\ndeixou um belo\vde um rastro!",
  ["_ChampionsRoomOakComeWithMeText"] = "CARVALHO: \n{PLAYER}!\fVocê entende que\nsua vitória não é\vum mérito apenas\vseu!\fA ligação que você\ncompartilha com\vseus POKéMON\vé maravilhosa!\f{PLAYER}!\nVenha comigo!",
  ["_ChampionsRoomOakCongratulatesPlayerText"] = "CARVALHO: Então,\nvocê venceu! Meus\vParabéns! Você é\vo novo campeão da\vLIGA POKéMON!\fVocê cresceu muito\ndesde que partiu\vpela primeira vez\vcom o {RAM:wNameBuffer}!\f{PLAYER}, você\namadureceu!",
  ["_ChampionsRoomOakDisappointedWithRivalText"] = "CARVALHO: Estou\ndesapontado com\vvocê, {RIVAL}!\fEu vim quando\nfiquei sabendo\vque você havia\vderrotado a ELITE\vDOS QUATRO!\fMas quando eu\ncheguei aqui,\vvocê já tinha\vperdido!\f{RIVAL}! Você\nentende por que\vvocê perdeu?\fVocê se esqueceu\nde tratar seus\vPOKéMON com\vamor e confiança!\fSem isso, você\nnunca irá se\vtornar um campeão\vnovamente!",
  ["_ChampionsRoomOakText"] = "CARVALHO: \n{PLAYER}!",
  ["_ChampionsRoomRivalAfterBattleText"] = "Por quê?\nPor que eu perdi?\fEu nunca cometi\nnenhum erro ao\vcriar os meus\vPOKéMON...\fDroga! Você é o\nnovo campeão da\vLIGA POKéMON!\fMesmo que eu não\ngoste de admitir.",
  ["_ChampionsRoomRivalIntroText"] = "{RIVAL}: Ei!\fEu estava ansioso\npara ver você,\v{PLAYER}!\fMeu rival deve ser\nforte para me\vmanter afiado!\fEnquanto eu traba-\nlhava completando\va POKéDEX, eu\vvasculhei por\vtoda parte atrás\vdos POKéMON mais\vpoderosos!\fE além disso, eu\nreuni uma equipe\vque pode derrotar\vqualquer tipo de\vPOKéMON!\fE agora!\fEu sou o campeão\nda LIGA POKéMON!\f{PLAYER}!\nSabe o que isso\vsignifica?\fEu vou te dizer!\fEu sou o treinador\nmais poderoso do\vmundo inteiro!",
  ["_ChanseyDexEntry"] = "Um POKéMON raro e\nelusivo que dizem\ntrazer felicidade\fpara aqueles\nque conseguem\ncapturá-lo",
  ["_ChargeMoveEffectText"] = "{USER}",
  ["_CharizardDexEntry"] = "Cospe fogo quente\nsuficiente para\nderreter pedras.\fCostuma causar in-\ncêndios florestais\npor acidente",
  ["_CharmanderDexEntry"] = "Prefere ficar em\nambientes quentes.\nQuando chove,\fdizem que jorra\nvapor da ponta\nde sua cauda",
  ["_CharmeleonDexEntry"] = "Quando balança sua\ncauda flamejante,\nconsegue elevar a\ftemperatura do\nambiente a níveis\ninsuportáveis",
  ["_ChooseABoxText"] = "Escolha a\nPOKéCAIXA.",
  ["_CinnabarGymBlainePostBattleAdviceText"] = "RAJADA DE FOGO é\na técnica suprema\vdo tipo fogo!\fNão desperdice ela\nusando contra\vPOKéMON de água!",
  ["_CinnabarGymBlainePreBattleText"] = "Hah!\fEu sou BLAINE! O\nLÍDER do GINÁSIO\vDA ILHA CINNABAR!\fMeus POKéMON\nardentes vão\vincinerar todos\vos oponentes!\fHah! Será que\nvocê atura?\vVai precisar de\vum ANTIQUEIMADURA!",
  ["_CinnabarGymBlaineReceivedTM38Text"] = "{PLAYER} recebeu\n{RAM:wStringBuffer}!",
  ["_CinnabarGymBlaineReceivedVolcanoBadgeText"] = "Meu\nfogo se apagou!\fVocê conquistou a\nINSÍGNIA VULCÃO!",
  ["_CinnabarGymBlaineTM38ExplanationText"] = "\fMT38 contém\nRAJADA DE FOGO!\fEnsine para um\nPOKéMON de fogo!\fCHARMELEON ou\nPONYTA seriam\vboas escolhas!",
  ["_CinnabarGymBlaineTM38NoRoomText"] = "Você precisa abrir\nespaço para o meu\vpresente!",
  ["_CinnabarGymBlaineVolcanoBadgeInfoText"] = "Hah!\fA INSÍGNIA VULCÃO\naumenta a habi-\vlidade ESPECIAL\vdos seus POKéMON!\fVocê também pode\nficar com isso!",
  ["_CinnabarGymGymGuideBeatBlaineText"] = "{PLAYER}! Você\nvenceu aquele\vesquentadinho!",
  ["_CinnabarGymGymGuideChampInMakingText"] = "E aí! Campeão em\nconstrução!\fO cabeça-quente do\nBLAINE é um pro-\vfissional em\vPOKéMON de fogo!\fAbata seu espírito\ncom muita água!\fSeria bom você ter\num ANTIQUEIMADURA!",
  ["_CinnabarGymQuizCorrectText"] = "Você está absolu-\ntamente correto!\fPode passar!",
  ["_CinnabarGymQuizIncorrectText"] = "Desculpe!\nResposta errada!",
  ["_CinnabarGymQuizIntroText"] = "Charadas POKéMON!\fAcerte a resposta\ne a porta vai se\vabrir!\fSe errar terá que\nenfrentar um\vtreinador!\fSe quiser poupar\nseus POKéMON para\vo LÍDER DO\vGINÁSIO...\fEntão acerte tudo!\nComeçando!",
  ["_CinnabarGymSuperNerd1AfterBattleText"] = "Fogo, ou para ser\nmais preciso,\vcombustão...\fBlá, blá, blá,\nblá...",
  ["_CinnabarGymSuperNerd1BattleText"] = "Você sabe o quão\nquente o bafo de\vum POKéMON de\vfogo pode chegar?",
  ["_CinnabarGymSuperNerd1EndBattleText"] = "Au!\nQuente, quente!",
  ["_CinnabarGymSuperNerd2AfterBattleText"] = "Não consigo parar\nde roubar POKéMON\vde outras pessoas!",
  ["_CinnabarGymSuperNerd2BattleText"] = "Eu era um ladrão,\nmas agora sou um\vtreinador honrado!",
  ["_CinnabarGymSuperNerd2EndBattleText"] = "Eu desisto\ndessa vida!",
  ["_CinnabarGymSuperNerd3AfterBattleText"] = "Minhas teorias são\nmuito complicadas\vpra você!",
  ["_CinnabarGymSuperNerd3BattleText"] = "Você não vai con-\nseguir me vencer!\vEu estudei tudo\vsobre POKéMON!",
  ["_CinnabarGymSuperNerd3EndBattleText"] = "Aaah!\nMeus estudos!",
  ["_CinnabarGymSuperNerd4AfterBattleText"] = "Eu gostaria que\nexistisse um\vPOKéMON ladrão!\vEu iria usar\vum desses!",
  ["_CinnabarGymSuperNerd4BattleText"] = "Eu gosto apenas de\nPOKéMON de fogo!",
  ["_CinnabarGymSuperNerd4EndBattleText"] = "Quente\ndemais pra mim!",
  ["_CinnabarGymSuperNerd5AfterBattleText"] = "BLAINE estava per-\ndido nas monta-\vnhas, quando um\vPOKéMON pássaro\vflamejante apare-\vceu.\fSua luz permitiu\nque BLAINE encon-\vtrasse o caminho\vde volta!",
  ["_CinnabarGymSuperNerd5BattleText"] = "Eu sei o porquê do\nBLAINE ser um\vtreinador!",
  ["_CinnabarGymSuperNerd5EndBattleText"] = "Au!",
  ["_CinnabarGymSuperNerd6AfterBattleText"] = "Nós, os fãs de\nPOKéMON de fogo\vgostamos de PONY-\vTA e NINETALES!",
  ["_CinnabarGymSuperNerd6BattleText"] = "Eu já estive em\nvários GINÁSIOs,\vmas esse é o meu\vfavorito!",
  ["_CinnabarGymSuperNerd6EndBattleText"] = "Caramba!\nMuito quente!",
  ["_CinnabarGymSuperNerd7AfterBattleText"] = "Água apaga o fogo!\nMas fogo derrete\vPOKéMON de gelo!",
  ["_CinnabarGymSuperNerd7BattleText"] = "Fogo é fraco\ncontra H2O!",
  ["_CinnabarGymSuperNerd7EndBattleText"] = "Ah!\nApagou meu fogo!",
  ["_CinnabarIslandDoorIsLockedText"] = "A porta está\ntrancada...",
  ["_CinnabarIslandGamblerText"] = "Cientistas faziam\nexperimentos na\vmansão que foi\vqueimada.",
  ["_CinnabarIslandGirlText"] = "BLAINE do GINÁSIO\nDA ILHA CINNABAR\vé um homem esqui-\vsito que vive\vaqui há décadas.",
  ["_CinnabarIslandGymSignText"] = "GINÁSIO POKéMON\nDA ILHA CINNABAR\vLÍDER: BLAINE\fO Mestre das\nCharadas Quentes!",
  ["_CinnabarIslandPokemonLabSignText"] = "LABORATÓRIO\nPOKéMON",
  ["_CinnabarIslandSignText"] = "ILHA CINNABAR\nO Vilarejo Quente\vdo Desejo Ardente",
  ["_CinnabarLabFishingGuruText"] = "Nós estudamos os\nPOKéMON extensi-\vvamente aqui.\fAs pessoas costu-\nmam nos trazer\vPOKéMON raros\vpara examinarmos.",
  ["_CinnabarLabFossilRoomScientist1ComeAgainText"] = "Aiyah! Você voltar\ndepois!",
  ["_CinnabarLabFossilRoomScientist1FossilIsBackToLifeText"] = "Onde você estava?\fSeu fóssil está\nde volta a vida!\fEra um {RAM:wStringBuffer}\ncomo eu pensava!",
  ["_CinnabarLabFossilRoomScientist1GoForAWalkText"] = "Eu demorar um\npouco!\fVocê ir dar uma\npasseio rápido!",
  ["_CinnabarLabFossilRoomScientist1GoForAWalkText2"] = "Eu demorar um\npouco!\fVocê ir dar uma\npasseio rápido!",
  ["_CinnabarLabFossilRoomScientist1NoFossilsText"] = "Não! Mas que pena!",
  ["_CinnabarLabFossilRoomScientist1SeesFossilText"] = "Oh! Esse ser\n{RAM:wNameBuffer}!\fÉ um fóssil de\n{RAM:wStringBuffer}, um\vPOKéMON que já\vestá extinto!\fMinha Máquina de\nRessurreição vai\vtrazer esse POKé-\vMON de volta à \vvida! Tudo bem?",
  ["_CinnabarLabFossilRoomScientist1TakesFossilText"] = "Então! Se apresse\ne me dê isso!\f{PLAYER} entregou\no {RAM:wNameBuffer}!",
  ["_CinnabarLabFossilRoomScientist1Text"] = "Olá!\fEu ser uma doutor\nmuito importante!\fAqui eu estudar os\nraros fósseis de\vPOKéMON!\fEi! Você ter algum\nfóssil para mim?",
  ["_CinnabarLabMeetingRoomSignText"] = "LABORATÓRIO POKéMON\nSala de Reuniões",
  ["_CinnabarLabMetronomeRoomAmberPipeText"] = "Um cachimbo âmbar!",
  ["_CinnabarLabMetronomeRoomPCText"] = "Tem uma mensagem\nde e-mail aberta!\f...\fOs 3 pássaros\nlendários POKéMON\vsão ARTICUNO,\vZAPDOS e MOLTRES.\fA localização\ndeles ainda é\vdesconhecida.\fNós planejamos ex-\nplorar a caverna\vque existe próxi-\vmo de CERULEAN.\fDe: EQUIPE DE\nPESQUISA POKéMON\f...",
  ["_CinnabarLabMetronomeRoomScientist1ReceivedTM35Text"] = "{PLAYER} recebeu \n{RAM:wStringBuffer}!",
  ["_CinnabarLabMetronomeRoomScientist1TM35ExplanationText"] = "Tch-tch-tch!\nEsse é o som de\vum METRÔNOMO!\fEle engana o cére-\nbro do POKéMON e\vfaz ele usar mo-\vvimentos que ele\vnão aprendeu!",
  ["_CinnabarLabMetronomeRoomScientist1TM35NoRoomText"] = "Sua mochila já\nestá cheia!",
  ["_CinnabarLabMetronomeRoomScientist1Text"] = "Tch-tch-tch!\fEu fiz uma MT\nbem interessante!\fEla pode causar\ntudo quanto é\vtipo de diversão!",
  ["_CinnabarLabMetronomeRoomScientist2Text"] = "EEVEE pode evoluir\nem 1 de 3 tipos\vde POKéMON.",
  ["_CinnabarLabPhotoText"] = "Uma foto do funda-\ndor do LABORATÓ-\vRIO, o DR.FUJI!",
  ["_CinnabarLabRAndDSignText"] = "LABORATÓRIO POKéMON\nSala de Pesquisas\ve Desenvolvimento",
  ["_CinnabarLabTestingRoomSignText"] = "LABORATÓRIO POKéMON\nSala de Testes",
  ["_CinnabarLabTradeRoomSuperNerdText"] = "Eu achei esse fós-\nsil estranho na\vMONTANHA DA LUA!\fEu acho que é um\nraro POKéMON \vpré-histórico!",
  ["_CinnabarMartScientistText"] = "Levar alguns itens\nextras não vai\vfazer mal algum!",
  ["_CinnabarMartSilphWorkerFText"] = "Aqui não vendem\nATAQUE X? É ótimo\vpara as batalhas!",
  ["_CinnabarPokecenterCooltrainerFText"] = "Você pode cancelar\na evolução.\fQuando um POKéMON\nestá evoluindo,\vvocê pode pará-lo\ve deixá-lo como\vestava antes.",
  ["_CinnabarPokecenterGentlemanText"] = "Você tem algum\namigo?\fPOKéMON que você\npega em trocas\vcrescem de nível\vmais rápido.\fEu acho que vale\na pena trocar!",
  ["_CinnabarPokecenterGuyText"] = "Os POKéMON ainda\npodem aprender\vtécnicas novas\vdepois de cance-\vlar a evolução.\fA evolução pode\nesperar até que\vtenha aprendido\vnovos golpes.",
  ["_CinnabarQuizQuestionsText1"] = "CATERPIE evolui\npara METAPOD?",
  ["_CinnabarQuizQuestionsText2"] = "Existem 9\ninsígnias da\vLIGA POKéMON?",
  ["_CinnabarQuizQuestionsText3"] = "POLIWAG evolui\n3 vezes?",
  ["_CinnabarQuizQuestionsText4"] = "Golpes elétricos\nsão eficazes\vcontra POKéMON\vtipo terra?",
  ["_CinnabarQuizQuestionsText5"] = "POKéMON do mesmo\nnível e espécie\vsão diferentes?",
  ["_CinnabarQuizQuestionsText6"] = "TM28 contém\nTUMBA DE PEDRA?",
  ["_ClearSaveDataText"] = "Apagar todos os\ndados já salvos?",
  ["_ClefableDexEntry"] = "Um POKéMON fada\ntímido e raramente\nvisto. Vai correr\fe se esconder no\nmomento que sentir\npresença humana",
  ["_ClefairyDexEntry"] = "Sua aparência fofa\ne mágica têm mui-\ntos admiradores.\fÉ raro e encontra-\ndo apenas em \nalgumas áreas",
  ["_ClosedOaksPCText"] = "Cerrando enlace al\nPC del PROF.OAK.",
  ["_CloysterDexEntry"] = "Quando é atacado,\nlança seus espi-\nnhos em rápidas\frajadas. O seu\ninterior nunca\nfoi visto",
  ["_CoinCaseNumCoinsText"] = "Fichas\n{NUM:wPlayerCoins, 2 | LEADING_ZEROES | LEFT_ALIGN} ",
  ["_CoinsScatteredText"] = "Moedas caíram\npor toda a parte!",
  ["_ColosseumOpponentText"] = "¡!",
  ["_ComeBackText"] = "¡Vuelve!",
  ["_ConfusedNoMoreText"] = "¡{USER} ya\nno está confuso!",
  ["_ConnectCableText"] = "Certo, conecte o\ncabo, então!",
  ["_ContCharText"] = "{_CONT}",
  ["_ConvertedTypeText"] = "Converteu seu tipo\npara o mesmo que{SCROLL}o de ROCKET!",
  ["_CopycatsHouse1FChanseyText"] = "CHANSEY: Chaan!\nSii!",
  ["_CopycatsHouse1FMiddleAgedManText"] = "Minha filha gosta\nde ficar imitando\vas pessoas.\fEssa mania lhe\nrendeu o apelido\vde IMITADORA por\vessas bandas!",
  ["_CopycatsHouse1FMiddleAgedWomanText"] = "Minha filha é tão\negocêntrica.\vEla tem poucos\vamigos.",
  ["_CopycatsHouse2FCopycatDoYouLikePokemonText"] = "{PLAYER}: Oi! Você\ngosta de POKéMON?\f{PLAYER}: Hã, não,\neu acabei de\vperguntar isso.\f{PLAYER}: Hã?\nVocê é estranha!\fIMITADORA: Hmm?\nParar de imitar?\fMas é meu passa-\ntempo favorito!",
  ["_CopycatsHouse2FCopycatReceivedTM31Text"] = "{PLAYER} recebeu\n{RAM:wStringBuffer}!",
  ["_CopycatsHouse2FCopycatTM31Explanation1Text"] = "\fMT31 contém meu\ngolpe favorito,\vMÍMICA!\fUse isso em um\nbom POKéMON!",
  ["_CopycatsHouse2FCopycatTM31Explanation2Text"] = "{PLAYER}: Oi! \nObrigado pela\vMT31!\f{PLAYER}: Perdão?\f{PLAYER}: Você\nrealmente acha\vdivertido ficar\vme imitando?\fIMITADORA:\nPode apostar!\vÉ o maior barato!",
  ["_CopycatsHouse2FCopycatTM31NoRoomText"] = "Você não quer\nisso?",
  ["_CopycatsHouse2FCopycatTM31PreReceiveText"] = "Oh, uau!\nUma POKéBONECA!\fPra mim?\nObrigada!\fVocê pode ficar\ncom isso, então!",
  ["_CopycatsHouse2FDoduoText"] = "DODUO: Giiih!\fESPELHO, ESPELHO\nMEU, QUEM É MAIS\vBELA DO QUE EU?",
  ["_CopycatsHouse2FPCCantSeeText"] = "Hã? Eu não vejo\nnada, doutor!",
  ["_CopycatsHouse2FPCMySecretsText"] = "...\fMeus Segredos!\fHabilidade: \nImitar!\fPassatempo: Cole-\ncionar bonecas!\fPOKéMON Favorito:\nCLEFAIRY!",
  ["_CopycatsHouse2FRareDollText"] = "Isso é um POKéMON\nraro! Hã?\vÉ só uma boneca!",
  ["_CopycatsHouse2FSNESText"] = "Um jogo do MARIO\ncom ele usando um\vbalde na cabeça!",
  ["_CriticalHitText"] = "¡Un Golpe Crítico!",
  ["_CuboneDexEntry"] = "Como ele nunca re-\nmove seu capacete\nde crânio, ninguém\fnunca viu o rosto\nverdadeiro desse\nPOKéMON",
  ["_CurrentTooFastText"] = "Bem-vindo ao\nClube Cabo!",
  ["_CyclingIsFunText"] = "A correnteza aqui\né muito rápida!",
  ["_DaycareGentlemanAllRightThenText"] = "Tudo bem, então.\n",
  ["_DaycareGentlemanCantAcceptMonWithHMText"] = "Não posso aceitar\num POKéMON que\vsabe técnicas\vocultas (MO)!",
  ["_DaycareGentlemanComeAgainText"] = "Volte mais tarde.",
  ["_DaycareGentlemanComeSeeMeInAWhileText"] = "Volte depois de\nalgum tempo.",
  ["_DaycareGentlemanGotMonBackText"] = "{PLAYER} recolheu\n{RAM:wDayCareMonName}.",
  ["_DaycareGentlemanHeresYourMonText"] = "Obrigado!\nAqui está seu\vPOKéMON!",
  ["_DaycareGentlemanIntroText"] = "Eu cuido dessa\nCRECHE POKéMON!\vGostaria que eu\vcuidasse de um de\vseus POKéMON?",
  ["_DaycareGentlemanMonHasGrownText"] = "{RAM:wNameBuffer}\ncresceu um pouco!\fO seu nível, \naumentou em {NUM:wDayCareNumLevelsGrown, 1, 3}!\fNão é demais?",
  ["_DaycareGentlemanMonNeedsMoreTimeText"] = "Já voltou?\n{RAM:wNameBuffer} ainda\vprecisa de mais\vtempo comigo.",
  ["_DaycareGentlemanNoRoomForMonText"] = "Você não tem \nespaço para pegar\vesse POKéMON!",
  ["_DaycareGentlemanNotEnoughMoneyText"] = "Ei, você não tem\n¥ suficiente!",
  ["_DaycareGentlemanOnlyHaveOneMonText"] = "Você só tem um\nPOKéMON com você.",
  ["_DaycareGentlemanOweMoneyText"] = "Você me deve ¥{NUM:wDayCareTotalCost, 2 | LEADING_ZEROES | LEFT_ALIGN}\npelos cuidados\vque tive com\vesse POKéMON.\vQuer recolher\v{RAM:wDayCareMonName} agora?",
  ["_DaycareGentlemanWhichMonText"] = "Qual POKéMON\neu devo cuidar?",
  ["_DaycareGentlemanWillLookAfterMonText"] = "Tudo bem, então.\n{RAM:wNameBuffer} está\vem boas mãos!",
  ["_DepositHowManyText"] = "Quantas unidades?",
  ["_DepositWhichMonText"] = "Depositar qual\nPOKéMON?",
  ["_DewgongDexEntry"] = "Armazena energia\ntérmica em seu\ncorpo. Nada a\festáveis 15km/h\nmesmo em intensas\náguas geladas",
  ["_DexCompletionText"] = "Seu progresso da\nPOKéDEX é:\f{NUM:hDexRatingNumMonsSeen, 1, 3} POKéMON vistos\n{NUM:hDexRatingNumMonsOwned, 1, 3} POKéMON pegos\fAvaliação do\nPROF.CARVALHO:",
  ["_DexRatingText"] = "Avaliação da\nsua POKéDEX:",
  ["_DexRatingText_Own0To9"] = "Você ainda tem\nmuito trabalho\vpela frente.\vProcure POKéMON\vnas área gramadas!",
  ["_DexRatingText_Own100To109"] = "Você finalmente\npegou pelo menos\v100 espécies!\vMal posso acredi-\vtar o quão bom\vvocê se tornou!",
  ["_DexRatingText_Own10To19"] = "Você está no\ncaminho certo! \vPegue a MO CLARÃO\vcom meu ajudante\vna ROTA 2!",
  ["_DexRatingText_Own110To119"] = "Você conseguiu até\nmesmo as formas\vevoluídas dos\vPOKéMON! Super!",
  ["_DexRatingText_Own120To129"] = "Excelente! Troque\ncom amigos para\vconseguir mais!",
  ["_DexRatingText_Own130To139"] = "Exepcional!\nVocê se tornou um\vprofissional!",
  ["_DexRatingText_Own140To149"] = "Não tenho mais o\nque dizer!\vVocê quem é a\vautoridade agora!",
  ["_DexRatingText_Own150To151"] = "Sua POKéDEX\nestá completa!\vParabéns!",
  ["_DexRatingText_Own20To29"] = "Você ainda precisa\nde mais POKéMON!\vTente pegar \vnovas espécies!",
  ["_DexRatingText_Own30To39"] = "Muito bom, você\nse esforçou!\vFale com meu aju-\vdante na ROTA 11\vpara receber um\vLOCALIZADOR!",
  ["_DexRatingText_Own40To49"] = "Indo muito bem!\nVá encontrar meu\vajudante quando\vvocê pegar 50!",
  ["_DexRatingText_Own50To59"] = "Você finalmente\npegou pelo menos\v50 espécies! Lem-\vbre-se de pegar\vo COMPART.EXP.\vcom meu ajudante\vna ROTA 15!",
  ["_DexRatingText_Own60To69"] = "Uau! Isso está\nficando cada\vvez melhor!",
  ["_DexRatingText_Own70To79"] = "Muito bom!\nVá pescar alguns\vPOKéMON marinhos!",
  ["_DexRatingText_Own80To89"] = "Maravilhoso!\nVocê gosta de\vcolecionar coisas?",
  ["_DexRatingText_Own90To99"] = "Estou ficando\nimpressionado!\vDeve ter sido uma\vtarefa difícil!",
  ["_DexSeenOwnedText"] = "POKéDEX  Viu:{NUM:wDexRatingNumMonsSeen, 1, 3}\n         Pegou:{NUM:wDexRatingNumMonsOwned, 1, 3}",
  ["_DidNotLearnText"] = "{RAM:wLearnMoveMonName}\nnão aprendeu\v{RAM:wStringBuffer}!",
  ["_DidntAffectText"] = "{TARGET}\nnão se assustou!",
  ["_DiglettDexEntry"] = "Vive a cerca de um\nmetro no subsolo,\nse alimentando das\fraízes de plantas.\nRaramente aparece\nacima da terra",
  ["_DiglettSculptureText"] = "É a escultura\nde um DIGLETT.",
  ["_DiglettsCaveRoute11GamblerText"] = "Que surpresa!\nDIGLETTs cavaram\vesse longo túnel!\fEle vai direto\npara a CIDADE DE\vVIRIDIAN!",
  ["_DiglettsCaveRoute2FishingGuruText"] = "Eu fui até o TÚNEL\nROCHOSO, mas é\vmuito escuro e\ve assustador.\fSe um POKéMON\nusar a técnica de\vCLARÃO isso iria\viluminar tudo...",
  ["_DisabledNoMoreText"] = "{USER}\nvacilou!",
  ["_DittoDexEntry"] = "Capaz de copiar o\ncódigo genético do\ninimigo e, então,\fse transforma\ninstantaneamente\nem sua duplicata",
  ["_DoItText"] = "Ataque! ",
  ["_DoYouWantToNicknameText"] = "Você quer colocar\num apelido no\vseu {RAM:wNameBuffer}?",
  ["_DodrioDexEntry"] = "Usa seus três cé-\nrebros para criar\nplanos complexos.\fEnquanto duas ca-\nbeças dormem, uma\nfica acordada",
  ["_DoduoDexEntry"] = "Uma ave que com-\npensa sua falta de\nvoo com sua alta\fvelocidade com os\npés, deixando lar-\ngas pegadas",
  ["_DoesntAffectMonText"] = "{TARGET}\nnão foi afetada!",
  ["_DragonairDexEntry"] = "Um POKéMON místico\nque exala uma aura\ngentil. Possui a\fhabilidade de\nalterar as condi-\nções climáticas",
  ["_DragoniteDexEntry"] = "Um POKéMON marinho\nraramente visto.\nSua inteligência\fchega a níveis\naltos, comparável\ncom a dos humanos",
  ["_DratiniDexEntry"] = "Há muito tempo\nconsiderado um\nPOKéMON mítico,\faté encontrarem\npequenas colônias\nsubaquáticas",
  ["_DreamWasEatenText"] = "ROCKET teve\no sonho devorado!",
  ["_DroppedHiddenCoinsText"] = "\fOpa! Derrubou\nalgumas fichas!",
  ["_DrowzeeDexEntry"] = "Coloca os inimigos\npara dormir e come\nos seus sonhos.\fOcasionalmente fi-\nca doente se comer\nsonhos ruins",
  ["_DugAHoleText"] = "\ncavou um buraco!",
  ["_DugtrioDexEntry"] = "Uma equipe de DI-\nGLETTs trigêmeos.\nPodem desencadear\fgrandes terremotos\nenquanto cava a \n100km no subsolo",
  ["_EeveeDexEntry"] = "Seu código genéti-\nco é irregular,\ne pode sofrer\fmutações se for\nexposto a alguma\nPEDRA elemental",
  ["_EkansDexEntry"] = "Se move de forma\nfurtiva e silenci-\nosa. Come os ovos\fde aves pequenas,\ncomo PIDGEY, engo-\nlindo-os inteiros",
  ["_ElectabuzzDexEntry"] = "Normalmente encon-\ntrado perto de\nusinas elétricas,\fperambulam e podem\ncausar apagões nas\ncidades próximas",
  ["_ElectrodeDexEntry"] = "Armazena energia\nelétrica sob alta\npressão. Às vezes\fpode explodir por\npouca ou nenhuma\nprovocação",
  ["_ElevatorText"] = "Aqui é o\nelevador.",
  ["_EndUsedMove1Text"] = "!",
  ["_EndUsedMove2Text"] = "!",
  ["_EndUsedMove3Text"] = "!",
  ["_EndUsedMove4Text"] = "!",
  ["_EndUsedMove5Text"] = "!",
  ["_EnemiesOnEverySideText"] = "Inimigos por\ntoda parte!",
  ["_EnemyAppearedText"] = "{RAM:wEnemyMonNick}\napareceu!",
  ["_EnemyMonFaintedText"] = "Inimigo {RAM:wEnemyMonNick}\ndesmaiou!",
  ["_EnemyRanText"] = "Inimigo {RAM:wEnemyMonNick}\nfugiu!",
  ["_EnemysWeakText"] = "Eu escolho você,\n",
  ["_EnoughText"] = "já\nchega! ",
  ["_EvadedAttackText"] = "{TARGET}\nse esquivou desse{SCROLL}ataque!",
  ["_EvolvedText"] = "{RAM:wStringBuffer} evoluiu",
  ["_ExchangeCoinsForPrizesText"] = "Nós trocamos\nsuas fichas\vpor prêmios.",
  ["_ExclamationText"] = "!",
  ["_ExeggcuteDexEntry"] = "Comumente confun-\ndido com ovos.\nQuando incomodado,\feles se juntam ra-\npidamente e atacam\nem conjunto",
  ["_ExeggutorDexEntry"] = "Diz a lenda que em\nraras ocasiões, \numa de suas cabe-\fças cai e continua\na viver, na forma\nde um EXEGGCUTE",
  ["_ExpPointsText"] = "{NUM:wExpAmountGained, 2, 4} Pontos de EXP.!",
  ["_FarfetchdDexEntry"] = "O ramo de cebola\nverde que ele se-\ngura é uma arma.\fEle usa isso como\nse fosse uma espa-\nda de metal",
  ["_FastAsleepText"] = "{USER}\nestá dormindo!",
  ["_FearowDexEntry"] = "Com suas grandes e\nmagníficas asas,\nele pode se manter\fpairando no ar sem\nnunca ter que pou-\nsar e descansar",
  ["_FellAsleepBecameHealthyText"] = "PC caiu no\nsono e recuperou{SCROLL}sua saúde!",
  ["_FellAsleepText"] = "{TARGET}\ncaiu no sono!",
  ["_FellText"] = "!",
  ["_FightingDojoBetterNotGetGreedyText"] = "Melhor não ser\nganancioso...",
  ["_FightingDojoBlackbelt1AfterBattleText"] = "Espere só até você\nver nosso Mestre!\fEu sou peixe pe-\nqueno perto dele!",
  ["_FightingDojoBlackbelt1BattleText"] = "Hoargh! Tire os\nseus sapatos!",
  ["_FightingDojoBlackbelt1EndBattleText"] = "Eu\ndesisto!",
  ["_FightingDojoBlackbelt2AfterBattleText"] = "Nosso Mestre é um\nlutador profis-\vsional!",
  ["_FightingDojoBlackbelt2BattleText"] = "Ouvi dizer que vo-\ncê é bom! Mostre!",
  ["_FightingDojoBlackbelt2EndBattleText"] = "Juiz!\n1 ponto!",
  ["_FightingDojoBlackbelt3AfterBattleText"] = "A única coisa que\nnos assusta são\vpoderes psíquicos!",
  ["_FightingDojoBlackbelt3BattleText"] = "Nenhuma coisa dura\nme assusta!\fEu quebro pedras\ncomo treinamento!",
  ["_FightingDojoBlackbelt3EndBattleText"] = "Auu!\nMachuquei a mão!",
  ["_FightingDojoBlackbelt4AfterBattleText"] = "Os melhores luta-\ndores do mundo\vtreinam aqui.",
  ["_FightingDojoBlackbelt4BattleText"] = "Uhah!\fVocê está invadin-\ndo nosso DOJO DE\vARTES MARCIAIS!",
  ["_FightingDojoBlackbelt4EndBattleText"] = "Urgh!\nEu desisto!",
  ["_FightingDojoHitmonchanPokeBallText"] = "Você vai querer o\npunho de pistão\vHITMONCHAN?",
  ["_FightingDojoHitmonleePokeBallText"] = "Você vai querer o\ngrande chutador\vHITMONLEE?",
  ["_FightingDojoKarateMasterDefeatedText"] = "Hwa!\nArrgh! Derrotado!",
  ["_FightingDojoKarateMasterIWillGiveYouAPokemonText"] = "Eu perdi, de\nfato!\fMas eu lhe\nimploro, não leve\vo nosso emblema\vcomo seu troféu!\fEm troca, eu lhe\ndarei um POKéMON\vlutador premiado!\fEscolha qual você\nmais gostar!",
  ["_FightingDojoKarateMasterStayAndTrainWithUsText"] = "Ho!\fFique e treine\ncaratê conosco!",
  ["_FightingDojoKarateMasterText"] = "Arrrg!\fEu sou o MESTRE\nDO CARATÊ! Eu sou\vo LÍDER daqui!\fVocê veio nos\ndesafiar? Não\vespere piedade!\fHiaaaa!",
  ["_FightingDojoText"] = "DOJO DE ARTES\nMARCIAIS",
  ["_FileDataDestroyedText"] = "Obrigada,\namigo!",
  ["_FireDefrostedText"] = "{TARGET}\nfoi queimado!",
  ["_FlareonDexEntry"] = "Enquanto armazena\nenergia térmica em\nseu corpo, sua\ftemperatura pode\natingir mais de\n900 graus Celsius",
  ["_FlashLightsAreaText"] = "Um CLARÃO brilhoso\niluminou a área!",
  ["_FlewUpHighText"] = "\nvoou para o alto!",
  ["_FlinchedText"] = "",
  ["_FluteWokeUpText"] = "POKéMON dormindo\nacordaram.",
  ["_ForgotAndText"] = "\f{RAM:wLearnMoveMonName} esqueceu\n{RAM:wNameBuffer}!\fE...",
  ["_FoundHiddenCoins2Text"] = "{PLAYER} encontrou\n{NUM:hCoins, 2 | LEADING_ZEROES | LEFT_ALIGN} fichas!",
  ["_FoundHiddenCoinsText"] = "{PLAYER} encontrou\n{NUM:hCoins, 2 | LEADING_ZEROES | LEFT_ALIGN} fichas!",
  ["_FoundHiddenItemText"] = "{PLAYER} encontrou\n{RAM:wNameBuffer}!",
  ["_FoundItemText"] = "{PLAYER} encontrou\n{RAM:wStringBuffer}!",
  ["_FrozenText"] = "",
  ["_FuchsiaBillsGrandpasHouseBillsGrandpaText"] = "Hmm? Você conheceu\no BILL?\fEle é meu neto!\fEle sempre gostou\nde colecionar\vcoisas, desde\vcriancinha!",
  ["_FuchsiaBillsGrandpasHouseMiddleAgedWomanText"] = "O DIRETOR da ZONA\nDO SAFARI pode\vser velho, mas\vé muito ativo!\fEntretanto, todos\nos seus dentes\vsão falsos.",
  ["_FuchsiaBillsGrandpasHouseYoungsterText"] = "BILL arquiva suas\ninformações sobre\vPOKéMON raros em\vseu computador.\fEle te mostrou?",
  ["_FuchsiaCityChanseySignText"] = "Nome: CHANSEY\fCapture uma se\ntiver a chance.",
  ["_FuchsiaCityErikText"] = "ERIK: Onde está a\nSARA? Eu avisei\vpara esperar aqui.",
  ["_FuchsiaCityFossilSignKabutoText"] = "Nome: KABUTO\fUm POKéMON que\nfoi ressuscitado\va partir de um\vfóssil.",
  ["_FuchsiaCityFossilSignOmanyteText"] = "Nome: OMANYTE\fUm POKéMON que\nfoi ressuscitado\va partir de um\vfóssil.",
  ["_FuchsiaCityFossilSignUndeterminedText"] = "...",
  ["_FuchsiaCityGamblerText"] = "A ZONA DO SAFARI\ntem um zoológico\vna frente da sua\ventrada.\fNa parte de trás é\nonde acontece a\vcompetição de\vcapturar POKéMON.",
  ["_FuchsiaCityGymSignText"] = "GINÁSIO POKéMON\nDE FUCHSIA\vLÍDER: KOGA\fO Venenoso\nMestre Ninja",
  ["_FuchsiaCityKangaskhanSignText"] = "Nome: KANGASKHAN\fUm POKéMON mater-\nnal que cuida do\vseu filhote em\vuma bolsa em sua\vbarriga.",
  ["_FuchsiaCityLaprasSignText"] = "Nome: LAPRAS\fConhecido como\no rei dos mares.",
  ["_FuchsiaCityPokecenterGuyText"] = "Se você está estu-\ndando os POKéMON,\ventão vá visitar\va ZONA DO SAFARI.\fLá tem todo tipo\nde POKéMON raro.",
  ["_FuchsiaCityPokemonText"] = "!",
  ["_FuchsiaCitySafariGameSignText"] = "PASSEIO DE SAFARI\nPegue todos...\vSe puder!",
  ["_FuchsiaCitySafariZoneSignText"] = "PARAÍSO POKéMON!\nZONA DO SAFARI!",
  ["_FuchsiaCitySignText"] = "CIDADE DE FUCHSIA\nContemple! Ela é\vRosa de Paixão!",
  ["_FuchsiaCitySlowpokeSignText"] = "Nome: SLOWPOKE\fAmigável e também\nmuito vagaroso.",
  ["_FuchsiaCityVoltorbSignText"] = "Nome: VOLTORB\fÉ igualzinho a\numa POKé BOLA.",
  ["_FuchsiaCityWardensHomeSignText"] = "CASA do DIRETOR\nda ZONA DO SAFARI",
  ["_FuchsiaCityYoungster1Text"] = "Você foi na compe-\ntição de SAFARI?\vAlguns POKéMON só\vpodem ser captu-\vrados lá.",
  ["_FuchsiaCityYoungster2Text"] = "Parece ter um item\nali, mas na ver-\vdade é um POKéMON.",
  ["_FuchsiaGoodRodHouseFishingGuruHowAreTheFishText"] = "Olá, meu bom\namigo {PLAYER}!\fOs peixes estão\nfisgando muito?",
  ["_FuchsiaGoodRodHouseFishingGuruNoRoomText"] = "Ah, não!\fVocê está sem\nespaço para\vmeu presente!",
  ["_FuchsiaGoodRodHouseFishingGuruReceivedGoodRodText"] = "BOA! Eu gostei\ndo seu estilo!\fPegue isso e vá\npescar, meu bom!\f{PLAYER} recebeu\numa {RAM:wStringBuffer}!",
  ["_FuchsiaGoodRodHouseFishingGuruText"] = "Eu sou o irmão\nmais velho do\vGURU DA PESCARIA!\fEu simplesmente\naaaaamo pescar!\fVocê gosta\nde pescar?",
  ["_FuchsiaGoodRodHouseFishingGuruThatsSoDisappointingText"] = "Ah... Isso é tão\ndecepcionante...",
  ["_FuchsiaGymGymGuideBeatKogaText"] = "É incrível como\nninjas podem ser\vaterrorizantes,\vmesmo agora.",
  ["_FuchsiaGymGymGuideChampInMakingText"] = "E aí, campeão em\nformação!\fO GINÁSIO DE\nFUCHSIA está\vcheio de paredes\vinvisíveis pelo\vcaminho.\fKOGA parece estar\nperto, mas o cami-\vnho até ele está\vbloqueado!\fVocê precisa en-\ncontrar falhas na\vparede para poder\vchegar até ele!",
  ["_FuchsiaGymKogaBeforeBattleText"] = "KOGA: Fwahahaha!\fUma mera criança\ncomo você ousa\vme desafiar?\fMuito bem, irei te\nmostrar o verda-\vdeiro terror de\vum mestre ninja!\fAgora você sentirá\no desespero das\vtécnicas de sono\ve envenenamento!",
  ["_FuchsiaGymKogaPostBattleAdviceText"] = "Quando são afeta-\ndos pelo TÓXICO,\vPOKéMON sofrerão\vcada vez mais\vconforme a luta\vprogride!\fIsso com certeza\naterrorizará os\vadversários!",
  ["_FuchsiaGymKogaReceivedSoulBadgeText"] = "Humph!\nVocê provou o\vseu valor!\fAqui! Fique com a\nINSÍGNIA ALMA!",
  ["_FuchsiaGymKogaReceivedTM06Text"] = "{PLAYER} recebeu\n{RAM:wStringBuffer}!",
  ["_FuchsiaGymKogaSoulBadgeInfoText"] = "Agora que você tem\na INSÍGNIA ALMA,\va DEFESA de todos\vos seus POKéMON\virá aumentar!\fEla também permite\nque você use a MO\vSURFAR fora das\vbatalhas!\fAh! Fique com\nisso também!",
  ["_FuchsiaGymKogaTM06ExplanationText"] = "\fMT06 contém\nTÓXICO!\fÉ uma técnica\nsecreta de mais\vde 400 anos!",
  ["_FuchsiaGymKogaTM06NoRoomText"] = "Abra espaço para\nisso, garoto!",
  ["_FuchsiaGymRocker1AfterBattleText"] = "Então, você mistu-\nra força bruta e\vcérebro?\vBoa estratégia!",
  ["_FuchsiaGymRocker1BattleText"] = "Força não é a\nchave do sucesso\vPOKéMON!\fÉ a estratégia!\fEu vou te mostrar\ncomo a estratégia\vpode derrotar a\vforça bruta!",
  ["_FuchsiaGymRocker1EndBattleText"] = "Quê?\nExtraordinário!",
  ["_FuchsiaGymRocker2AfterBattleText"] = "Vou continuar meu\ntreinamento com\vKOGA, meu mestre\vninja!",
  ["_FuchsiaGymRocker2BattleText"] = "Eu queria virar\num ninja, então\vme juntei a esse\vGINÁSIO!",
  ["_FuchsiaGymRocker2EndBattleText"] = "Já\nchega pra mim!",
  ["_FuchsiaGymRocker3AfterBattleText"] = "Eu gosto das téc-\nnicas de sono e\vveneno, pois elas\vduram até depois\vda batalha!",
  ["_FuchsiaGymRocker3BattleText"] = "Vamos ver se você\nderrota minhas\vtécnicas secretas!",
  ["_FuchsiaGymRocker3EndBattleText"] = "Você\nme enganou!",
  ["_FuchsiaGymRocker4AfterBattleText"] = "Você me impres-\nsionou! Aqui vai\vuma dica!\fOlhe bem de perto\npara ver as fa-\vlhas da parede\vinvisível!",
  ["_FuchsiaGymRocker4BattleText"] = "Pare aí mesmo!\fNossas paredes\ninvisíveis estão\vte frustrando?",
  ["_FuchsiaGymRocker4EndBattleText"] = "Uou!\nVocê é bom!",
  ["_FuchsiaGymRocker5AfterBattleText"] = "Ainda tenho muito\no que aprender!",
  ["_FuchsiaGymRocker5BattleText"] = "Eu também estudo\nos métodos ninja\vdo mestre KOGA!\fOs ninjas têm uma\nlonga história\vusando animais!",
  ["_FuchsiaGymRocker5EndBattleText"] = "Au!",
  ["_FuchsiaGymRocker6AfterBattleText"] = "Mestre KOGA veio\nde uma longa li-\vnhagem de ninjas!\fE você, é descen-\ndente do quê?",
  ["_FuchsiaGymRocker6BattleText"] = "Mestre KOGA veio\nde uma longa li-\vnhagem de ninjas!\fE você, é descen-\ndente do quê?",
  ["_FuchsiaGymRocker6EndBattleText"] = "Der-\nrubei as bolas!",
  ["_FuchsiaMartCooltrainerFText"] = "Você já usou um\nVELOCIDADE X?\vEle aumenta a ve-\vlocidade dos seus\vPOKéMON durante\vuma batalha!",
  ["_FuchsiaMartMiddleAgedManText"] = "Você já tem uma\nbandeira da ZONA\vDO SAFARI?\fQue tal cartas\nou calendários?",
  ["_FuchsiaMeetingRoomSafariZoneWorker1"] = "Nós apelidamos o\nDIRETOR daqui\vde SLOWPOKE.\fEle tem um olhar\nvago, igual o de\vum SLOWPOKE.",
  ["_FuchsiaMeetingRoomSafariZoneWorker2"] = "SLOWPOKE tem muito\nconhecimento\vsobre POKéMON!\fEle até possui\nalguns fósseis\vde POKéMON raros\ve extintos!",
  ["_FuchsiaMeetingRoomSafariZoneWorker3"] = "SLOWPOKE passou\npor aqui, mas eu\vnão consegui en-\vtender o que ele\vdizia.\fAcho que ele tem\nalgum problema\vna sua fala.",
  ["_FuchsiaPokecenterCooltrainerFText"] = "Ao oeste da CIDADE\nDE VIRIDIAN, tem\vuma pequena rota.\fEla leva até o\nQuartel General\vda LIGA POKéMON.\vEles controlam o\vregistro de todos\vos treinadores.",
  ["_FuchsiaPokecenterRockerText"] = "Você não pode ven-\ncer com apenas um\vPOKéMON forte.\fÉ difícil, mas\nprecisa treiná-\vlos igualmente.",
  ["_FullHealText"] = "A saúde de\n{RAM:wNameBuffer} voltou!",
  ["_FullyParalyzedText"] = "",
  ["_GainedText"] = "{RAM:wNameBuffer} ganhou\n",
  ["_GameCornerBeauty1Text"] = "Bem-vindo!\fVocê pode trocar\nsuas fichas por\vprêmios incríveis\vna porta ao lado.",
  ["_GameCornerBeauty2Text"] = "Eu acho que cada\nmáquina dá resul-\vtados diferentes.",
  ["_GameCornerClerk1CantAffordTheCoinsText"] = "Você não tem um\nPORTA-FICHAS!",
  ["_GameCornerClerk1CoinCaseIsFullText"] = "Opa! Seu PORTA-\nFICHAS está cheio.",
  ["_GameCornerClerk1DoYouNeedSomeGameCoinsText"] = "Bem-vindo ao\nCASSINO ROCKET!\fEstá precisando de\nalgumas fichas?\fCada 50 fichas\ncustam ¥1000. Vai\vquerer algumas?",
  ["_GameCornerClerk1DontHaveCoinCaseText"] = "Você não tem um\nPORTA-FICHAS!",
  ["_GameCornerClerk1PleaseComePlaySometimeText"] = "Opa! Seu PORTA-\nFICHAS está cheio.",
  ["_GameCornerClerk1ThanksHereAre50CoinsText"] = "Obrigado! Aqui\nestão 50 fichas!",
  ["_GameCornerClerk2INeedMoreCoinsText"] = "Droga! Eu preciso\nde mais fichas\vpara o POKéMON\vque eu quero!",
  ["_GameCornerClerk2Received20CoinsText"] = "{PLAYER} recebeu\n20 fichas!",
  ["_GameCornerClerk2WantSomeCoinsText"] = "O que foi? Quer\nalgumas fichas?",
  ["_GameCornerClerk2YouHaveLotsOfCoinsText"] = "Você já tem muitas\nfichas!",
  ["_GameCornerCoinCaseText"] = "PORTA-FICHAS\né necessário!",
  ["_GameCornerFishingGuruDontNeedMyCoinsText"] = "Você não precisa\ndas minhas fichas!",
  ["_GameCornerFishingGuruReceived10CoinsText"] = "{PLAYER} recebeu\n10 fichas!",
  ["_GameCornerFishingGuruWantToPlayText"] = "Garoto, você quer\njogar?",
  ["_GameCornerFishingGuruWinsComeAndGoText"] = "A vitória vai e\nvem.",
  ["_GameCornerGamblerText"] = "Isso me assusta!\nÉ muito fácil\vficar viciado!",
  ["_GameCornerGentlemanCloselyWatchTheReelsText"] = "O truque é olhar\nela girando bem\vde pertinho!",
  ["_GameCornerGentlemanReceived20CoinsText"] = "{PLAYER} recebeu\n20 fichas!",
  ["_GameCornerGentlemanThrowingMeOffText"] = "Hein, o quê? Você\nestá me distrain-\vdo! Aqui, pegue\vessas fichas, xô!",
  ["_GameCornerGentlemanYouGotYourOwnCoinsText"] = "Você tem suas\npróprias fichas!",
  ["_GameCornerGymGuideChampInMakingText"] = "Ei!\fVocê tem coisas\nmelhores para\vfazer, campeão\vem treinamento!\fA LÍDER DO GINÁSIO\nda CIDADE CELADON\vse chama ERIKA!\vEla usa POKéMON\vdo tipo planta!\fEla pode parecer\ninofensiva, mas\vnão se engane!",
  ["_GameCornerGymGuideTheyOfferRarePokemonText"] = "Eles oferecem uns\nPOKéMON raros em\vtroca de fichas.\fMas eu nunca\nganho!",
  ["_GameCornerMiddleAgedMan1Text"] = "Mantenha em\nsegredo.\fMas há um rumor\nque esse local é\vcontrolado pela\vEQUIPE ROCKET!",
  ["_GameCornerMiddleAgedWomanText"] = "Estou cheia de\nsorte hoje!",
  ["_GameCornerNoCoinsText"] = "Você não tem\nnenhuma ficha!",
  ["_GameCornerOopsForgotCoinCaseText"] = "Opa! Você não tem\num PORTA-FICHAS!",
  ["_GameCornerOutOfOrderText"] = "Sem fichas\nsuficientes!",
  ["_GameCornerOutToLunchText"] = "Mais uma\ntentativa?",
  ["_GameCornerPosterSwitchBehindPosterText"] = "Ei!\fUm botão atrás do\ncartaz!?\vVamos apertar!",
  ["_GameCornerPrizeRoomBaldingGuyText"] = "Eu quero muito\num PORYGON!\fMas é difícil\nvencer naqueles\vcaça-níqueis!",
  ["_GameCornerPrizeRoomGamblerText"] = "Eu tirei a sorte\ngrande hoje!",
  ["_GameCornerRocketAfterBattleText"] = "Nosso esconderijo\npode ser desco-\vberto! É melhor\veu avisar o CHEFE!",
  ["_GameCornerRocketBattleEndText"] = "Droga!",
  ["_GameCornerRocketImGuardingThisPosterText"] = "Eu estou vigiando\nesse cartaz!\vVá embora, senão!",
  ["_GameCornerSomeonesKeysText"] = "se alinharam!\nGanhou {RAM:wStringBuffer} fichas!",
  ["_GameOverText"] = "RÁDIO: \nSeu SAFARI acabou!",
  ["_GameSavedText"] = "{PLAYER} salvou\no jogo!",
  ["_GastlyDexEntry"] = "Quase invisível,\nesse POKéMON gaso-\nso envolve sua\fpresa e a coloca\npara dormir sem\nque ela perceba",
  ["_GengarDexEntry"] = "Sob a lua cheia,\nesse POKéMON gosta\nde imitar a sombra\fdas pessoas para\nentão rir quando\nelas se assustam",
  ["_GeodudeDexEntry"] = "Encontrado em cam-\npos e montanhas.\nConfundido por\frochas, as pessoas\ncomumente pisam ou\ntropeçam neles",
  ["_GetDexRatedText"] = "Quer avaliar a\nsua POKéDEX?",
  ["_GetOutText"] = "FANTASMA: Saia...\nSaia daqui...",
  ["_GetmText"] = "Pega! ",
  ["_GettingPumpedText"] = "{USER}\nestá mais focado!",
  ["_GhostCantBeIDdText"] = "Volte!",
  ["_GloomDexEntry"] = "O fluído que \nescorre de sua\nboca não é baba,\fé nectar, usado\npara atrair as\nsuas presas",
  ["_GoText"] = "Vai! ",
  ["_GolbatDexEntry"] = "Quando ataca, não\nvai parar de sugar\nenergia da vítima\fmesmo que fique\npesado demais para\nconseguir voar",
  ["_GoldeenDexEntry"] = "Sua nadadeira tra-\nseira ondula como\num elegante vesti-\fdo de gala, lhe\ndando o apelido de\na Rainha d'água",
  ["_GolduckDexEntry"] = "Comumente visto\nnadando elegante-\nmente na margem de\flagos. Às vezes é\nconfundido com o\nmitológico Kappa",
  ["_GolemDexEntry"] = "Seu corpo de pedra\né extremamente du-\nro e resistente.\fPode facilmente\naguentar explosões\nde dinamite",
  ["_GoodText"] = "bom!",
  ["_GotAwayText"] = "Conseguiu fugir\nem segurança!",
  ["_GotMapText"] = "{PLAYER} recebeu\num {RAM:wStringBuffer}!",
  ["_GotMonText"] = "{PLAYER} recebeu\n{RAM:wNameBuffer}!",
  ["_GotOffBicycleText1"] = "{PLAYER} desceu da",
  ["_GotOffBicycleText2"] = "{RAM:wStringBuffer}.",
  ["_GotOnBicycleText1"] = "{PLAYER} subiu na",
  ["_GotOnBicycleText2"] = "{RAM:wStringBuffer}!",
  ["_GravelerDexEntry"] = "Rola ladeira abai-\nxo para se mover.\nPassa por cima de\fqualquer obstáculo\nsem desviar ou\nperder velocidade",
  ["_GreatlyFellText"] = "{SCROLL}bastante",
  ["_GreatlyRoseText"] = "{SCROLL}bastante",
  ["_GrewLevelText"] = "{RAM:wNameBuffer} subiu\npara o nível {NUM:wCurEnemyLevel, 1, 3}!",
  ["_GrimerDexEntry"] = "Aparece em áreas\nimundas. Sobrevive\nsugando a lama po-\fluída que é despe-\njada por fábricas\ne indústrias",
  ["_GroundRoseText"] = "!",
  ["_GrowlitheDexEntry"] = "É muito territori-\nalista. Costuma\nlatir e morder\fpara repelir os\nintrusos de seu\nterritório",
  ["_GyaradosDexEntry"] = "Raramente visto na\nnatureza. Grande e\nferoz, é capaz de\fdestruir cidades\ninteiras durante\nataques de fúria",
  ["_GymStatueText1"] = "{RAM:wGymCityName}\nGINÁSIO POKéMON\vLÍDER: {RAM:wGymLeaderName}\fVENCEDORES:\n{RIVAL}",
  ["_GymStatueText2"] = "{RAM:wGymCityName}\nGINÁSIO POKéMON\vLÍDER: {RAM:wGymLeaderName}\fVENCEDORES:\n{RIVAL}\v{PLAYER}",
  ["_HMCantDeleteText"] = "Não pode esquecer\ntécnicas de MO!",
  ["_HallOfFameOakText"] = "CARVALHO: Er-hem!\nMeus parabéns,\v{PLAYER}!\fAqui nesse andar\né o MURAL DA FAMA\vPOKéMON!\fAqui os campeões\nda LIGA POKéMON\vsão honrados por\vseus feitos!\fE seus POKéMON\ntambém serão\vgravados no\vMURAL DA FAMA!\f{PLAYER}! Você se\nesforçou bastante\vpara se tornar o\vmais novo campeão\vda LIGA POKéMON!\fMeus parabéns, \n{PLAYER}, agora\vvocê e seus\vPOKéMON estão no\vMURAL DA FAMA!",
  ["_HasSubstituteText"] = "PC já tem\num SUBSTITUTO!",
  ["_HaunterDexEntry"] = "Por causa de sua\nhabilidade de \natravessar paredes\fsólidas, é dito\nque veio de outra\ndimensão",
  ["_HereYouGoText"] = "Aqui está!",
  ["_HiddenItemBagFullText"] = "Mas {PLAYER} não\ntem espaço para\vmais itens!",
  ["_HisNameIsText"] = "É verdade! Eu me\nlembrei agora!\fO nome dele\né {RIVAL}!",
  ["_HitWithRecoilText"] = "PC se\nferiu pelo recuo!",
  ["_HitXTimesText"] = "Acertou {NUM:wEnemyNumHits, 1, 1} vezes!",
  ["_HitmonchanDexEntry"] = "Enquanto aparenta\nnão estar fazendo\nnada, dispara seus\fsocos tão rápidos\nque é impossível\nde se ver",
  ["_HitmonleeDexEntry"] = "Quando está com\npressa, alonga\nsuas pernas.\fCorre suavemente\nnum galope de pas-\nsos extra longos",
  ["_HookedMonAttackedText"] = "O FANTASMA foi\nidentificado com{SCROLL}o SILPHOSCÓPIO!",
  ["_HorseaDexEntry"] = "Conhecido por der-\nrubar insetos em\npleno voo, com\fseu preciso jato\nde tinta. Faz seu\nninho em corais",
  ["_HurtByBurnText"] = "A queimadura\ncontinua a ferir!",
  ["_HurtByLeechSeedText"] = "A semente sugou\nenergia vital de\vPC!",
  ["_HurtByPoisonText"] = "O envenenamento\ncontinua a ferir!",
  ["_HurtItselfText"] = "{USER}\nnão está mais{SCROLL}inabilitado!",
  ["_HypnoDexEntry"] = "Quando fixa seu\nolhar em um inimi-\ngo, usa uma mistu-\fra de ataques psí-\nquicos, como CON-\nFUSãO e HIPNOSE",
  ["_IceHealText"] = "{RAM:wNameBuffer}\ndescongelou!",
  ["_IgnoredOrdersText"] = "{RAM:wBattleMonNick}\nignorou as ordens!",
  ["_IndigoPlateauHQText"] = "PLANALTO ÍNDIGO\nQG DA LIGAPOKéMON",
  ["_IndigoPlateauLobbyCooltrainerFText"] = "A partir daqui,\nvocê enfrentará a\vELITE DOS QUATRO\vum por um!\fSe você vencer,\na porta para o\vpróximo treinador\vse abrirá!\vBoa Sorte!",
  ["_IndigoPlateauLobbyGymGuideText"] = "E aí! Campeão\nem construção!\fNa LIGA POKéMON,\nvocê precisará\venfrentar toda a\vELITE DOS QUATRO\vem sequência.\fSe você perder,\nterá que começar\vtudo de novo!\vE é isso!\vVai nessa!",
  ["_IndigoPlateauStatuesText1"] = "PLANALTO ÍNDIGO",
  ["_IndigoPlateauStatuesText2"] = "O último objetivo\ndos treinadores!\vQG - LIGA POKéMON",
  ["_IndigoPlateauStatuesText3"] = "A mais alta\nautoridade em\vPOKéMON\vQG - LIGA POKéMON",
  ["_IntoText"] = "\npara {RAM:wNameBuffer}!",
  ["_IntroducePlayerText"] = "Pero primero dime\ncómo te llamas.",
  ["_IntroduceRivalText"] = "Este es mi nieto.\nÉl ha sido tu\vrival desde que\vérais niños.\f...Mmm, ¿Podrías\nrecordarme su\vnombre?",
  ["_IsConfusedText"] = "PC pre-\ncisa recarregar!",
  ["_IsEvolvingText"] = "O quê? {RAM:wStringBuffer}\nestá evoluindo!",
  ["_IsFrozenText"] = "{USER}\nestá congelado!",
  ["_IsItOKToTossItemText"] = "Quer jogar fora\n{RAM:wStringBuffer}?",
  ["_IsUnaffectedText"] = "{TARGET}\nresistiu!",
  ["_ItemUseBallText00"] = "Ele se esquivou\nda BOLA!\fNão pode capturar\nesse POKéMON!",
  ["_ItemUseBallText01"] = "Você errou o\nPOKéMON!",
  ["_ItemUseBallText02"] = "Droga! O POKéMON\nse libertou!",
  ["_ItemUseBallText03"] = "Ahh! Parecia que\ntinha capturado!",
  ["_ItemUseBallText04"] = "Puxa! Estava\ntão perto!",
  ["_ItemUseBallText05"] = "É isso aí!\n{RAM:wEnemyMonNick} foi\vcapturado!",
  ["_ItemUseBallText06"] = "Sua POKéDEX foi\natualizada com\vnovas informações\vsobre {RAM:wEnemyMonNick}!",
  ["_ItemUseBallText07"] = "{RAM:wBoxMonNicks} foi\ntransferido para\vo PC do BILL!",
  ["_ItemUseBallText08"] = "{RAM:wBoxMonNicks} foi\ntransferido para\vo PC de alguém!",
  ["_ItemUseNoEffectText"] = "Não vai fazer\nnenhum efeito.",
  ["_ItemUseNotTimeText"] = "CARVALHO: Não\né hora de usar\visso, {PLAYER}!",
  ["_ItemUseNotYoursToUseText"] = "Não é seu para\nvocê usar!",
  ["_ItemUseText001"] = "{PLAYER} usou",
  ["_ItemUseText002"] = "{RAM:wStringBuffer}!",
  ["_ItemWasStoredText"] = "{RAM:wNameBuffer} foi\narmazenado via PC.",
  ["_ItemfinderFoundItemText"] = "Isso! LOCALIZADOR\nencontrou algo\vnos arredores.",
  ["_ItemfinderFoundNothingText"] = "Nada! LOCALIZADOR\nnão achou nada.",
  ["_ItemsCantBeUsedHereText"] = "Itens não podem\nser usados aqui.",
  ["_ItsABiteText"] = "Opa!\nFisgou algo!",
  ["_IvysaurDexEntry"] = "Quando o bulbo em\nsuas costas cresce\ndemais, ele perde\fa capacidade de\nficar de pé sobre\nas patas de trás",
  ["_JigglypuffDexEntry"] = "Quando seus olhos\nenormes se ilumi-\nnam, uma melodia\fsuave e misteriosa\nembala seus inimi-\ngos e os adormece",
  ["_JolteonDexEntry"] = "Ele acumula íons\nnegativos da\natmosfera para\fdisparar raios\nelétricos de mais\nde 10000 volts",
  ["_JustAMomentText"] = "Só um momento.",
  ["_JynxDexEntry"] = "Move seus quadris\nde forma sedutora\nenquanto anda. Faz\fcom que as pessoas\ndancem em uníssono\na seus movimentos",
  ["_KabutoDexEntry"] = "Um POKéMON que foi\nressuscitado de\num fóssil encon-\ftrado onde um dia\njá foi o fundo dos\noceanos antigos",
  ["_KabutopsDexEntry"] = "Sua forma lisa é\nperfeita para na-\ndar. Usa as garras\fpara fatiar presas\ne drenar os seus\nfluídos corporais",
  ["_KabutopsFossilText"] = "KABUTOPS\nFossilizado\fUm POKéMON raro\ne primitivo.",
  ["_KadabraDexEntry"] = "Emite ondas-alfa\nespectrales de su\ncuerpo que causan\njaquecas a todo\naquel que se\nacerca.",
  ["_KakunaDexEntry"] = "Praticamente inca-\npaz de se mover,\nesse POKéMON pode\fapenas endurecer o\nseu casulo como\nforma de proteção",
  ["_KangaskhanDexEntry"] = "Antes de completar\n3 anos de idade,\nseu filhote\fraramente sai\nde sua bolsa\nprotetora",
  ["_KeptGoingAndCrashedText"] = "{USER}\nprosseguiu{SCROLL}e caiu!",
  ["_KinglerDexEntry"] = "Sua pinça maior\npossui 10000CV\nde esmagamento.\fEntretanto, o seu\ntamanho a torna de\ndifícil manuseio",
  ["_KoffingDexEntry"] = "Como ele armazena\ndiversos tipos de\ngases tóxicos em\fseu corpo, pode\nexplodir a qual-\nquer momento",
  ["_KrabbyDexEntry"] = "Suas pinças não\nsão apenas podero-\nsas armas, mas\ftambém são usadas\npara se equilibrar\nenquanto anda",
  ["_LancesRoomLanceAfterBattleText"] = "Eu ainda não con-\nsigo acreditar\vque meus dragões\vperderam para\vvocê, {PLAYER}!\fVocê é o campeão\nda LIGA POKéMON!\f...Ou, teria sido,\nmas você ainda\vterá que enfren-\vtar mais um desa-\vfio pela frente.\fVocê terá que\nencarar outro\vtreinador!\vSeu nome é...\f{RIVAL}!\nEle derrotou a\vELITE DOS QUATRO\vantes de você!\fEle é o verdadeiro\ncampeão atual da\vLIGA POKéMON!",
  ["_LancesRoomLanceBeforeBattleText"] = "Ah! Eu ouvi\nmuito sobre\vvocê, {PLAYER}!\fEu lidero a ELITE\nDOS QUATRO! Você\vpode me chamar de\vLANCE, o treina-\vdor de dragões!\fVocê sabe que os\ndragões são\vPOKéMON míticos!\fSão difíceis de\ncapturar e criar,\vmas seus poderes\vsão superiores!\fSão virtualmente\nindestrutíveis!\fBem, já está pron-\nto para perder?\fSeu desafio à LIGA\nPOKéMON termina\vcomigo, {PLAYER}!",
  ["_LancesRoomLanceEndBattleText"] = "É isso!\fEu odeio ter que\nadmitir, mas você\vrealmente é um\vmestre POKéMON!",
  ["_LaprasDexEntry"] = "Um POKéMON que foi\ncaçado até quase a\nextinção. Eles\fpodem transportar\npessoas através\nda água",
  ["_LavenderCuboneHouseBrunetteGirlGhostIsGoneText"] = "O FANTASMA da\nTORRE POKéMON foi\vembora!\fAlguém deve ter\nacalmado sua alma\vperturbada!",
  ["_LavenderCuboneHouseBrunetteGirlPoorCubonesMotherText"] = "Eu odeio aqueles\nmalditos ROCKETs!\fA pobre mãe desse\nCUBONE...\fFoi morta quando\ntentava fugir da\vEQUIPE ROCKET!",
  ["_LavenderCuboneHouseCuboneText"] = "CUBONE: Kyarugoo!",
  ["_LavenderMartBaldingGuyText"] = "Estou procurando\npor itens que\vaumentam os\vatributos dos\vPOKéMON durante\vuma só batalha.\fVELOCIDADE X, ATA-\nQUE X, DEFESA X e\vESPECIAL X são os\vque eu procuro.\fSabe onde posso\ncomprá-los?",
  ["_LavenderMartCooltrainerMNuggetText"] = "Achei uma PEPITA\nnas montanhas.\fPensei que era\ninútil, mas eu\vvendi por ¥5000!",
  ["_LavenderMartCooltrainerMReviveText"] = "Conhece o item\nREVIVER? Ele rea-\vnima um POKéMON\vque desmaiou!",
  ["_LavenderPokecenterGentlemanText"] = "A EQUIPE ROCKET\nvai topar tudo\vpor dinheiro!",
  ["_LavenderPokecenterGuyText"] = "Os CUBONEs vestem\ncaveiras, não é?\fAs pessoas devem\npagar caro por um!",
  ["_LavenderPokecenterLittleGirlText"] = "Eu vi a mamãe do\nCUBONE morrendo\vao tentar escapar\vda EQUIPE ROCKET!",
  ["_LavenderTownCooltrainerMText"] = "Essa cidade é um\nconhecido local\vde sepultamento\vpara os POKéMON.\fServiços fúnebres\nsão realizados na\vTORRE POKéMON.",
  ["_LavenderTownLittleGirlDoYouBelieveInGhostsText"] = "Você acredita em\nFANTASMAS?",
  ["_LavenderTownLittleGirlHaHaGuessNotText"] = "Hahaha, eu também\nnão acredito.\fEssa mão branca\nno seu ombro,\vnão é real.",
  ["_LavenderTownLittleGirlSoThereAreBelieversText"] = "Sério? Então há\nquem acredite...",
  ["_LavenderTownPokemonHouseSignText"] = "CASA POKéMON DE\nATENÇÃO VOLUNTÁRIA",
  ["_LavenderTownPokemonTowerSignText"] = "Que as Almas dos\nPOKéMON Possam\vDescansar em Paz\vTORRE POKéMON",
  ["_LavenderTownSignText"] = "CIDADE DE LAVENDER\nPúrpura de Nobreza",
  ["_LavenderTownSilphScopeSignText"] = "Novo SILPHOSCÓPIO!\fFaz o Invisível\nFácil de Ver!\fSILPH CO.",
  ["_LavenderTownSuperNerdText"] = "FANTASMAs aparecem\nna TORRE POKéMON.\fEu acho que são os\nespíritos dos\vPOKéMON que os\vROCKETs mataram.",
  ["_LearnedMove1Text"] = "{RAM:wLearnMoveMonName} aprendeu\n{RAM:wStringBuffer}!",
  ["_LickitungDexEntry"] = "Sua língua pode se\nextender como a de\num camaleão. Deixa\fuma sensação de\nformigamento em\nquem for lambido",
  ["_LightScreenProtectedText"] = "PC se\nprotegeu contra{SCROLL}golpes especiais!",
  ["_LinedUpText"] = "se alinharam!\nGanhou {RAM:wStringBuffer} fichas!",
  ["_LinkBattleLostText"] = "{PLAYER} perdeu\npara {RAM:wTrainerName}!",
  ["_LinkCableHelpText1"] = "DICAS PARA\nTREINADORES\fUsando o Cabo\nGame Link",
  ["_LinkCableHelpText2"] = "Sobre o que você\ngostaria de ler?",
  ["_LinkCableInfoText1"] = "Quando você\nconectar seu\vGAME BOY a outro\vGAME BOY, fale\vcom a atendente\vdo canto direito\vde qualquer\vCENTRO POKéMON.",
  ["_LinkCableInfoText2"] = "COLISEU deixa\nvocê batalhar\vcom um amigo.",
  ["_LinkCableInfoText3"] = "CENTRO DE TROCAs\né usado para\vtrocar POKéMON.",
  ["_LinkCanceledText"] = "A conexão foi\ncancelada.",
  ["_LoafingAroundText"] = "{RAM:wBattleMonNick} está\nse espreguiçando.",
  ["_LoreleisRoomLoreleiAfterBattleText"] = "Você é melhor do\nque eu pensei!\vVá em frente!\fVocê sentiu apenas\num gostinho do\vpoder da LIGA\vPOKéMON!",
  ["_LoreleisRoomLoreleiBeforeBattleText"] = "Bem-vindo à\nLIGA POKéMON!\fEu sou LORELEI, da\nELITE DOS QUATRO!\fNinguém pode me\nsuperar quando o\vassunto são os\vPOKéMON gelados!\fGolpes congelantes\nsão poderosos!\fSeus POKéMON vão\nficar à minha\vmercê quando eles\vestiverem todos\vcongelados!\fHahaha!\nVocê está pronto?",
  ["_LoreleisRoomLoreleiDontRunAwayText"] = "Voz de Alguém:\nNão pode fugir!",
  ["_LoreleisRoomLoreleiEndBattleText"] = "Como\nse atreve!",
  ["_LoweredItsHeadText"] = "\nabaixou a cabeça!",
  ["_MachampDexEntry"] = "Usando seus múscu-\nlos incríveis, ele\ndispara socos po-\fderosos que podem\nenviar a vítima\nalém do horizonte",
  ["_MachokeDexEntry"] = "Seu corpo musculo-\nso é tão poderoso,\nque ele precisa de\fum cinto especial\npara regular seus\nmovimentos",
  ["_MachopDexEntry"] = "Adora exercitar os\nseus músculos. \nTreina todo tipo\fde artes marciais\npara ficar cada\nvez mais forte",
  ["_MadeWhirlwindText"] = " fez\num redemoinho!",
  ["_MagazinesText"] = "Revistas POKéMON!\fCadernos POKéMON!\fDesenhos POKéMON!",
  ["_MagikarpDexEntry"] = "Num passado dis-\ntante, já foi bem\nmais poderoso que\fque seus fracos\ndescendentes que\nexistem hoje",
  ["_MagmarDexEntry"] = "Seu corpo sempre\nqueima com um bri-\nlho alaranjado, o\fque lhe permite se\nesconder perfeita-\nmente no fogo",
  ["_MagnemiteDexEntry"] = "Usa anti-gravidade\npara se manter em\nsuspensão. Aparece\fsem qualquer aviso\nusando golpes como\na ONDA DE TROVÃO",
  ["_MagnetonDexEntry"] = "Formado por vários\nMAGNEMITEs ligados\njuntos. Aparecem\fquando as manchas\ne tempestades\nsolares aumentam",
  ["_MankeyDexEntry"] = "Extremamente rápi-\ndo e nervoso. Ele\npode estar dócil\fem um momento e\nentão se agitar\nem um instante",
  ["_MarowakDexEntry"] = "O osso que ele\nsegura é sua prin-\ncipal arma. Habil-\fmente o atira como\num bumerangue para\nacertar inimigos",
  ["_MartSignText"] = "Todos os itens\nque você precisar!\vLOJA POKéMON",
  ["_MeowthDexEntry"] = "Adora objetos cir-\nculares. Durante\na noite, costuma\fvagar pelas ruas\na procura de\nmoedas perdidas",
  ["_MetapodDexEntry"] = "Esse POKéMON fica\nvulnerável a ata-\nques enquanto sua\fcasca está mole,\nexpondo seu corpo\nfraco e delicado",
  ["_MewDexEntry"] = "Tão raro que ainda\né considerado uma\nmiragem por muitos\fespecialistas.\nPoucas pessoas no\nmundo o viram",
  ["_MewtwoBattleText"] = "Mew!",
  ["_MewtwoDexEntry"] = "Foi criado por um\ncientista após \nanos de terríveis\fexperimentos com\nreconstrução e en-\ngenharia genética",
  ["_MimicLearnedMoveText"] = "{USER}\naprendeu\v{RAM:wNameBuffer}!",
  ["_MirrorMoveFailedText"] = "O ATAQUE ESPELHADO\nfalhou!",
  ["_MoltresDexEntry"] = "Conhecido como a\nlendária ave de\nfogo. A cada bater\fde suas asas, ele\ncria deslumbrantes\nclarões de chamas",
  ["_MonCannotLearnMachineMoveText"] = "{RAM:wNameBuffer} não é\ncompatível com\v{RAM:wStringBuffer}.\fNão pode aprender\n{RAM:wStringBuffer}.",
  ["_MonIsTakenOutText"] = "{RAM:wStringBuffer} foi\nretirado.\vRecebeu {RAM:wStringBuffer}.",
  ["_MonWasReleasedText"] = "{RAM:wStringBuffer} foi\nsolto na natureza.\vTchau, {RAM:wStringBuffer}!",
  ["_MonWasStoredText"] = "{RAM:wStringBuffer} foi guardado\nna POKéCAIXA {RAM:wBoxNumString}.",
  ["_MoneyForWinningText"] = "{PLAYER} ganhou ¥{NUM:wAmountMoneyWon, 3 | LEADING_ZEROES | LEFT_ALIGN}\npela sua vitória!",
  ["_MonsStatsFellText"] = "{RAM:wStringBuffer}\nde {TARGET}",
  ["_MonsStatsRoseText"] = "{RAM:wStringBuffer}\nde {USER}",
  ["_MoveDisabledText"] = "Esse golpe está\ninabilitado!",
  ["_MoveIsDisabledText"] = "{USER}\nsegue atacando!",
  ["_MoveNameText"] = "{RAM:wStringBuffer}!",
  ["_MoveNoPPText"] = "Sem PP sobrando\npara esse golpe!",
  ["_MoveWasDisabledText"] = "{RAM:wNameBuffer} de\n{TARGET} foi\vinabilitado!",
  ["_MrFujisHouseLittleGirlPokemonAreNiceToHugText"] = "É tão quentinho!\nPOKéMON são muito\vbons para abraçar!",
  ["_MrFujisHouseLittleGirlThisIsMrFujisHouseText"] = "Essa é mesmo a\ncasa do SR.FUJI.\fEle é realmente\nmuito bondoso!\fEle cuida de POKé-\nMON órfãos e que\vforam abandonados!",
  ["_MrFujisHouseMrFujiHasMyFluteHelpedYouText"] = "SR.FUJI: Minha\nFLAUTA te ajudou?",
  ["_MrFujisHouseMrFujiIThinkThisMayHelpYourQuestText"] = "SR.FUJI: {PLAYER}.\fSua missão de\ncompletar a sua\vPOKéDEX poderá\vfalhar sem amor\vpor seus POKéMON.\fEu acho que isso\npode te ajudar em\vsua missão.",
  ["_MrFujisHouseMrFujiPokeFluteExplanationText"] = "\fAo escutar o som\nda POKéFLAUTA, os\vPOKéMON que estão\vdormindo irão\vacordar na hora.\fFunciona em todos\nos POKéMON que\vestão dormindo.",
  ["_MrFujisHouseMrFujiPokeFluteNoRoomText"] = "Você precisa abrir\nespaço para isso!",
  ["_MrFujisHouseMrFujiPokedexText"] = "Grande Prêmio de\nDesenhos POKéMON!\fO formulário de\ninscrição está...\fJá era!\nFoi recortado!",
  ["_MrFujisHouseMrFujiReceivedPokeFluteText"] = "{PLAYER} recebeu\na {RAM:wStringBuffer}!",
  ["_MrFujisHouseNidorinoText"] = "NIDORINO: Niaoo!",
  ["_MrFujisHousePsyduckText"] = "PSYDUCK: Psaiai!",
  ["_MrFujisHouseSuperNerdMrFujiHadBeenPrayingText"] = "SR.FUJI estava\nrezando sozinho\vpara a mãe do\vCUBONE.",
  ["_MrFujisHouseSuperNerdMrFujiIsntHereText"] = "Que estranho, o \nSR.FUJI não está\vaqui. Pra onde\vele foi?",
  ["_MrMimeDexEntry"] = "Se for interrompi-\ndo enquanto faz a\nsua mímica, irá\fencher o agressor\nde tapas com suas\nmãos enormes",
  ["_MrPsychicsHouseMrPsychicReceivedTM29Text"] = "{PLAYER} recebeu\n{RAM:wStringBuffer}!",
  ["_MrPsychicsHouseMrPsychicTM29ExplanationText"] = "MT29 contém\nPSÍQUICO!\fEsse golpe pode\nabaixar o atribu-\vto de ESPECIAL do\vseu adversário.",
  ["_MrPsychicsHouseMrPsychicTM29NoRoomText"] = "Onde pretender por\nisso, se você\vnão tem espaço?",
  ["_MrPsychicsHouseMrPsychicYouWantedThisText"] = "...Espere! não\ndiga uma palavra!\fVocê queria isso!",
  ["_MtMoon1FBewareZubatSign"] = "Cuidado! ZUBAT é\num sanguessuga!",
  ["_MtMoon1FCooltrainerF1AfterBattleText"] = "Como faz pra\nsair daqui?",
  ["_MtMoon1FCooltrainerF1BattleText"] = "Uau! Aqui dentro\né bem maior do\vque eu imaginava!",
  ["_MtMoon1FCooltrainerF1EndBattleText"] = "Oh!\nEu perdi!",
  ["_MtMoon1FCooltrainerF2AfterBattleText"] = "Ouvi que tem algum\ntipo de fóssil\vraro por aqui.",
  ["_MtMoon1FCooltrainerF2BattleText"] = "O que foi? Estou\nesperando meus\vamigos virem ao\vao meu encontro.",
  ["_MtMoon1FCooltrainerF2EndBattleText"] = "Eu perdi?",
  ["_MtMoon1FHikerAfterBattleText"] = "Crianças como você\nnão deveriam\vestar por aqui!",
  ["_MtMoon1FHikerBattleText"] = "UAU! Você me sur-\npreendeu! Ah, mas\vé só uma criança!",
  ["_MtMoon1FHikerEndBattleText"] = "Uau!\nSurpreso de novo!",
  ["_MtMoon1FSuperNerdAfterBattleText"] = "Preciso encontrar\num POKéMON que\vseja mais forte.",
  ["_MtMoon1FSuperNerdBattleText"] = "O quê?! Não fique\nse esgueirando!",
  ["_MtMoon1FSuperNerdEndBattleText"] = "Meu\nPOKéMON perdeu!",
  ["_MtMoon1FYoungster1AfterBattleText"] = "Eu vim até aqui\npara me exibir\vpara as meninas.",
  ["_MtMoon1FYoungster1BattleText"] = "Você também veio\npara explorar?",
  ["_MtMoon1FYoungster1EndBattleText"] = "Perder\né chato!",
  ["_MtMoon1FYoungster2AfterBattleText"] = "Eu os vi! Tenho\ncerteza que são\vda EQUIPE ROCKET!",
  ["_MtMoon1FYoungster2BattleText"] = "Tem uns homens\nsuspeitos aqui\vna caverna.\vVocê viu?",
  ["_MtMoon1FYoungster2EndBattleText"] = "\nVocê me pegou!",
  ["_MtMoon1FYoungster3AfterBattleText"] = "ZUBATs são chatos!\nMas podem ser\vúteis se você\vcapturar um.",
  ["_MtMoon1FYoungster3BattleText"] = "Siga por essa\ncaverna para\vchegar na CIDADE\vDE CERULEAN!",
  ["_MtMoon1FYoungster3EndBattleText"] = "\nEu perdi.",
  ["_MtMoonB2FDomeFossilYouWantText"] = "Você quer o\nFÓSSIL CÚPULA?",
  ["_MtMoonB2FHelixFossilYouWantText"] = "Você quer o\nFÓSSIL ESPIRAL?",
  ["_MtMoonB2FReceivedFossilText"] = "{PLAYER} ganhou\no {RAM:wStringBuffer}!",
  ["_MtMoonB2FRocket1AfterBattleText"] = "Você me irritou!\nA EQUIPE ROCKET\vvai te colocar na\vlista negra!",
  ["_MtMoonB2FRocket1BattleText"] = "A EQUIPE ROCKET\nvai encontrar os\vfósseis, revivê-\vlos e vendê-los!",
  ["_MtMoonB2FRocket1EndBattleText"] = "Argh!\nAgora eu fiquei\vnervoso!",
  ["_MtMoonB2FRocket2AfterBattleText"] = "Se deu mal! Meus\ncompanheiros não\vvão deixar isso\vpassar batido!",
  ["_MtMoonB2FRocket2BattleText"] = "Nós, da EQUIPE\nROCKET, somos\vmafiosos POKéMON!",
  ["_MtMoonB2FRocket2EndBattleText"] = "Eu\nestraguei tudo!",
  ["_MtMoonB2FRocket3AfterBattleText"] = "Se você achar um\nfóssil, dê ele\vpra mim e vaza!",
  ["_MtMoonB2FRocket3BattleText"] = "Temos negócios\nnessas bandas.\vVaza, pivete!",
  ["_MtMoonB2FRocket3EndBattleText"] = "Então,\nvocê é bom.",
  ["_MtMoonB2FRocket4AfterBattleText"] = "POKéMON viveram\naqui muito antes\vdas pessoas\vchegarem aqui.",
  ["_MtMoonB2FRocket4BattleText"] = "Crianças deveriam\ndeixar os adultos\vem paz!",
  ["_MtMoonB2FRocket4EndBattleText"] = "Mas\nque ódio!",
  ["_MtMoonB2FSuperNerdOkIllShareText"] = "OK!\nVamos repartir!",
  ["_MtMoonB2FSuperNerdThenThisIsMineText"] = "Tudo bem. Então\nesse será meu!",
  ["_MtMoonB2FSuperNerdTheresAPokemonLabText"] = "Bem longe, na\nILHA CINNABAR,\vexiste um labora-\vtório POKéMON.\fEles pesquisam\na regeneração \vde fósseis.",
  ["_MtMoonB2FSuperNerdTheyreBothMineText"] = "Ei, pare!\fEu que encontrei\nesses fósseis!\vAmbos são meus!",
  ["_MtMoonB2FYouHaveNoRoomText"] = "Olha, você não tem\nespaço pra isso.",
  ["_MtMoonB2fSuperNerdEachTakeOneText"] = "Cada um de nós\nfica com um!\vSem ganância!",
  ["_MtMoonPokecenterBenchGuyText"] = "Se você tiver\nmuitos POKéMON,\vvai precisar\varmazená-los no\vcomputador!",
  ["_MtMoonPokecenterGentlemanText"] = "EQUIPE ROCKET\nataca cidadãos\vde CERULEAN...\fEQUIPE ROCKET está\nsempre nas\vnotícias!",
  ["_MtMoonPokecenterMagikarpSalesmanIGotADealText"] = "HOMEM: Olá, você!\nEu tenho uma\voferta especial\vsó para você!\fVou deixar você\nficar com esse\vincrível MAGIKARP\vpor míseros ¥500!\vO que me diz?",
  ["_MtMoonPokecenterMagikarpSalesmanNoMoneyText"] = "Vai precisar de\nmais dinheiro!",
  ["_MtMoonPokecenterMagikarpSalesmanNoRefundsText"] = "HOMEM: Não aceito\ndevoluções!",
  ["_MtMoonPokecenterMagikarpSalesmanNoText"] = "Não? Eu só estou\ntentando ajudar!",
  ["_MtMoonPokecenterYoungsterText"] = "Tenho 6 POKé BOLAs\nem meu cinto.\fVocê pode carregar\nno máximo até\v6 POKéMON.",
  ["_MukDexEntry"] = "Coberto por uma\ngrossa camada de\nlama imunda e no-\fjenta, que até as\nsuas pegadas são\ncheias de veneno",
  ["_MultiHitText"] = "Acertou o adversá-\nrio {NUM:wPlayerNumHits, 1, 1} vezes!",
  ["_Museum1FGamblerText"] = "Esse é um fóssil\nmagnífico!",
  ["_Museum1FOldAmberText"] = "O ÂMBAR é claro\ne dourado!",
  ["_Museum1FScientist1AmberIsFossilizedTreeSapText"] = "ÂMBAR é seiva\nfossilizada.",
  ["_Museum1FScientist1ComeAgainText"] = "¡Vuelve pronto!",
  ["_Museum1FScientist1DoYouKnowWhatAmberIsText"] = "Você não deveria\nse esgueirar pela\vporta dos fundos!\fAh, tanto faz!\nVocê sabe o que é\vum ÂMBAR?",
  ["_Museum1FScientist1DontHaveEnoughMoneyText"] = "Parece que você\nnão tem dinheiro\vsuficiente.",
  ["_Museum1FScientist1GoToOtherSideText"] = "Por favor, vá para\no outro lado!",
  ["_Museum1FScientist1TakePlentyOfTimeText"] = "¡Lleva mucho\ntiempo mirar!",
  ["_Museum1FScientist1ThankYouText"] = "¡50¥! ¡vale!\n¡Gracias!",
  ["_Museum1FScientist1TheresALabSomewhereText"] = "Tem um laboratório\nem algum lugar\vtentando reviver\vPOKéMON extintos\vatravés do ÂMBAR.",
  ["_Museum1FScientist1WouldYouLikeToComeInText"] = "Custa ¥50 por um\nbilhete infantil.\fGostaria de\nentrar?",
  ["_Museum1FScientist2GetTheOldAmberCheckText"] = "Chiu! Vá analisar\no ÂMBAR ANTIGO!",
  ["_Museum1FScientist2ReceivedOldAmberText"] = "{PLAYER} recebeu\nÂMBAR ANTIGO!",
  ["_Museum1FScientist2TakeThisToAPokemonLabText"] = "Chiu! Eu acho que\nesse pedaço de\vÂMBAR contém\vDNA POKéMON!\fSeria incrível se\num POKéMON fosse\vrevivido através\vdisso!\fMas meus colegas\nme ignoraram!\fEntão vou te pedir\num favor!\fLeve isso para\num LABORATÓRIO\vexaminar melhor!",
  ["_Museum1FScientist2YouDontHaveSpaceText"] = "Você não espaço\npara pegar isso!",
  ["_Museum1FScientist3Text"] = "Estamos muito\norgulhosos dos\vdois fósseis de\vPOKéMON raros e\vpré-históricos!",
  ["_Museum2FBrunetteGirlText"] = "Quero um PIKACHU!\nÉ tão fofinho!\fEu pedi para o\npapai pegar um!",
  ["_Museum2FGrampsText"] = "20 de Julho, 1969!\fFoi o primeiro\npouso na Lua!\fEu me lembro de\nter comprado uma\vTV colorida só\vpra ver isso!",
  ["_Museum2FHikerText"] = "Tá, vou pegar um\nPIKACHU, eu juro!",
  ["_Museum2FMoonStoneSignText"] = "É um meteorito\nque caiu na\vMONTANHA DA LUA.\v(PEDRA DA LUA?)",
  ["_Museum2FScientistText"] = "Agora temos uma\nexposição sobre o\vespaço sideral.",
  ["_Museum2FSpaceShuttleSignText"] = "NAVE ESPACIAL\nCOLUMBIA",
  ["_Museum2FYoungsterText"] = "¿La PIEDRA LUNAR?\f¿Qué tiene tan\nde especial?",
  ["_MustRechargeText"] = "{USER}\nestá paralisada!",
  ["_NameRatersHouseNameRaterATrulyImpeccableNameText"] = "{RAM:wNameBuffer}, é isso?\nEsse é um nome\vimpecável mesmo!\fCuide bem de\n{RAM:wNameBuffer}!",
  ["_NameRatersHouseNameRaterComeAnyTimeYouLikeText"] = "Tudo bem! Volte\nquando quiser!",
  ["_NameRatersHouseNameRaterGiveItANiceNameText"] = "{RAM:wNameBuffer}, é isso?\nEsse é um nome\vrazoável!\fMas, você\nquer que eu dê\vum nome melhor?\fQue tal?",
  ["_NameRatersHouseNameRaterPokemonHasBeenRenamedText"] = "OK! Esse POKéMON\nagora se chama\v{RAM:wBuffer}!\fEsse é um nome\nmuito melhor que\vo anterior!",
  ["_NameRatersHouseNameRaterWantMeToRateText"] = "Olá, olá! Eu sou o\nNOMEADOR OFICIAL!\fQuer que eu avalie\no apelido dos\vseus POKéMON?",
  ["_NameRatersHouseNameRaterWhatShouldWeNameItText"] = "Ótimo! Que nome\nvamos por?",
  ["_NameRatersHouseNameRaterWhichPokemonText"] = "Qual POKéMON\ndevo avaliar?",
  ["_NeedYourPokemonText"] = "OK. Me entregue\nseus POKéMON.",
  ["_NewBadgeRequiredText"] = "Não pode usar\nisso agora...\fPrecisa de uma\nnova INSÍGNIA...",
  ["_NewBicycleText"] = "¡Una BICICLETA\nnueva!",
  ["_NidokingDexEntry"] = "Usa sua poderosa\ncauda em batalha\npara apertar, es-\fmagar, e então\nquebrar os ossos\nde suas presas",
  ["_NidoqueenDexEntry"] = "Suas escamas duras\nlhe dão uma forte\nproteção. Ela usa\fsua massa robusta\npara executar \ngolpes poderosos",
  ["_NidoranFDexEntry"] = "Embora pequena,\nseus espinhos\nvenenosos a\ftornam perigosa.\nAs fêmeas possuem\nchifres menores",
  ["_NidoranMDexEntry"] = "Ergue suas orelhas\npara sentir o pe-\nrigo. Quanto maior\fsão seus espinhos,\nmais forte será o\nveneno secretado",
  ["_NidorinaDexEntry"] = "O chifre da fêmea\ncresce mais deva-\ngar. Ela prefere\fusar ataques físi-\ncos como arranhões\ne mordidas",
  ["_NidorinoDexEntry"] = "Um POKéMON muito\nagressivo que é\nrápido no ataque.\fO chifre em sua\ncabeça secreta um\nveneno poderoso",
  ["_NinetalesDexEntry"] = "Muito inteligente\ne vingativo. Agar-\nrar uma de suas\fvárias caudas pode\nresultar em 1000\nanos de maldição",
  ["_NoCyclingAllowedHereText"] = "Não seja\num ladrão!",
  ["_NoEffectText"] = "Nada aconteceu!",
  ["_NoMonText"] = "Quê? Não há\nPOKéMON aqui!",
  ["_NoMoreRoomForItemText"] = "Pra onde gostaria\nde ir?",
  ["_NoMovesLeftText"] = "{RAM:wBattleMonNick} não\ntem mais golpes!",
  ["_NoNibbleText"] = "Nem mesmo uma\nmordiscadinha!",
  ["_NoRoomToStoreText"] = "Sem espaço para\narmazenar itens.",
  ["_NoRunningText"] = "Não! Não se pode\nfugir de uma \vbatalha entre{SCROLL}treinadores!",
  ["_NoSurfingHereText"] = "Não pode andar de\nBICICLETA aqui.",
  ["_NoTrade1Text"] = "Ahhh!\nTudo bem...",
  ["_NoTrade2Text"] = "Bem, se você\nnão quer...",
  ["_NoTrade3Text"] = "Oi! Você teria\num {RAM:wInGameTradeGiveMonName}?\fQuer trocar por\num {RAM:wInGameTradeReceiveMonName}?",
  ["_NoWillText"] = "Não tem forças\npara lutar!",
  ["_NotEnoughCoinsSlotMachineText"] = "Sem fichas\nsuficientes!",
  ["_NotHealthyEnoughText"] = "Sem saúde\nsuficiente.",
  ["_NotThisTimeText"] = "Não foi dessa vez!",
  ["_NotVeryEffectiveText"] = "Não foi muito\neficaz...",
  ["_NothingHappenedText"] = "{RAM:wNameBuffer}\nde ROCKET\vfoi inabilitado!",
  ["_NothingHereText"] = "Parece que não tem\nnada por aqui.",
  ["_NothingStoredText"] = "O que você quer\njogar fora?",
  ["_NothingToCutText"] = "Não tem nada para\nCORTAR aqui!",
  ["_NothingToDepositText"] = "Você não tem nada\npara depositar.",
  ["_OHKOText"] = "¡KO en un golpe!",
  ["_OKExclamationText"] = "¡VALE!",
  ["_OakLabEmailText"] = "Tem uma mensagem\nde e-mail aqui!\f...\fConvocando todos\ntreinadores de\vPOKéMON!\fA elite de treina-\ndores da LIGA \vPOKéMON está\vpronta para todos\vos desafiantes!\fTraga os seus\nmelhores POKéMON\ve veja como você\vse classifica!\fQG DA LIGA POKéMON\nPLANALTO ÍNDIGO\fPS: PROF.CARVALHO,\npor favor venha\vnos visitar...",
  ["_OakSpeechText1"] = "¡Hola a todos!\n¡Bienvenidos al\vmundo de POKéMON!\f¡Me llamo OAK!\f¡Pero la gente me\nllama el PROFESOR\vPOKéMON!",
  ["_OakSpeechText2A"] = "¡Este mundo está\nhabitado por unas\vcriaturas\vllamadas POKéMON!",
  ["_OakSpeechText2B"] = "\fPara algunos, los\nPOKéMON son\vcomo mascotas.\vMientras que\votros los usan\vpara pelear.\fEn cuanto a mí...\fEstudio a los\nPOKéMON como\nprofesión.",
  ["_OakSpeechText3"] = "¡{PLAYER}!\f¡Tu propia\nleyenda POKéMON!\vestá a punto\vde comenzar!\fTe espera un\nmundo de sueños\vy aventuras con\vlos POKéMON.\v¡Adelante!",
  ["_OaksAideComeBackText"] = "Ah! Ya veo.\fCuando tengas {NUM:hOaksAideNumMonsOwned, 1, 3}\nespecies distintas\vde POKéMON, aquí\vte espero.",
  ["_OaksAideGotItemText"] = "¡{PLAYER}\nobtiene {NUM:wDexRatingNumMonsSeen, 1, 3}!",
  ["_OaksAideHereYouGoText"] = "Ótimo! Você já\ncapturou {NUM:hOaksAideNumMonsOwned, 1, 3} tipos\vde POKéMON!\vParabéns!\fAqui está!",
  ["_OaksAideHiText"] = "Olá!\nLembra-se de mim?\vSou o ajudante do\vPROF.CARVALHO!\fSe você já tiver\npego {NUM:hDexRatingNumMonsSeen, 1, 3} POKéMON\vde espécies dife-\vrentes, eu tenho\vque te entregar\vum {NUM:wDexRatingNumMonsSeen, 1, 3}!\fEntão, {PLAYER}!\nVocê pegou pelo\vmenos {NUM:hDexRatingNumMonsSeen, 1, 3} espécies\vde POKéMON?",
  ["_OaksAideNoRoomText"] = "Oh! Parece que\nvocê não tem\vespaço livre para\vcarregar isso.",
  ["_OaksAideUhOhText"] = "Vamos ver...\nEi!! Você pegou\vapenas {NUM:hOaksAideNumMonsOwned, 1, 3} POKéMON\vdiferentes!\fVocê precisa pegar\n{NUM:hDexRatingNumMonsSeen, 1, 3} POKéMON de es-\vpécies diferentes\vse quiser receber\vo {NUM:wDexRatingNumMonsSeen, 1, 3}!",
  ["_OaksLabGirlText"] = "PROF.CARVALHO é\numa autoridade em\vassuntos POKéMON!\fMuitos treinadores\nPOKéMON têm muito\vrespeito por ele!",
  ["_OaksLabGivePokeballsExplanationText"] = "\fQuando um POKéMON\nselvagem aparece,\vé molezinha.\fBasta atirar uma\nPOKé BOLA nele\vpara capturar!\fMas nem sempre vai\nfuncionar...\fUm POKéMON com a\nsaúde cheia pode\vescapar. Você\vprecisa de sorte!",
  ["_OaksLabLastMonText"] = "O último POKéMON\ndo PROF.CARVALHO!",
  ["_OaksLabMonEnergeticText"] = "Esse é um POKéMON\nbem animado!",
  ["_OaksLabOak1ComeSeeMeSometimesText"] = "CARVALHO: Venha\nme visitar de vez\vem quando.\fQuero ver como\nsua POKéDEX está\vprogredindo.",
  ["_OaksLabOak1DeliverParcelText"] = "CARVALHO: Olá,\n{PLAYER}!\fComo vai meu velho\nPOKéMON?\fBem, ele parece\ngostar de você.\fVocê deve ser bem\ntalentoso como\vtreinador {PK}{MN}!\fO que? Você tem\nalgo para mim?\f{PLAYER} entregou\na ENCOMENDA.",
  ["_OaksLabOak1HowIsYourPokedexComingText"] = "CARVALHO: Que bom\nte ver! Como anda\va sua POKéDEX?\vAqui, deixe-me\vdar uma olhada!",
  ["_OaksLabOak1ParcelThanksText"] = "\fAh! Isso são as\nPOKé BOLAs que eu\vencomendei!\vMuito obrigado!",
  ["_OaksLabOak1PokemonAroundTheWorldText"] = "POKéMON do mundo\ntodo aguardam por\vvocê, {PLAYER}!",
  ["_OaksLabOak1RaiseYourYoungPokemonText"] = "CARVALHO: Você\ndeve fazer o seu\vPOKéMON batalhar\vpara fortalecê-lo!",
  ["_OaksLabOak1ReceivedPokeballsText"] = "CARVALHO: Você\nnão vai conseguir\vdados detalhados\vapenas olhando\vpara os POKéMON.\fVocê precisa\ncapturá-los!\fAqui, use isto\npara capturar um\vPOKéMON selvagem.\f{PLAYER} ganhou\n5 POKé BOLAs!",
  ["_OaksLabOak1WhichPokemonDoYouWantText"] = "CARVALHO: E então,\n{PLAYER} qual\vPOKéMON você vai\vescolher?",
  ["_OaksLabOak1YourPokemonCanFightText"] = "CARVALHO: Agora\nquando você for\vatacado por um\vPOKéMON selvagem,\vterá como se\vdefender!",
  ["_OaksLabOak2Text"] = "?",
  ["_OaksLabOakBePatientText"] = "CARVALHO: Seja pa-\nciente, {RIVAL}!\vVocê também pode\vescolher um!",
  ["_OaksLabOakChooseMonText"] = "CARVALHO: Hã?\n{RIVAL}?\vDeixe-me ver...\fAh, é verdade, eu\ntinha pedido que\vvocê viesse!\vEspere um pouco!\fAqui, {PLAYER}!\fTem 3 POKéMON\nali na mesa!\fHaha!\fEles estão dentro\ndas POKé BOLAs.\fQuando eu era\njovem, era um \vgrande treina-\vdor POKéMON!\fAgora que já sou\nvelho, sobraram\vapenas esses 3,\vmas você pode fi-\vcar com um deles!\vPode escolher!",
  ["_OaksLabOakDontGoAwayYetText"] = "CARVALHO: Ei! Não\nvá embora ainda!",
  ["_OaksLabOakGotPokedexText"] = "CARVALHO: {PLAYER}\ne {RIVAL}! Levem\visso com vocês!\f{PLAYER} ganhou\numa POKéDEX!",
  ["_OaksLabOakIHaveARequestText"] = "CARVALHO: Verdade!\nTenho uma tarefa\vpara vocês dois.",
  ["_OaksLabOakMyInventionPokedexText"] = "Ali na mesa está\nminha invenção,\va POKéDEX!\fEla registra auto-\nmaticamente os\vdados dos POKéMON\vque vocês virem\vou capturarem!\fÉ uma enciclopédia\ntecnológica!",
  ["_OaksLabOakThatWasMyDreamText"] = "Fazer um guia\ncompleto de todos\vPOKéMON do mundo\vinteiro...\fEsse era o\nmeu sonho!\fMas estou velho!\nNão consigo mais!\fEntão, quero que\nvocês dois reali-\vzem esse sonho\vno meu lugar!\fAgora mexam-se,\nvocês dois!\fEsse será um\ngrande marco na\vhistória POKéMON!",
  ["_OaksLabPokedexText"] = "Parece ser uma\nenciclopédia, mas\vas páginas estão\vtodas em branco!",
  ["_OaksLabReceivedMonText"] = "{PLAYER} recebeu\num {RAM:wNameBuffer}!",
  ["_OaksLabRivalAmIGreatOrWhatText"] = "{RIVAL}: Isso! Eu\nnão sou incrível?",
  ["_OaksLabRivalFedUpWithWaitingText"] = "{RIVAL}: Vovô!\nEstou cansado de\vesperar!",
  ["_OaksLabRivalGoAheadAndChooseText"] = "{RIVAL} ¡Ja!\n¡No soy tan\vávaro como tú!\f¡Venga, elige tú\nprimero, {PLAYER}!",
  ["_OaksLabRivalGrampsIsntAroundText"] = "{RIVAL}: ¡Oye\n{PLAYER}! ¡El\vabuelo no está\vaquí!",
  ["_OaksLabRivalGrampsText"] = "{RIVAL}: ¡Abuelo!",
  ["_OaksLabRivalIPickedTheWrongPokemonText"] = "O QUÊ?\nInacreditável!\vEu peguei o\vPOKéMON errado!",
  ["_OaksLabRivalIllTakeThisOneText"] = "{RIVAL}: Então,\nvou pegar esse!",
  ["_OaksLabRivalIllTakeYouOnText"] = "{RIVAL}: Espere\n{PLAYER}!\vVamos testar\vnossos POKéMON!\fQual é, vou pegar\nleve com você!",
  ["_OaksLabRivalLeaveItAllToMeText"] = "{RIVAL}: Não se\npreocupe, Vovô!\vPode deixar tudo\vcomigo!\f{PLAYER}, detesto\ndizer, mas eu não\vvou precisar da\vsua ajuda!\fJá sei! Vou pegar\num MAPA com a\vminha irmã!\fE vou dizer pra\nela não te dar\vnenhum, {PLAYER}!\vHahaha!",
  ["_OaksLabRivalMyPokemonLooksStrongerText"] = "{RIVAL}: Meu\nPOKéMON parece\vbem mais forte.",
  ["_OaksLabRivalReceivedMonText"] = "{RIVAL} recebeu\num {RAM:wNameBuffer}!",
  ["_OaksLabRivalSmellYouLaterText"] = "{RIVAL}: Certo!\nVou fazer meu\vPOKéMON lutar até\vficar mais forte!\f{PLAYER}! Vovô!\nFalou, valeu aí!",
  ["_OaksLabRivalWhatAboutMeText"] = "{RIVAL}: Ei!\nVovô! E quanto\va mim?",
  ["_OaksLabRivalWhatDidYouCallMeForText"] = "{RIVAL}: Por que\nvocê me chamou?",
  ["_OaksLabScientistText"] = "Eu estudo POKéMON\ncomo ajudante do\vPROF.CARVALHO.",
  ["_OaksLabThoseArePokeBallsText"] = "Essas são POKé\nBOLAs. Elas\vcontém POKéMON!",
  ["_OaksLabYouWantBulbasaurText"] = "Então, você quer o\nPOKéMON SEMENTE,\vBULBASAUR?",
  ["_OaksLabYouWantCharmanderText"] = "Então, você quer o\nPOKéMON de FOGO,\vCHARMANDER?",
  ["_OaksLabYouWantSquirtleText"] = "Então, você quer o\nPOKéMON da ÁGUA,\vSQUIRTLE?",
  ["_OddishDexEntry"] = "Durante o dia,\nmantém sua face\nenterrada no solo.\fÀ noite, vagueia\npelos campos plan-\ntando sementes",
  ["_OhFineThenText"] = "Ah, tudo bem\nentão.",
  ["_OlderFileWillBeErasedText"] = "O arquivo antigo\nserá apagado para\vsalvar esse. OK?",
  ["_OmanyteDexEntry"] = "Apesar de estar\nextinto, em raras\nocasiões, ele pode\fser geneticamente\nressuscitado atra-\nvés de fósseis",
  ["_OmastarDexEntry"] = "Um POKéMON pré-\nhistórico que\nmorreu quando sua\fconcha ficou pesa-\nda demais, impos-\nsibilitando caçar",
  ["_OnceReleasedText"] = "Depois de solto,\n{RAM:wStringBuffer}\vsome de vez. OK?",
  ["_OneMoreGoSlotMachineText"] = "Mais uma\ntentativa?",
  ["_OneTwoAndText"] = "1, 2 e...",
  ["_OnixDexEntry"] = "Conforme cresce,\nas partes de pedra\ndo seu corpo en-\fdurecem, ficando\nsimilares a um\ndiamante negro",
  ["_OopsYouDontHaveEnoughRoomText"] = "Ah, tudo bem\nentão.",
  ["_OutOfCoinsSlotMachineText"] = "Droga! Acabaram\nas fichas!",
  ["_OutOfSafariBallsText"] = "RADIO: ¡Ding-dong!\f¡Te has quedado\nsin SAFARI BALLS!",
  ["_PPIncreasedText"] = "O PP de\n{RAM:wStringBuffer} aumentou.",
  ["_PPMaxedOutText"] = "O PP de\n{RAM:wStringBuffer} já é máximo.",
  ["_PPRestoredText"] = "Ativou uma MT!",
  ["_PalletTownFisherText"] = "A tecnologia é\nmesmo incrível!\fVocê pode guardar\nitens e POKéMON\vno computador!",
  ["_PalletTownGirlText"] = "Estou criando\nPOKéMON também!\fQuando ele\ncrescer e ficar\vforte, poderá\vme proteger!",
  ["_PalletTownOakHeyWaitDontGoOutText"] = "OAK: ¡Eh! ¡Alto!\n¡No te vayas!",
  ["_PalletTownOakItsUnsafeText"] = "CARVALHO: É muito\nperigoso! POKéMON\vselvagens vivem\vna grama alta!\fVocê precisa ter\nseus próprios\vPOKéMON para se\vproteger.\vJá sei!\fAqui, venha\ncomigo!",
  ["_PalletTownOaksLabSignText"] = "LABORATÓRIO {PK}{MN}\nDO PROF.CARVALHO",
  ["_PalletTownPlayersHouseSignText"] = "Casa do {PLAYER}",
  ["_PalletTownRivalsHouseSignText"] = "Casa do {RIVAL}",
  ["_PalletTownSignText"] = "CIDADE DE PALLET\nUma página em\vbranco aguardando\vnovas aventuras!",
  ["_ParalyzedMayNotAttackText"] = "{TARGET}\nfoi paralisado!\vPode ser que não{SCROLL}consiga atacar!",
  ["_ParasDexEntry"] = "Cava para sugar as\nraízes de árvores.\nO cogumelo em suas\fcostas cresce su-\ngando nutrientes\ndo seu hospedeiro",
  ["_ParasectDexEntry"] = "Um par de parasita\ne hospedeiro, onde\no fungo parasita\fjá tomou conta do\ninseto hospedeiro.\nGosta de umidade",
  ["_ParlyzHealText"] = "A paralisia de\n{RAM:wNameBuffer} sarou!",
  ["_PartyMenuBattleText"] = "Qual POKéMON\nusar agora?",
  ["_PartyMenuItemUseText"] = "Usar item em qual\nPOKéMON?",
  ["_PartyMenuNormalText"] = "Selecione\num POKéMON.",
  ["_PartyMenuSwapMonText"] = "Mover esse POKéMON\npara qual posição?",
  ["_PartyMenuUseTMText"] = "Ensinar essa MT\npara qual POKéMON?",
  ["_PersianDexEntry"] = "Apesar do seu pelo\nter muitos admira-\ndores, ele é muito\fdifícil de criar\ndevido a sua natu-\nreza malvada",
  ["_PewterCityCooltrainerFText"] = "Diz a lenda que\nos CLEFAIRYs\vvieram da Lua!\fElas apareceram\ndepois que várias\vPEDRAs DA LUA\vcaíram sobre a\vMONTANHA DA LUA.",
  ["_PewterCityCooltrainerMText"] = "Não tem muitos\ntreinadores sé-\vrios por aqui!\fSão todos apenas\nuns CAÇA-INSETOS,\vmas o LÍDER DO\vGINÁSIO, o BROCK,\vé bem dedicado!",
  ["_PewterCityGymSignText"] = "GINÁSIO POKéMON DA\nCIDADE DE PEWTER\vLÍDER: BROCK\fO Treinador de\nPOKéMON Rochosos",
  ["_PewterCityMuseumSignText"] = "MUSEU DE CIÊNCIA\nDE PEWTER",
  ["_PewterCityPokecenterGuyText"] = "Uahh!\fQuando JIGGLYPUFF\ncanta, os POKéMON\vpegam no sono...\f...Eu também...\nRonc...",
  ["_PewterCityPoliceNoticeSignText"] = "ATENÇÃO!\fBandidos estão\nroubando fósseis\vde POKéMON na\vMONTANHA DA LUA!\vPor favor, entrar\vem contato com a\vPOLÍCIA DE PEWTER\vse tiver pistas!",
  ["_PewterCitySignText"] = "CIDADE DE PEWTER\nUma cidade cor\vde Pedra Cinzenta",
  ["_PewterCitySuperNerd1DidYouCheckOutMuseumText"] = "Você já visitou\no MUSEU?",
  ["_PewterCitySuperNerd1ItsRightHereText"] = "É bem aqui!\nPrecisa pagar\vpara entrar, mas\vvale a pena!\vTe vejo por aí!",
  ["_PewterCitySuperNerd1WerentThoseFossilsAmazingText"] = "Aqueles fósseis da\nMONTANHA DA LUA\vnão são demais?",
  ["_PewterCitySuperNerd1YouHaveToGoText"] = "Sério?\nVocê realmente\vprecisa ir!",
  ["_PewterCitySuperNerd2DoYouKnowWhatImDoingText"] = "Psssiu!\nSabe o que eu\vestou fazendo?",
  ["_PewterCitySuperNerd2ImSprayingRepelText"] = "Estou passando um\nREPELENTE para\vmanter os POKéMON\vbem longe do\vmeu jardim!",
  ["_PewterCitySuperNerd2ThatsRightText"] = "Isso mesmo!  É\num trabalho duro!",
  ["_PewterCityTrainerTipsText"] = "DICAS PARA\nTREINADORES\fQualquer POKéMON\nque participar de\vuma batalha, irá\vganhar Pontos\vde Experiência\v(Pts. de EXP.)!",
  ["_PewterCityYoungsterGoTakeOnBrockText"] = "Quando se sentir\npronto, entre e\venfrente o BROCK!",
  ["_PewterCityYoungsterYoureATrainerFollowMeText"] = "Você é um treina-\ndor, certo? BROCK\vestá procurando\vpor desafiantes!\vMe siga!",
  ["_PewterGymBrockBoulderBadgeInfoText"] = "\fÉ uma INSÍGNIA\noficial da LIGA\vPOKéMON!\fSeus POKéMON\nficarão mais\vpoderosos!\fA técnica CLARÃO\nagora pode ser\vusada a qualquer\vmomento!",
  ["_PewterGymBrockPostBattleAdviceText"] = "Existem treinado-\nres de todo tipo\vpelo mundo!\fVocê parece ser\nbem talentoso\vcomo treinador\vPOKéMON!\fVá para o GINÁSIO\nem CERULEAN se\vquiser testar as\vsuas habilidades!",
  ["_PewterGymBrockPreBattleText"] = "Eu sou BROCK!\nSou o LÍDER DO\vGINÁSIO DA \vCIDADE DE PEWTER!\fEu acredito em\ndefesa dura como\vpedra e muita\vdeterminação!\fÉ por isso que os\nmeus POKéMON são\vdo tipo pedra!\fVocê ainda quer me\ndesafiar? Tudo\vbem, então! Me\vdê o seu melhor!",
  ["_PewterGymBrockReceivedBoulderBadgeText"] = "E pelo seu\nvalor...\fComo prova da sua\nvitória, aqui \vestá a INSÍGNIA\vROCHEDO!\f{PLAYER} recebeu\nINSÍGNIA ROCHEDO!",
  ["_PewterGymBrockWaitTakeThisText"] = "Espere! Leve isso\ncom você!",
  ["_PewterGymCooltrainerMAfterBattleText"] = "Você é bom, mas\nnão tão bom\vquanto BROCK!",
  ["_PewterGymCooltrainerMBattleText"] = "Pare aí mesmo,\npivete!\fVocê ainda está\nanos-luz de\venfrentar BROCK!",
  ["_PewterGymCooltrainerMEndBattleText"] = "Droga!\fAnos-luz não é\ntempo! É usado\vpara distância!",
  ["_PewterGymGuideAdviceText"] = "O 1º POKéMON a\nentrar na batalha\vé o que fica no\vtopo da sua\vLISTA DE POKéMON!\fMovendo a ordem\ndos seus POKéMON,\vpode facilitar\vas batalhas!",
  ["_PewterGymGuideBeginAdviceText"] = "Tá certo! Vamos\nfazer acontecer!",
  ["_PewterGymGuideFreeServiceText"] = "É um trabalho\nvoluntário! Vamos\vfazer acontecer!",
  ["_PewterGymGuidePostBattleText"] = "Como eu pensei!\nVocê será um\vgrande campeão!",
  ["_PewterGymGuidePreAdviceText"] = "Irra! Eu posso ver\nque você tem o\vnecessário para\vse tornar um\vmestre POKéMON!\fEu não sou um\ntreinador, mas\vposso te contar\vcomo vencer!\fDeixe-me te guiar\naté o topo!",
  ["_PewterGymReceivedTM34Text"] = "{PLAYER} recebeu\na MT34!",
  ["_PewterGymTM34NoRoomText"] = "Você não tem mais\nespaço para isso!",
  ["_PewterMartSuperNerdText"] = "Coisas boas vão\nacontecer se você\vtreinar POKéMON\vcom dedicação,\vaté mesmo aqueles\vmais fracotes!",
  ["_PewterMartYoungsterText"] = "Um velho suspeito\nconseguiu me con-\vvencer a comprar\vum POKéMON peixe\vbem estranho!\fÉ realmente fraco\ne me custou ¥500!",
  ["_PewterNidoranHouseLittleBoyText"] = "NIDORAN, senta!",
  ["_PewterNidoranHouseMiddleAgedManText"] = "Nosso POKéMON é um\nforasteiro, por\visso é difícil\vde controlar.\fForasteiros, são\nPOKéMON que você\vpegou numa troca.\fEles crescem bem\nmais rápido, mas\vpodem ignorar as\vordens de um\vtreinador que\vseja inexperiente\vem batalha!\fSe pelo menos eu\ntivesse alguma\vdas INSÍGNIAS...",
  ["_PewterNidoranHouseNidoranText"] = "NIDORAN: Ranran!",
  ["_PewterPokecenterGentlemanText"] = "O quê!?\fEQUIPE ROCKET na\nMONTANHA DA LUA?\vHã? Ei, eu estou\vno telefone!\fVaza!",
  ["_PewterPokecenterJigglypuffText"] = "JIGGLYPUFF: Jiggly\njiggly!",
  ["_PewterSpeechHouseGamblerText"] = "POKéMON aprendem\nnovas técnicas\vconforme crescem!\fMas alguns golpes\nprecisam ser\vensinados pelo\vseu treinador.",
  ["_PewterSpeechHouseYoungsterText"] = "POKéMON ficam mais\nfáceis de se\vcapturar quando\vestão feridos\vou dormindo!\fMas nem sempre\nfunciona!",
  ["_PickUpPayDayMoneyText"] = "{PLAYER} recolheu\n¥{NUM:wTotalPayDayMoney, 3 | LEADING_ZEROES | LEFT_ALIGN} do chão!",
  ["_PidgeotDexEntry"] = "Para caçar, ele\nvoa sobre a água\nem alta velocidade\fpara pegar presas\ndistraídas, como\nas MAGIKARP",
  ["_PidgeottoDexEntry"] = "Muito protetivo de\nsua vasta área\nterritorial,\fesse POKéMON irá\nbicar ferozmente\nqualquer intruso",
  ["_PidgeyDexEntry"] = "É comumente visto\nem qualquer bosque\nou florestas. Ele\fbate as asas no\nnível do solo para\nlevantar poeira",
  ["_PikachuDexEntry"] = "Quando vários\ndesses POKéMON se\nreúnem, a sua \feletricidade pode\ncausar tempesta-\ndes elétricas",
  ["_PinsirDexEntry"] = "Se não conseguir\nesmagar suas víti-\nmas com suas pin-\fças, ele as gira e\narremessa com um\nforça violenta",
  ["_PlaySlotMachineText"] = "Um caça-níquel!\nQuer jogar?",
  ["_PlayedFluteHadEffectText"] = "{PLAYER} tocou a\nPOKéFLAUTA.",
  ["_PlayedFluteNoEffectText"] = "{PLAYER} tocou a\nPOKéFLAUTA.\fÉ uma melodia\ncontagiosa!",
  ["_PlayerBlackedOutText"] = "{PLAYER} ficou\nsem POKéMON para\vusar em batalha!\f{PLAYER} perdeu\na consciência!",
  ["_PlayerBlackedOutText2"] = "{PLAYER} ficou sem\nnenhum POKéMON!\f{PLAYER} foi\nderrotado!",
  ["_PlayerMon1Text"] = "{RAM:wBattleMonNick}!",
  ["_PlayerMon2Text"] = "{RAM:wBattleMonNick} ",
  ["_PlayerMonFaintedText"] = "{RAM:wBattleMonNick}\ndesmaiou!",
  ["_PleaseWaitText"] = "A conexão foi\ncancelada.",
  ["_PoisonedText"] = "{TARGET}\nfoi envenenado!",
  ["_PokeCenterSignText"] = "Cure seus POKéMON!\nCENTRO POKéMON",
  ["_PokemartAnythingElseText"] = "Precisa de mais\nalguma coisa?",
  ["_PokemartBoughtItemText"] = "Aqui está!\nMuito obrigado!",
  ["_PokemartBuyingGreetingText"] = "Fique à vontade.",
  ["_PokemartGreetingText"] = "Olá! Como posso\nte ajudar?",
  ["_PokemartItemBagEmptyText"] = "Você não tem\nnada pra vender.",
  ["_PokemartItemBagFullText"] = "Você não pode car-\nregar mais items.",
  ["_PokemartNotEnoughMoneyText"] = "Não tem dinheiro\nsuficiente.",
  ["_PokemartTellBuyPriceText"] = "{RAM:wStringBuffer}?\nIsso vai custar\v¥{NUM:hMoney, 3 | LEADING_ZEROES | LEFT_ALIGN}. OK?",
  ["_PokemartTellSellPriceText"] = "Posso te pagar\n¥{NUM:hMoney, 3 | LEADING_ZEROES | LEFT_ALIGN} por isso.",
  ["_PokemartThankYouText"] = "Obrigado!",
  ["_PokemartUnsellableItemText"] = "Não posso pôr um\npreço nisso.",
  ["_PokemonBooksText"] = "Está repleta de\nlivros POKéMON!",
  ["_PokemonCenterFarewellText"] = "Obrigada! E volte\nquando precisar!",
  ["_PokemonCenterWelcomeText"] = "¡Bienvenido a\nnuestro CENTRO\vPOKéMON!\f¿Desea curar\na sus POKéMON?",
  ["_PokemonFaintedText"] = "{RAM:wNameBuffer}\ndesmaiou!",
  ["_PokemonFanClubBagFullText"] = "Abra espaço na sua\nmochila pra isso!",
  ["_PokemonFanClubChairFinalText"] = "Olá, {PLAYER}!\fVeio ouvir mais\nhistórias sobre\vmeu POKéMON?\fNão? Que pena!",
  ["_PokemonFanClubChairmanIntroText"] = "Olá! Eu sou o\npresidente do\vFã Clube POKéMON!\fJá capturei mais\nde 100 POKéMON!\fFico bem animado\nquando o assunto\vé POKéMON!\fEntão...\fVocê veio nos\nvisitar e ouvir\vum pouco sobre\vmeus POKéMON?",
  ["_PokemonFanClubChairmanStoryText"] = "Ótimo!\nEntão escute!\fMeu favorito é\no RAPIDASH...\fÉ...esperto...\namável...belo...\ve...incrível...\vacha mesmo?...\vah, sim...ele...\vesplêndido...\vgentilmente...\vamo demais!\fAbraço...quando...\ndorme...quentinho\ve aconchegante...\vespetacular...\varrebatador...\v...Opa! Olha só\va hora! Acabei\vfalando demais!\fObrigado por me\nouvir! Quero que\vfique com isso!",
  ["_PokemonFanClubExplainBikeVoucherText"] = "\fTroque isso por\numa BICICLETA!\fNão se preocupe,\nmeu FEAROW pode\vVOAR me levando\va qualquer lugar!\fEntão, não preciso\nde uma BICICLETA!\fEspero que goste\nde pedalar!",
  ["_PokemonFanClubNoStoryText"] = "Ah! Volte quando\nquiser ouvir as\vminhas histórias!",
  ["_PokemonFanClubPikachuFanBetterText"] = "Hum! Meu PIKACHU\né duas vezes mais\vfofo do que\vaquele peixe!",
  ["_PokemonFanClubPikachuFanNormalText"] = "Não quer admirar\na adorável cauda\vdo meu PIKACHU?",
  ["_PokemonFanClubPikachuText"] = "PIKACHU: Chu!\nPikachu!",
  ["_PokemonFanClubReceivedBikeVoucherText"] = "{PLAYER} ganhou um\n{RAM:wStringBuffer}!",
  ["_PokemonFanClubReceptionistText"] = "Nosso presidente é\nbem tagarela\vquando o assunto\vé POKéMON.",
  ["_PokemonFanClubSeelFanBetterText"] = "Ah, querido!\fMeu SEEL é muito\nmais incrível\vque aquele rato!",
  ["_PokemonFanClubSeelFanNormalText"] = "Eu amo meu\nquerido SEEL!\fEle dá gritinhos\nquando o abraço!",
  ["_PokemonFanClubSeelText"] = "SEEL: Syuoo!",
  ["_PokemonFanClubSign1Text"] = "Vamos todos ser\neducados e ouvir\vaos demais\vtreinadores!",
  ["_PokemonFanClubSign2Text"] = "Se alguém estiver\nse gabando, pode\vse gabar também!",
  ["_PokemonFightingFitText"] = "Aqui está!\nSeus POKéMON já\vestão prontos\vpara as batalhas!",
  ["_PokemonMansion1FScientistAfterBattleText"] = "Uma chave? Eu não\nfaço ideia do que\vvocê está falando.",
  ["_PokemonMansion1FScientistBattleText"] = "Quem é você? Não\ndeveria ter mais\vninguém aqui.",
  ["_PokemonMansion1FScientistEndBattleText"] = "Ai!",
  ["_PokemonMansion1FSwitchNotPressedText"] = "Agora não!",
  ["_PokemonMansion1FSwitchPressedText"] = "Por que não?!",
  ["_PokemonMansion1FSwitchText"] = "Um botão secreto!\fApertar o botão?",
  ["_PokemonMansion2FDiary1Text"] = "Diário:\n‘5 de Julho'\vGuiana,\vAmérica do Sul\fUm novo POKéMON\nfoi descoberto\vnas profundezas\vda selva.",
  ["_PokemonMansion2FDiary2Text"] = "Diário:\n‘10 de Julho'\vNós batizamos o\vnovo POKéMON des-\vcoberto, de MEW.",
  ["_PokemonMansion2FSuperNerdAfterBattleText"] = "Os botões abrem e\nfecham portas de\vmaneira alternada!",
  ["_PokemonMansion2FSuperNerdBattleText"] = "Não consigo sair!\nEssa casa velha é\vum labirinto!",
  ["_PokemonMansion2FSuperNerdEndBattleText"] = "Ah, não!\nMeu saco de\vpilhagem rasgou.",
  ["_PokemonMansion2FSwitchNotPressedText"] = "Ainda não!",
  ["_PokemonMansion2FSwitchPressedText"] = "Quem não o faria?",
  ["_PokemonMansion2FSwitchText"] = "Um botão secreto!\fApertar?",
  ["_PokemonMansion3FDiaryText"] = "Diário: \n‘6 de Fevereiro'\vMEW gerou vida.\fNós batizamos o\nnovo POKéMON de\vMEWTWO.",
  ["_PokemonMansion3FScientistAfterBattleText"] = "Então, está perdi-\ndo? Tente pular\ve descer por ali!",
  ["_PokemonMansion3FScientistBattleText"] = "Meu mentor já\nmorou aqui.",
  ["_PokemonMansion3FScientistEndBattleText"] = "Ufa!\nAvassalador!",
  ["_PokemonMansion3FSuperNerdAfterBattleText"] = "Onde será que meu\nparceiro se meteu?",
  ["_PokemonMansion3FSuperNerdBattleText"] = "Esse lugar é,\ntipo, enorme!",
  ["_PokemonMansion3FSuperNerdEndBattleText"] = "Aiaa!",
  ["_PokemonMansionB1FBurglarAfterBattleText"] = "Você pode achar\nalgumas coisas\vpelo chão daqui.",
  ["_PokemonMansionB1FBurglarBattleText"] = "Oh-oh. Onde eu\nestou agora?",
  ["_PokemonMansionB1FBurglarEndBattleText"] = "Auuu!",
  ["_PokemonMansionB1FDiaryText"] = "Diário: \n‘01 de Setembro'\vMEWTWO é muito\vpoderoso.\fNós falhamos em\nconter seu ins-\vtinto violento.\v...",
  ["_PokemonMansionB1FScientistAfterBattleText"] = "Eu gosto daqui!\nÉ útil para meus\vestudos!",
  ["_PokemonMansionB1FScientistBattleText"] = "Esse lugar é\nideal para um\vlaboratório.",
  ["_PokemonMansionB1FScientistEndBattleText"] = "O que\nfoi isso?",
  ["_PokemonSellingGreetingText"] = "O que gostaria\nde vender?",
  ["_PokemonStuffText"] = "Uau! Toneladas de\ncoisas POKéMON!",
  ["_PokemonTower1FBaldingGuyText"] = "Vim orar pelo\nmeu CLEFAIRY.\fSnif! Não consigo\nconter minhas\vlágrimas...",
  ["_PokemonTower1FChannelerText"] = "Sou um EXORCISTA!\nExistem espíritos\vmalignos a solta!",
  ["_PokemonTower1FGirlText"] = "Meu GROWLITHE...\nPor que você\vteve que partir?",
  ["_PokemonTower1FMiddleAgedWomanText"] = "Você veio prestar\ncondolências?\vSeja abençoado!",
  ["_PokemonTower1FReceptionistText"] = "A TORRE POKéMON\nfoi erguida em\vmemória aos POKé-\vMON que morreram.",
  ["_PokemonTower2FChannelerText"] = "Nem mesmo nós po-\ndemos identificar\vesses FANTASMAs\vrebeldes!\fUm SILPHOSCÓPIO\npode conseguir\vdesmascará-los.",
  ["_PokemonTower2FRivalDefeatedText"] = "Que?\nSeu nojento!\fEu estava pegando\nleve com você!",
  ["_PokemonTower2FRivalHowsYourDexText"] = "E sua POKéDEX,\ncomo está indo?\vEu acabei de cap-\vturar um CUBONE!\fSó não encontrei\nainda a sua evo-\vlução, o MAROWAK!\fDuvido que tenha\nsobrado algum!\vBem, é melhor eu\vme mandar! Tenho\vmais o que fazer.\fFalou, tamo junto!",
  ["_PokemonTower2FRivalVictoryText"] = "{RIVAL}: Bem,\nolha só como os\vseus POKéMON\vsão fracotes!\fTreine-os um pouco\nmais!",
  ["_PokemonTower2FRivalWhatBringsYouHereText"] = "{RIVAL}: Ei,\n{PLAYER}! O que\vte traz aqui?\vSeus POKéMON não\vparecem mortos!\fMas eu posso fazer\neles desmaiarem!\vVamos nessa, cara!",
  ["_PokemonTower3FChanneler1AfterBattleText"] = "Os FANTASMAs podem\nser identificados\vse você possuir\vum SILPHOSCÓPIO.",
  ["_PokemonTower3FChanneler1BattleText"] = "Urrg...Awaa...\nHuhu...graa..",
  ["_PokemonTower3FChanneler1EndBattleText"] = "Ufa!\nEstou salva!",
  ["_PokemonTower3FChanneler2AfterBattleText"] = "Me perdoe! Eu\nestava possuída!",
  ["_PokemonTower3FChanneler2BattleText"] = "Kekeke....\nKwaaah!",
  ["_PokemonTower3FChanneler2EndBattleText"] = "Hã?\nO que eu fiz?",
  ["_PokemonTower3FChanneler3AfterBattleText"] = "Minhas amigas\ntambém foram\vpossuídas!",
  ["_PokemonTower3FChanneler3BattleText"] = "Vá embora!\nEspírito maligno!",
  ["_PokemonTower3FChanneler3EndBattleText"] = "Ufa! O\nespírito se foi!",
  ["_PokemonTower4FChanneler1AfterBattleText"] = "Eu devia estar\nsonhando...",
  ["_PokemonTower4FChanneler1BattleText"] = "FANTASMA! Não!\nKwaaah!",
  ["_PokemonTower4FChanneler1EndBattleText"] = "Onde\nestá o FANTASMA?",
  ["_PokemonTower4FChanneler2AfterBattleText"] = "Nós não consegui-\nmos desvendar a\videntidade desses\vFANTASMAs.",
  ["_PokemonTower4FChanneler2BattleText"] = "Seja amaldiçoado\ncomigo! Kwaaah!",
  ["_PokemonTower4FChanneler2EndBattleText"] = "Que!",
  ["_PokemonTower4FChanneler3AfterBattleText"] = "Que as almas dos\nPOKéMON que já se\vforam, descansem\vem paz...",
  ["_PokemonTower4FChanneler3BattleText"] = "Huhuhu...\nNão me derrotará!",
  ["_PokemonTower4FChanneler3EndBattleText"] = "Hã?\nQuem? O quê?",
  ["_PokemonTower5FChanneler1Text"] = "Venha, criança! Eu\nselei esse espaço\vcom magia branca!\fVocê pode descan-\nsar aqui!",
  ["_PokemonTower5FChanneler2AfterBattleText"] = "Eu estava\npossuída!",
  ["_PokemonTower5FChanneler2BattleText"] = "Me...dê...\nsua...alma...",
  ["_PokemonTower5FChanneler2EndBattleText"] = "Ufa!",
  ["_PokemonTower5FChanneler3AfterBattleText"] = "Eu estava mesmo\npossuída!",
  ["_PokemonTower5FChanneler3BattleText"] = "Você...deve...\nvir...conosco...",
  ["_PokemonTower5FChanneler3EndBattleText"] = "Mas\nque pesadelo!",
  ["_PokemonTower5FChanneler4AfterBattleText"] = "Eu recuperei\nmeus sentidos!",
  ["_PokemonTower5FChanneler4BattleText"] = "Zumbis!",
  ["_PokemonTower5FChanneler4EndBattleText"] = "Hã?",
  ["_PokemonTower5FChanneler5AfterBattleText"] = "Apesar do meu\ntreinamento, fui\vdominada pelos\vespíritos do mal.",
  ["_PokemonTower5FChanneler5BattleText"] = "Blargh...\nArgh....",
  ["_PokemonTower5FChanneler5EndBattleText"] = "Ufa!",
  ["_PokemonTower5FPurifiedZoneText"] = "Entrou na área\nprotegida!\fSeus POKéMON\nse recuperaram!",
  ["_PokemonTower6FBeGoneText"] = "Vão embora...\nIntrusos...",
  ["_PokemonTower6FChanneler1AfterBattleText"] = "Me sinto anêmica\ne fraca...",
  ["_PokemonTower6FChanneler1BattleText"] = "Me...dê...\nsangue...",
  ["_PokemonTower6FChanneler1EndBattleText"] = "Arghh!",
  ["_PokemonTower6FChanneler2AfterBattleText"] = "Não caiu nada!\nEra um espírito\vmalígno!",
  ["_PokemonTower6FChanneler2BattleText"] = "Argh... Eca!",
  ["_PokemonTower6FChanneler2EndBattleText"] = "Algo\ncaiu em mim!",
  ["_PokemonTower6FChanneler3AfterBattleText"] = "O que aconteceu\naqui?",
  ["_PokemonTower6FChanneler3BattleText"] = "He..he...he...\nhe..he...he!!",
  ["_PokemonTower6FChanneler3EndBattleText"] = "Ahhh!",
  ["_PokemonTower6FGhostWasCubonesMotherText"] = "O FANTASMA era a\nalma inquieta da\vmãe dos CUBONEs!",
  ["_PokemonTower6FSoulWasCalmedText"] = "Ela finalmente\nse acalmou.\fE partiu para\no além-vida!",
  ["_PokemonTower7FMrFujiRescueText"] = "SR.FUJI: Hã? Você\nveio me salvar?\fObrigado, mas eu\nvim até aqui por\vconta própria.\fVim para tentar\nacalmar a alma da\vmãe dos CUBONEs.\fMas acho que o es-\npírito da MAROWAK\vjá partiu para o\valém-vida...\fDevo te agradecer\npor sua bondosa\vpreocupação!\fVenha comigo até a\nCASA POKéMON, no\vcentro da cidade!",
  ["_PokemonTower7FRocket1AfterBattleText"] = "Eu não vou me\nesquecer disso!",
  ["_PokemonTower7FRocket1BattleText"] = "O que você quer?\nPor que está aqui?",
  ["_PokemonTower7FRocket1EndBattleText"] = "Desisto!",
  ["_PokemonTower7FRocket2AfterBattleText"] = "POKéMON são bons\napenas pra fazer\vdinheiro!\fFique fora dos\nnossos negócios!",
  ["_PokemonTower7FRocket2BattleText"] = "Esse velhote veio\nreclamar que nós\vestamos ferindo\vPOKéMON inúteis!\fEstamos resolvendo\nisso como adultos!",
  ["_PokemonTower7FRocket2EndBattleText"] = "Por favor!\nChega!",
  ["_PokemonTower7FRocket3AfterBattleText"] = "Você não vai\nescapar dessa!",
  ["_PokemonTower7FRocket3BattleText"] = "Não está ajudando\nninguém, moleque!",
  ["_PokemonTower7FRocket3EndBattleText"] = "Não\nse meta conosco,\va EQUIPE ROCKET!",
  ["_PoliwagDexEntry"] = "Suas pernas recém-\nnascidas não lhe\ndeixam correr. Ele\fprefere continuar\nnadando do que\ntentar caminhar",
  ["_PoliwhirlDexEntry"] = "Capaz de viver\ndentro e fora da\nágua. Quando está\ffora, sua bastante\npara manter seu\ncorpo úmido",
  ["_PoliwrathDexEntry"] = "Um exímio nadador,\nna modalidade de\npeito e borboleta,\ffacilmente vencen-\ndo os melhores\nnadadores humanos",
  ["_PonytaDexEntry"] = "Seus cascos são 10\nvezes mais duros\nque diamante. Pode\fpisotear qualquer\ncoisa em instan-\ntes, até virar pó",
  ["_PoofText"] = " Puf!",
  ["_PorygonDexEntry"] = "Um POKéMON feito\ninteiramente em\ncódigo de progra-\fmação. Capaz de se\nmover livremente\nno ciberespaço",
  ["_PotionText"] = "{RAM:wNameBuffer}\nrecuperou {NUM:wHPBarHPDifference, 2, 3} PS!",
  ["_PowerPlantVoltorbBattleText"] = "Bzzzt!",
  ["_PowerPlantZapdosBattleText"] = "Gyaoo!",
  ["_PrimeapeDexEntry"] = "Está sempre furio-\nso e pronto para\natacar. Nunca para\fde perseguir sua\npresa até que con-\nsiga capturá-las",
  ["_PsyduckDexEntry"] = "Enquanto distrai\nseus inimigos com\nseu olhar vago,\fesse POKéMON astu-\nto usa seus pode-\nres telecinéticos",
  ["_PushStartText"] = "Aperte START para\nabrir o MENU!",
  ["_RaichuDexEntry"] = "Sua longa cauda\nserve como fio\nterra para se\fproteger de sua\nprópria alta\nvoltagem",
  ["_RaisePPWhichTechniqueText"] = "Aumentar PP de\nqual técnica?",
  ["_RanAwayScaredText"] = "{TARGET}\nfugiu de susto!",
  ["_RanFromBattleText"] = "{USER}\nfugiu da batalha!",
  ["_RapidashDexEntry"] = "Muito competitivo,\nesse POKéMON vai\nperseguir qualquer\fcoisa que se mova\nrápido apenas para\napostar corrida",
  ["_RareCandyText"] = "{RAM:wNameBuffer} subiu\npara o nível {NUM:wCurEnemyLevel, 1, 3}!",
  ["_RaticateDexEntry"] = "Usa seus bigodes\npara manter o seu\nequilíbrio. E apa-\frenta andar mais\ndevagar caso eles\nforem cortados",
  ["_RattataDexEntry"] = "Morde qualquer \ncoisa quando é\natacado. Pequenos\fe bem rápidos, são\numa visão comum em\nvários locais",
  ["_RedBedroomSNESText"] = "¡{PLAYER} está\njugando a la\vSuper Nintendo!\f...¡Bien!\n¡Vámonos ya!",
  ["_RedsHouse1FMomLookingGreatText"] = "MÃE: Ah, que bom!\nVocê e seu\vPOKéMON estão\vótimos!\vAgora se cuide!",
  ["_RedsHouse1FMomWakeUpText"] = "MÃE: Certo. Todos\nos meninos deixam\vo lar um dia.\vEu vi isso na TV.\fO vizinho do lado,\nPROF.CARVALHO,\vestá procurando\vpor você.",
  ["_RedsHouse1FMomYouShouldRestText"] = "MÃE: {PLAYER}!\nVocê deveria des-\vcansar um pouco.",
  ["_RedsHouse1FTVStandByMeMovieText"] = "Está passando um\nfilme na tv...\fQuatro meninos\nandando nos\vtrilhos de trêm.\fMelhor eu\nir agora.",
  ["_RedsHouse1FTVWrongSideText"] = "Opa, lado errado.",
  ["_ReflectGainedArmorText"] = "{USER}\nse transformou em{SCROLL}um {RAM:wNameBuffer}!",
  ["_RegainedHealthText"] = "{USER}\nse curou!",
  ["_ReleaseWhichMonText"] = "Soltar qual\nPOKéMON?",
  ["_RepelWoreOffText"] = "O efeito do\nREPELENTE acabou.",
  ["_RequireCoinCaseText"] = "Um PORTA-FICHAS é\nnecessário!",
  ["_RestorePPWhichTechniqueText"] = "Os PP foram\nrestaurados.",
  ["_ReviveText"] = "{RAM:wNameBuffer}\nreviveu!",
  ["_RhydonDexEntry"] = "Protegido por um\ncouro que parece\numa armadura, ele\fé capaz de viver\nem lava derretida\na 2000º Celcius",
  ["_RhyhornDexEntry"] = "Seus ossos massi-\nvos são 1000 vezes\nmais duros que os\fde um humano. Pode\nfacilmente mandar\ncarros pelos ares",
  ["_Rival1WinText"] = "{RIVAL}: Isso! Eu\nsou mesmo demais!",
  ["_RivalDefeatedText"] = "NÃO!\nNão pode ser!\vVocê derrotou os\vmeus melhores!\fDepois de todo o\ntrabalho para me\vtornar o campeão\vda LIGA?\fMeu reinado já\nse acabou?\vIsso não é justo!",
  ["_RivalVictoryText"] = "Hahaha! Eu\nvenci, eu venci!\fSou bom demais pra\nvocê, {PLAYER}!\fAté que você foi\nbem por ter che-\vgado até mim,\v{RIVAL}, o gran-\vde gênio POKéMON!\fBoa tentativa,\nperdedor!\vHahaha!",
  ["_RockTunnel1FCooltrainerF1AfterBattleText"] = "Eu vi um MACHOP\nnesse túnel!",
  ["_RockTunnel1FCooltrainerF1BattleText"] = "Ei! Não tente\nnenhuma gracinha\vaqui no escurinho!",
  ["_RockTunnel1FCooltrainerF1EndBattleText"] = "Estava\nmuito escuro!",
  ["_RockTunnel1FCooltrainerF2AfterBattleText"] = "Você parecia fofo\ne inofensivo!",
  ["_RockTunnel1FCooltrainerF2BattleText"] = "Vim tão longe\natrás de POKéMON!",
  ["_RockTunnel1FCooltrainerF2EndBattleText"] = "Fiquei\nsem POKéMON!",
  ["_RockTunnel1FCooltrainerF3AfterBattleText"] = "Ufa! Estou toda\nsuada agora!",
  ["_RockTunnel1FCooltrainerF3BattleText"] = "Você tem POKéMON!\nVamos batalhar!",
  ["_RockTunnel1FCooltrainerF3EndBattleText"] = "Você\nlutou pra valer!",
  ["_RockTunnel1FHiker1AfterBattleText"] = "Muito cuidado\ncom o ONIX!\vEle pode te dar\vum belo apertão!",
  ["_RockTunnel1FHiker1BattleText"] = "Esse túnel vai\nlonge, menino!",
  ["_RockTunnel1FHiker1EndBattleText"] = "Ugh!\nVocê venceu!",
  ["_RockTunnel1FHiker2AfterBattleText"] = "Aquele POKéMON\ndorminhoco da\vROTA 12 me forçou\va vir por aqui.",
  ["_RockTunnel1FHiker2BattleText"] = "Hmm. Acho que eu\nme perdi aqui...",
  ["_RockTunnel1FHiker2EndBattleText"] = "Ei!\nCalma aí! Onde é\vque eu estou?\vOnde é a saída?",
  ["_RockTunnel1FHiker3AfterBattleText"] = "Eu\ndesisto!",
  ["_RockTunnel1FHiker3BattleText"] = "Forasteiros como\nvocê precisam me\vmostrar respeito!",
  ["_RockTunnel1FHiker3EndBattleText"] = "Eu\ndesisto!",
  ["_RockTunnel1FSignText"] = "Eu ouvi alguns\nrumores sobre um\vgaroto prodígio!",
  ["_RockTunnel1FSuperNerdAfterBattleText"] = "Minha\narmadilha falhou.",
  ["_RockTunnel1FSuperNerdBattleText"] = "É melhor se prepa-\nrar! Que agora...\vÉ HORA DO DUELO!",
  ["_RockTunnel1FSuperNerdEndBattleText"] = "Minha\narmadilha falhou.",
  ["_RockTunnelB1FCooltrainerF1AfterBattleText"] = "Quero ir pra\ncasa!",
  ["_RockTunnelB1FCooltrainerF1BattleText"] = "Trilheiros deixam\ngalhos para\vmarcar o caminho.",
  ["_RockTunnelB1FCooltrainerF1EndBattleText"] = "Ahhh!\nDei o meu melhor!",
  ["_RockTunnelB1FCooltrainerF2AfterBattleText"] = "Eu só gosto dos\nPOKéMON pequenos,\vos grandões são\vassustadores!",
  ["_RockTunnelB1FCooltrainerF2BattleText"] = "Eu não venho muito\npor aqui, mas vou\vlutar com você.",
  ["_RockTunnelB1FCooltrainerF2EndBattleText"] = "Ah!\nEu perdi!",
  ["_RockTunnelB1FHiker1AfterBattleText"] = "Eu foco em poder\nporque odeio\vficar pensando!",
  ["_RockTunnelB1FHiker1BattleText"] = "Hahaha! Acha que\nvencerá meu poder?",
  ["_RockTunnelB1FHiker1EndBattleText"] = "Opa!\nFiquei sem força!",
  ["_RockTunnelB1FHiker2AfterBattleText"] = "Nas montanhas, é\ncomum encontrar \vPOKéMON do tipo\vpedra.",
  ["_RockTunnelB1FHiker2BattleText"] = "Minhas técnicas\nPOKéMON vão te\vfazer chorar!",
  ["_RockTunnelB1FHiker2EndBattleText"] = "Eu\ndesisto! A sua\vtécnica é melhor!",
  ["_RockTunnelB1FHiker3AfterBattleText"] = "Vou treinar mais\nmeus POKéMON só\vpara derrotarem\vos seus, pivete!",
  ["_RockTunnelB1FHiker3BattleText"] = "Me acerte com o\nseu melhor golpe!",
  ["_RockTunnelB1FHiker3EndBattleText"] = "Voei\nlonge!",
  ["_RockTunnelB1FSuperNerd1AfterBattleText"] = "Quando você\ncompletar a sua\vPOKéDEX, posso\vficar com ela?",
  ["_RockTunnelB1FSuperNerd1BattleText"] = "Você tem uma\nPOKéDEX?\vQuero uma também!",
  ["_RockTunnelB1FSuperNerd1EndBattleText"] = "\nDroga! Fiquei\vcom inveja!",
  ["_RockTunnelB1FSuperNerd2AfterBattleText"] = "Cosplayers se\nvestem de POKéMON\vpor diversão.",
  ["_RockTunnelB1FSuperNerd2BattleText"] = "Já ouviu falar\nsobre cosplayers?",
  ["_RockTunnelB1FSuperNerd2EndBattleText"] = "Bem,\nentão é isso.",
  ["_RockTunnelB1FSuperNerd3AfterBattleText"] = "Sou um artista,\nnão um guerreiro.",
  ["_RockTunnelB1FSuperNerd3BattleText"] = "Quando estou em\ncasa, eu gosto de\vdesenhar POKéMON.",
  ["_RockTunnelB1FSuperNerd3EndBattleText"] = "Puff!\nEstou exausto!",
  ["_RockTunnelPokecenterFisherText"] = "Eu vendi um pedaço\ninútil de PEPITA\vpor ¥5000!",
  ["_RockTunnelPokecenterGentlemanText"] = "Os tipos elemen-\ntais dos POKéMON\vfazem com que\vsejam fortes\vcontra alguns\vtipos e fracos\vcontra outros!",
  ["_RockTunnelPokecenterGuyText"] = "Ouvi dizer que têm\nFANTASMAS assom-\vbrando a CIDADE\vDE LAVENDER!",
  ["_RocketHide3AfterBattleText3"] = "Vá em frente!\nMas você precisa\vda CHAVE para\vusar o elevador!",
  ["_RocketHideout3BattleText"] = "Recebemos um aviso\nde cima que você\vestava a caminho!",
  ["_RocketHideout3EndBattleText3"] = "Quê?\nEu perdi? Não!",
  ["_RocketHideoutB1FRocket1AfterBattleText"] = "Ousa insultar a\nEQUIPE ROCKET?",
  ["_RocketHideoutB1FRocket1BattleText"] = "Quem é você? Como\nchegou até aqui?",
  ["_RocketHideoutB1FRocket1EndBattleText"] = "Ahh!\nFui derrotado!",
  ["_RocketHideoutB1FRocket2AfterBattleText"] = "Dessa vez você\nnão vai escapar,\vpivete!",
  ["_RocketHideoutB1FRocket2BattleText"] = "Você se meteu com\no nosso esquema?",
  ["_RocketHideoutB1FRocket2EndBattleText"] = "Tostado!",
  ["_RocketHideoutB1FRocket3AfterBattleText"] = "SILPHOSCÓPIO?\nEu não sei onde\visso está!",
  ["_RocketHideoutB1FRocket3BattleText"] = "Alerta de Intruso!",
  ["_RocketHideoutB1FRocket3EndBattleText"] = "Eu\nnão consigo!",
  ["_RocketHideoutB1FRocket4AfterBattleText"] = "Tá bem, vou falar!\nPegue o elevador\vse quiser chegar\vaté o meu CHEFE!",
  ["_RocketHideoutB1FRocket4BattleText"] = "Por que você veio\naqui?",
  ["_RocketHideoutB1FRocket4EndBattleText"] = "Isso não\nserá suficiente!",
  ["_RocketHideoutB1FRocket5AfterBattleText"] = "Eita, nossa luta\nabriu a porta!",
  ["_RocketHideoutB1FRocket5BattleText"] = "Está perdido, seu\npequeno rato?",
  ["_RocketHideoutB1FRocket5EndBattleText"] = "Por quê...?",
  ["_RocketHideoutB2FRocketAfterBattleText"] = "O QG da EQUIPE\nROCKET possui\v4 pisos. Você\vconsegue chegar\vaté o CHEFE?",
  ["_RocketHideoutB2FRocketBattleText"] = "O CHEFE disse que\npodemos ver os\vfantasmas com\vo SILPHOSCÓPIO!",
  ["_RocketHideoutB2FRocketEndBattleText"] = "Eu\ndesisto!",
  ["_RocketHideoutB3FRocket1AfterBattleText"] = "SILPHOSCÓPIO?\nA máquina que o\vCHEFE roubou...\vEstá por aqui\vem algum lugar.",
  ["_RocketHideoutB3FRocket1BattleText"] = "Pare de se meter\nnos assuntos da\vEQUIPE ROCKET!",
  ["_RocketHideoutB3FRocket1EndBattleText"] = "Ahh!\nPerdi!",
  ["_RocketHideoutB4FGiovanniHopeWeMeetAgainText"] = "Vejo que você cria\nseus POKéMON com\vmuito carinho.\fUma criança como\nvocê jamais iria\ventender o que eu\vpretendo atingir.\fSairei do seu ca-\nminho desta vez!\fEspero que nos\nencontremos nova-\vmente um dia...",
  ["_RocketHideoutB4FGiovanniImpressedYouGotHereText"] = "Então! Devo dizer\nque estou impres-\vsionado que tenha\vchegado até aqui!",
  ["_RocketHideoutB4FGiovanniWhatCannotBeText"] = "QUE!\nNão pode ser!",
  ["_RocketHideoutB4FRocket1AfterBattleText"] = "Você tem alguma\ncoisa contra a\vEQUIPE ROCKET?",
  ["_RocketHideoutB4FRocket1BattleText"] = "Eu te conheço!\nVocê que arruinou\vnossos planos na\vMONTANHA DA LUA!",
  ["_RocketHideoutB4FRocket1EndBattleText"] = "Perdi\nde novo!",
  ["_RocketHideoutB4FRocket2AfterBattleText"] = "CHEFE! Me perdoe,\neu falhei!",
  ["_RocketHideoutB4FRocket2BattleText"] = "Como você não\nconsegue ver a\vbeleza na maldade?",
  ["_RocketHideoutB4FRocket2EndBattleText"] = "Aiaia!",
  ["_RocketHideoutB4FRocket3AfterBattleText"] = "Ah, não! Eu deixei\na CHAVE cair!",
  ["_RocketHideoutB4FRocket3BattleText"] = "O elevador não\nfunciona? Hmm...\vCom quem será que\vestá a CHAVE?",
  ["_RocketHideoutB4FRocket3EndBattleText"] = "Não!",
  ["_RocketHideoutElevatorAppearsToNeedKeyText"] = "Parece precisar de\num tipo de chave.",
  ["_RoseText"] = "!",
  ["_Route10CooltrainerF1AfterBattleText"] = "Eu percebi alguns\nPOKéMANÍACOs\vandando por aí.",
  ["_Route10CooltrainerF1BattleText"] = "Já fui no GINÁSIO\nPOKéMON algumas\vvezes. Mas eu\vperdi em todas.",
  ["_Route10CooltrainerF1EndBattleText"] = "Ahh!\nPerdi de novo!",
  ["_Route10CooltrainerF2AfterBattleText"] = "Os POKéMON aqui\nsão feiosos!\vPoderia ter um\vrosinha e estam-\vpado com flores!",
  ["_Route10CooltrainerF2BattleText"] = "Já estou cansada\ncom toda essa\vcaminhada pelas\vmontanhas.",
  ["_Route10CooltrainerF2EndBattleText"] = "Não\nsirvo pra isso!",
  ["_Route10Hiker1AfterBattleText"] = "Haha-ha-tchim!\nHa-tchim!\vSnif! Snif!",
  ["_Route10Hiker1BattleText"] = "Ha-hahah-ah-ha!",
  ["_Route10Hiker1EndBattleText"] = "Ha-h!\nNão estou rindo!\vHa-héh gripe!\vHaha-ha-tchiimmm!",
  ["_Route10Hiker2AfterBattleText"] = "Estou cheio de ar\nda montanha!",
  ["_Route10Hiker2BattleText"] = "Olha o que\nvocê fez!",
  ["_Route10Hiker2EndBattleText"] = "Isso\nfoi relaxante!",
  ["_Route10PowerPlantSignText"] = "USINA ELÉTRICA",
  ["_Route10RockTunnelSignText"] = "TÚNEL ROCHOSO",
  ["_Route10SuperNerd1AfterBattleText"] = "Tenho mais POKéMON\nraros em casa!",
  ["_Route10SuperNerd1BattleText"] = "Uau, você também é\num POKéMANÍACO?\vQuer ver minha\vcoleção?",
  ["_Route10SuperNerd1EndBattleText"] = "Aff!\nNem fiquei bravo!",
  ["_Route10SuperNerd2AfterBattleText"] = "Não gosto de você,\nvocê me derrotou!",
  ["_Route10SuperNerd2BattleText"] = "Oi, criança, quer\nver meus POKéMON?",
  ["_Route10SuperNerd2EndBattleText"] = "Não!\nMeus POKéMON!",
  ["_Route11DiglettsCaveSignText"] = "CAVERNA \nDOS DIGLETT",
  ["_Route11Gambler1AfterBattleText"] = "POKéMON é vida!\nE a vida é uma\vgrande aposta!",
  ["_Route11Gambler1BattleText"] = "Vencer ou perder!",
  ["_Route11Gambler1EndBattleText"] = "Ganhar, perder\nou empatar!",
  ["_Route11Gambler2AfterBattleText"] = "Não dá pra ser\ncovarde aqui no\vmundo POKéMON!",
  ["_Route11Gambler2BattleText"] = "Competição! Não\nposso ficar sem!",
  ["_Route11Gambler2EndBattleText"] = "Eu\ntinha uma chance!",
  ["_Route11Gambler3AfterBattleText"] = "Foi uma jogada de\nsorte! Só isso!",
  ["_Route11Gambler3BattleText"] = "Uahahaha! Eu nunca\nperdi antes!",
  ["_Route11Gambler3EndBattleText"] = "Minha\nprimeira derrota!",
  ["_Route11Gambler4AfterBattleText"] = "Sorte no jogo,\nazar no amor...",
  ["_Route11Gambler4BattleText"] = "Eu nunca ganhei\nantes...",
  ["_Route11Gambler4EndBattleText"] = "Eu já\nprevia isso...",
  ["_Route11Gate1FGuardText"] = "Quando você pega\nvários POKéMON,\vfica difícil de\vpensar em nomes?\fNa CIDADE DE\nLAVENDER, tem um\vhomem que avalia\vos apelidos dos\vseus POKéMON.\fEle também poderá\nte ajudar a\vrenomeá-los!",
  ["_Route11Gate2FLeftBinocularsNoSnorlaxText"] = "Olhando pelos\nbinóculos.\fÉ uma vista\nincrível!",
  ["_Route11Gate2FLeftBinocularsSnorlaxText"] = "Olhando pelos\nbinóculos.\fUm POKéMON enorme\nestá dormindo no\vmeio do caminho!",
  ["_Route11Gate2FOaksAideItemfinderDescriptionText"] = "Tem itens no chão\nque não podem\vser vistos.\fLOCALIZADOR vai\ndetectar os itens\vperto de você.\fEle não é muito\npreciso, então\vvocê ainda vai\vter que procurar\vum pouco!",
  ["_Route11Gate2FRightBinocularsText"] = "Olhando pelos\nbinóculos.\fO único caminho\nentre a CIDADE DE\vCERULEAN e a CI-\vDADE DE LAVENDER\vé atravessando o\vTÚNEL ROCHOSO.",
  ["_Route11SuperNerd1AfterBattleText"] = "Temos que economi-\nzar a energia!",
  ["_Route11SuperNerd1BattleText"] = "Cuidado!\nEstou instalando\valguns cabos!",
  ["_Route11SuperNerd1EndBattleText"] = "Isso\nfoi eletrizante!",
  ["_Route11SuperNerd2AfterBattleText"] = "Bem, melhor voltar\nao trabalho.",
  ["_Route11SuperNerd2BattleText"] = "Cuidado com os \ncabos elétricos!",
  ["_Route11SuperNerd2EndBattleText"] = "Uau!\nVocê é chocante!",
  ["_Route11Youngster1AfterBattleText"] = "Eu dei meu melhor!\nNão me arrependo!",
  ["_Route11Youngster1BattleText"] = "Vamos nessa, mas\nsem trapaças!",
  ["_Route11Youngster1EndBattleText"] = "Hãh?\nTá certo isso?!",
  ["_Route11Youngster2AfterBattleText5"] = "O que você quer?\nMe deixe em paz!",
  ["_Route11Youngster2BattleText"] = "Virei treinador há\npouco tempo! Mas\vacho que eu já\vconsigo vencer!",
  ["_Route11Youngster2EndBattleText"] = "Não!\nMeus POKéMON!",
  ["_Route11Youngster3AfterBattleText"] = "Existe um POKéMON\ngorducho que vem\vdas montanhas.\fÉ bem forte, se\nconseguir pegá-lo.",
  ["_Route11Youngster3BattleText"] = "Sou o melhor da\nminha turma!",
  ["_Route11Youngster3EndBattleText"] = "Droga!\nTenho que deixar\vmeus POKéMON\vmais fortes!",
  ["_Route11Youngster4AfterBattleText"] = "Melhor eu procurar\nuns mais fortes!",
  ["_Route11Youngster4BattleText"] = "Meu POKéMON já\ndeveria estar\vpronto pra tudo!",
  ["_Route11Youngster4EndBattleText"] = "Ainda\nestá muito fraco!",
  ["_Route12CooltrainerMAfterBattleText"] = "Eu poderia evoluir\nmeu POKéMON com\vessa PEDRA DA LUA!",
  ["_Route12CooltrainerMBattleText"] = "Você encontrou uma\nPEDRA DA LUA?",
  ["_Route12CooltrainerMEndBattleText"] = "Uau!",
  ["_Route12Fisher1AfterBattleText"] = "Espere aí! Minha\nlinha está presa!",
  ["_Route12Fisher1BattleText"] = "Isso! Consegui uma\nfisgada, olha!",
  ["_Route12Fisher1EndBattleText"] = "Puff!\nEra um pequeno!",
  ["_Route12Fisher2AfterBattleText"] = "Se eu tivesse uma\nVARA melhor, iria\vpescar uns\vPOKéMON melhores!",
  ["_Route12Fisher2BattleText"] = "Seja paciente!\nPescaria é a\varte da espera!",
  ["_Route12Fisher2EndBattleText"] = "Esse\nfugiu!",
  ["_Route12Fisher3AfterBattleText"] = "Você ganhou em\nPOKéMON, mas na\vpescaria eu ganho!",
  ["_Route12Fisher3BattleText"] = "PATETA PESCADOR\nぇぉ PIVETE POKéMON!",
  ["_Route12Fisher3EndBattleText"] = "Essa foi\ndemais!",
  ["_Route12Fisher4AfterBattleText"] = "Tudo bem.\nPerder já não me\vincomoda mais.",
  ["_Route12Fisher4BattleText"] = "Prefiro voltar ao\ntrabalho!",
  ["_Route12Fisher4EndBattleText"] = "Não\né fácil...",
  ["_Route12Fisher5AfterBattleText"] = "Pesco MAGIKARP\no tempo todo, mas\vsão bem fracos!",
  ["_Route12Fisher5BattleText"] = "ROTA 12 \nNorte para \vCIDADE DE LAVENDER",
  ["_Route12Fisher5EndBattleText"] = "ÁREA DE\nPESCA ESPORTIVA",
  ["_Route12Gate1FGuardText"] = "Tem um mirante no\nandar de cima.",
  ["_Route12Gate2FBrunetteGirlReceivedTM39Text"] = "{PLAYER} recebeu\na MT39!",
  ["_Route12Gate2FBrunetteGirlTM39ExplanationText"] = "MT39 contém a\ntécnica chamada\vATAQUE VELOZ.\fÉ bem preciso,\nentão use nas\vbatalhas que não\vpode perder.",
  ["_Route12Gate2FBrunetteGirlTM39NoRoomText"] = "Você não tem \nespaço pra isso.",
  ["_Route12Gate2FBrunetteGirlYouCanHaveThisText"] = "As cinzas do meu\nPOKéMON estão\varmazenadas na\vTORRE POKéMON.\fVocê pode ficar\ncom essa MT. Eu\vjá não preciso...",
  ["_Route12Gate2FLeftBinocularsText"] = "Olhando pelos\nbinóculos.\fUm homem pescando!",
  ["_Route12Gate2FRightBinocularsText"] = "Olhando pelos\nbinóculos.\fÉ a TORRE POKéMON!",
  ["_Route12SignText"] = "Pesco MAGIKARP\no tempo todo, mas\vsão tão fracos!",
  ["_Route12SnorlaxCalmedDownText"] = "SNORLAX já se\nacalmou! Com um\vgrande bocejo,\vele retornou para\vas montanhas!",
  ["_Route12SnorlaxText"] = "Esse POKéMON\ndorminhoco está\vbloqueando\va passagem!",
  ["_Route12SnorlaxWokeUpText"] = "SNORLAX acordou!\fEstá furioso e\nquer batalhar!",
  ["_Route12SportFishingSignText"] = "ROTA 12 \nNorte para \vCIDADE DE LAVENDER",
  ["_Route12SuperNerdAfterBattleText"] = "Água conduz\neletricidade,\ventão você deve\veletrocutar os\vPOKéMON aquáticos!",
  ["_Route12SuperNerdBattleText"] = "Eletricidade é mi-\nnha especialidade!",
  ["_Route12SuperNerdEndBattleText"] = "Fiquei\nsem bateria!",
  ["_Route12SuperRodHouseFishingGuruDoYouLikeToFishText"] = "Eu sou o irmão\ncaçula do GURU\vDA PESCARIA!\fEu simplesmente\naaaaamo pescar!\fVocê gosta\nde pescar?",
  ["_Route12SuperRodHouseFishingGuruFishingWayOfLifeText"] = "\fPescaria é um \nestilo de vida!\fDe mares aos rios,\nvá e pesque um\vgrandão, jovem!",
  ["_Route12SuperRodHouseFishingGuruNoRoomText"] = "Ah, não!\fEu tenho um\npresente para\vpara você, mas\vvocê não tem\vespaço para ele!",
  ["_Route12SuperRodHouseFishingGuruReceivedSuperRodText"] = "SUPER! Eu gostei\ndo seu estilo!\fPegue isso e vá\npescar, jovem!\f{PLAYER} recebeu\na {RAM:wStringBuffer}!",
  ["_Route12SuperRodHouseFishingGuruThatsDisappointingText"] = "Ah... Isso é tão\ndecepcionante...",
  ["_Route12SuperRodHouseFishingGuruTryFishingText"] = "Olá, jovem\n{PLAYER}!\fUse a SUPER VARA\nem qualquer água!\vVocê pode pegar\vdiversos tipos\vde POKéMON.\fTente pescar em\nqualquer lugar\vque puder!",
  ["_Route13Beauty1AfterBattleText"] = "Você sabe quem\nvence, eu e você,\vum contra um!",
  ["_Route13Beauty1BattleText"] = "Quê?\nVocê!?",
  ["_Route13Beauty1EndBattleText"] = "ROTA 14\nOeste para\vCIDADE DE FUCHSIA",
  ["_Route13Beauty2AfterBattleText"] = "Eu não sei nada\nsobre POKéMON. Eu\vsó gosto dos mais\vfofinhos!",
  ["_Route13Beauty2BattleText"] = "Quê, quê, o quê?\nO que você quer?",
  ["_Route13Beauty2EndBattleText"] = "Já\nacabou?",
  ["_Route13BikerAfterBattleText"] = "Suma daqui!",
  ["_Route13BikerBattleText"] = "O que você\nestá olhando?",
  ["_Route13BikerEndBattleText"] = "Droga!\nParafuso torto!!",
  ["_Route13CooltrainerF1AfterBattleText"] = "Eu quero ser uma\nboa treinadora.\vVou treinar duro.",
  ["_Route13CooltrainerF1BattleText"] = "Dizem que sou uma\nmenina prodígio!",
  ["_Route13CooltrainerF1EndBattleText"] = "Ahh!\nEu perdi!",
  ["_Route13CooltrainerF2AfterBattleText"] = "Você ganhou essas\nINSÍGNIAS dos LÍ-\vDERES de GINÁSIO.\vEu já sabia!",
  ["_Route13CooltrainerF2BattleText"] = "Uau! Suas INSÍG-\nNIAS são demais!",
  ["_Route13CooltrainerF2EndBattleText"] = "Não\nfoi o bastante!",
  ["_Route13CooltrainerF3AfterBattleText"] = "É preciso fazer os\nPOKéMON lutarem\vpara que eles fi-\vquem mais fortes!",
  ["_Route13CooltrainerF3BattleText"] = "Meu POKéMON fofo\nquer ser seu\vamiguinho.",
  ["_Route13CooltrainerF3EndBattleText"] = "Uau!\nVocê me venceu!",
  ["_Route13CooltrainerF4AfterBattleText"] = "Quem será que é\nmais forte, os\vPOKéMON machos ou\vas fêmeas?",
  ["_Route13CooltrainerF4BattleText"] = "Claro, vou brincar\ncom você um pouco!",
  ["_Route13CooltrainerF4EndBattleText"] = "Oh!\nOra, seu bruto!",
  ["_Route13CooltrainerM1AfterBattleText"] = "Meu POKéMON está\nfeliz mesmo de-\vpois da derrota.",
  ["_Route13CooltrainerM1BattleText"] = "Meu POKéMON voador\nquer ciscar!",
  ["_Route13CooltrainerM1EndBattleText"] = "Meu\npássaro perdeu?",
  ["_Route13CooltrainerM2AfterBattleText"] = "Vencer, perder,\nisso não importa\vnada no final!",
  ["_Route13CooltrainerM2BattleText"] = "Você quer batalhar\ncomigo?",
  ["_Route13CooltrainerM2EndBattleText"] = "Eu\nsabia!",
  ["_Route13CooltrainerM3AfterBattleText"] = "Eu queria poder\nvoar como PIDGEY\ve PIDGEOTTO...",
  ["_Route13CooltrainerM3BattleText"] = "Eu sempre uso\nPOKéMON pássaros!",
  ["_Route13CooltrainerM3EndBattleText"] = "Eu\nfiquei sem força!",
  ["_Route13SignText"] = "ROTA 13\nAo Norte\vPONTE DO SILÊNCIO",
  ["_Route13TrainerTips1Text"] = "DICAS PARA\nTREINADORES\fOlhe para o outro\nlado dessa placa!",
  ["_Route13TrainerTips2Text"] = "DICAS PARA\nTREINADORES\fUse SELECT para\ntrocar a posição\vdos ITENS na sua\vmochila!",
  ["_Route14Biker1AfterBattleText"] = "Arrg!\nPerdi! Sai daqui!",
  ["_Route14Biker1BattleText"] = "Vamos, vamos.\nBora, bora,\vbora lá!",
  ["_Route14Biker1EndBattleText"] = "Vamos, vamos!\nBora, bora, bora!",
  ["_Route14Biker2AfterBattleText"] = "Criar POKéMON é\numa chatice, cara.",
  ["_Route14Biker2BattleText"] = "Quê, quê, o quê?\nO que você quer?",
  ["_Route14Biker2EndBattleText"] = "Quê?\nVocê!?",
  ["_Route14Biker3AfterBattleText"] = "É bom que você\nfez seus POKéMON\vficarem fortes!\fForça bruta é\no que conta!\vE você sabe disso!",
  ["_Route14Biker3BattleText"] = "Pilotamos por aqui\nporque tem mais\vespaço!",
  ["_Route14Biker3EndBattleText"] = "Fui\ndestruído!",
  ["_Route14Biker4AfterBattleText"] = "Você sabe quem\nvence, eu e você,\vum contra um!",
  ["_Route14Biker4BattleText"] = "Batalha POKéMON?\nLegal! Vrummm!",
  ["_Route14Biker4EndBattleText"] = "Que\nestouro!",
  ["_Route14CooltrainerM1AfterBattleText"] = "Você tem algumas\nMOs, não é? Os\vPOKéMON jamais se\vesquecem dessas\vtécnicas ocultas.",
  ["_Route14CooltrainerM1BattleText"] = "Você precisa usar\nMTs para ensinar\vboas técnicas aos\vseus POKéMON!",
  ["_Route14CooltrainerM1EndBattleText"] = "Não\nfui o bastante!",
  ["_Route14CooltrainerM2AfterBattleText"] = "Preciso ensiná-los\ntécnicas melhores.",
  ["_Route14CooltrainerM2BattleText"] = "Meus POKéMON pás-\nsaros já estão\vprontos pra lutar.",
  ["_Route14CooltrainerM2EndBattleText"] = "Não\nestavam prontos!",
  ["_Route14CooltrainerM3AfterBattleText"] = "Ensine técnicas do\nmesmo elemento do\vPOKéMON para ter\vmais eficácia.",
  ["_Route14CooltrainerM3BattleText"] = "MTs estão a venda\nem CELADON!\vMas poucas pes-\vsoas têm as MOs!",
  ["_Route14CooltrainerM3EndBattleText"] = "Ah,\nque chatice!",
  ["_Route14CooltrainerM4AfterBattleText"] = "Pássaros POKéMON\nsão minha paixão!",
  ["_Route14CooltrainerM4BattleText"] = "Já ensinou seu\nPOKéMON pássaro a\vtécnica VOAR?",
  ["_Route14CooltrainerM4EndBattleText"] = "Fui\nabatido!",
  ["_Route14CooltrainerM5AfterBattleText"] = "Todos os 3 POKéMON\nlendários são\vaves de rapina.",
  ["_Route14CooltrainerM5BattleText"] = "Já ouviu falar dos\nPOKéMON lendários?",
  ["_Route14CooltrainerM5EndBattleText"] = "Como?\nPor que eu perdi?",
  ["_Route14CooltrainerM6AfterBattleText"] = "Vencer, perder,\nisso não importa\vnada no final!",
  ["_Route14CooltrainerM6BattleText"] = "Não estou a fim,\nmas OK! Vamos lá!",
  ["_Route14CooltrainerM6EndBattleText"] = "Eu\nsabia!",
  ["_Route14SignText"] = "ROTA 14\nOeste para\vCIDADE DE FUCHSIA",
  ["_Route15Beauty1AfterBattleText"] = "Eu te perdoo!\nPosso aturar isso!",
  ["_Route15Beauty1BattleText"] = "Oh, você é\numa gracinha!",
  ["_Route15Beauty1EndBattleText"] = "Você\nparecia fofinho!",
  ["_Route15Beauty2AfterBattleText"] = "Eu só quero ir pra\ncasa ficar com\vmeus POKéMON!",
  ["_Route15Beauty2BattleText"] = "Eu crio POKéMON\nporque eu moro\vsozinha!",
  ["_Route15Beauty2EndBattleText"] = "Eu não\npedi por isso!",
  ["_Route15Biker1AfterBattleText"] = "Aquele lance da\ngrana era só uma\vbrincadeira!",
  ["_Route15Biker1BattleText"] = "Mas\npor quê?",
  ["_Route15Biker1EndBattleText"] = "Não\npode ser verdade!",
  ["_Route15Biker2AfterBattleText"] = "Oh, você é\numa gracinha!",
  ["_Route15Biker2BattleText"] = "Vai me dar toda\nsua grana quando\vperder, garoto!",
  ["_Route15Biker2EndBattleText"] = "Isso\nnão pode ser real!",
  ["_Route15CooltrainerF1AfterBattleText"] = "Você não pode\nmudar o apelido\vde nenhum POKéMON\vque você receber\vem uma troca.\fApenas o Treinador\nOriginal pode.",
  ["_Route15CooltrainerF1BattleText"] = "Deixe-me testar o\nnovo POKéMON que\veu acabei de ga-\vnhar em uma troca!",
  ["_Route15CooltrainerF1EndBattleText"] = "Não foi\nbom o bastante!",
  ["_Route15CooltrainerF2AfterBattleText"] = "Eu tenho medo dos\nMOTOQUEIROs, eles\vparecem ser tão\vmalvados e feios!",
  ["_Route15CooltrainerF2BattleText"] = "Você parece ser\ngentil, então eu\vacho que posso te\vderrotar!",
  ["_Route15CooltrainerF2EndBattleText"] = "Não,\nerrei feio!",
  ["_Route15CooltrainerF3AfterBattleText"] = "Eu troco POKéMON\ncom meus amigos!",
  ["_Route15CooltrainerF3BattleText"] = "Você\nparecia fofinho!",
  ["_Route15CooltrainerF3EndBattleText"] = "Eu\ndisse trocas!",
  ["_Route15CooltrainerF4AfterBattleText"] = "Vou praticar com\nalguém mais fraco.",
  ["_Route15CooltrainerF4BattleText"] = "Quer brincar com\nmeu POKéMON?",
  ["_Route15CooltrainerF4EndBattleText"] = "Eu fui\nmuito impaciente!",
  ["_Route15CooltrainerM1AfterBattleText"] = "Acho que batalhar\nnão é pra mim.",
  ["_Route15CooltrainerM1BattleText"] = "Com um assobio, eu\nposso chamar meus\vpássaros POKéMON!",
  ["_Route15CooltrainerM1EndBattleText"] = "Ah!\nIsso foi trágico!",
  ["_Route15CooltrainerM2AfterBattleText"] = "Você sabia que\nos golpes como\vTERREMOTO não tem\vefeito algum nos\vpássaros?",
  ["_Route15CooltrainerM2BattleText"] = "Hmm? Meus pássaros\nse eriçaram! Você\vé forte, não é?",
  ["_Route15CooltrainerM2EndBattleText"] = "Foi\ncomo eu pensei!",
  ["_Route15Gate1FGuardText"] = "É você quem está\ntrabalhando com\vuma POKéDEX?\fUm ajudante do\nPROF.CARVALHO\vesteve por aqui.",
  ["_Route15Gate2FBinocularsText"] = "Olhando pelos\nbinóculos.\fParece ser um\npequena ilha!",
  ["_Route15Gate2FOaksAideExpAllText"] = "Com o COMPART.EXP.\nos Pontos de EXP.\vserão divididos\ventre todos os\vPOKéMON com você,\vmesmo se eles não\vbatalharem.\fEntretanto, ele\nreduz a quantia\vde EXP. que cada\vPOKéMON receberá.\fSe você não preci-\nsar disso, é só\vguardar ele no PC.",
  ["_Route15SignText"] = "ROTA 15\nAo oeste para\vCIDADE DE FUCHSIA",
  ["_Route15UpstairsBinocularsText"] = "Olhou pelos\nbinóculos...\fUma grande e\nbrilhante ave\vestá voando em\vdireção ao mar.",
  ["_Route16Biker1AfterBattleText"] = "Nós viemos aqui\nficar de boa, o\vque você tem com\visso?",
  ["_Route16Biker1BattleText"] = "O que você quer?",
  ["_Route16Biker1EndBattleText"] = "Não se\natreva a rir!",
  ["_Route16Biker2AfterBattleText"] = "Seu\nrato sujo!",
  ["_Route16Biker2BattleText"] = "Bela BICICLETA!\nPassa pra cá!",
  ["_Route16Biker2EndBattleText"] = "Fui\nderrotado!",
  ["_Route16Biker3AfterBattleText"] = "Esse é meu local\nfavorito de caçar\vPOKéMON!",
  ["_Route16Biker3BattleText"] = "Essa é minha área!\nSaia já daqui!",
  ["_Route16Biker3EndBattleText"] = "\nDroga!",
  ["_Route16Biker4AfterBattleText"] = "Você também pode\nchegar na CIDADE\vDE FUCHSIA indo\vpela CIDADE DE\vVERMILION usando\va rota costeira.",
  ["_Route16Biker4EndBattleText"] = "Kabum!",
  ["_Route16Biker5AfterBattleText"] = "Eu gosto dos\nPOKéMON ferozes!\vEles destroçam\vos oponentes!",
  ["_Route16Biker5BattleText"] = "Estou me sentindo\nfaminto e malvado!",
  ["_Route16Biker5EndBattleText"] = "Mal,\nmal, mal!",
  ["_Route16Biker6AfterBattleText"] = "Adoro assustar\npessoas com meus\vPOKéMON cruéis!",
  ["_Route16Biker6BattleText"] = "Tudo bem,\nvou embora!",
  ["_Route16Biker6EndBattleText"] = "Não me\ndeixe nervoso!",
  ["_Route16CyclingRoadSignText"] = "Aproveite a\nladeira!\vROTA DO CICLISMO",
  ["_Route16FlyHouseBrunetteGirlHM02ExplanationText"] = "MO02 contém VOAR.\nCom isso você po-\vderá voltar para\vqualquer cidade.\fFaça bom uso\ndisso!",
  ["_Route16FlyHouseBrunetteGirlHM02NoRoomText"] = "Você não tem mais\nespaço para isso.",
  ["_Route16FlyHouseBrunetteGirlReceivedHM02Text"] = "{PLAYER} recebeu\na MO02!",
  ["_Route16FlyHouseBrunetteGirlText"] = "Ah, você achou meu\nretiro secreto!\fPor favor não\nconte pra ninguém\vque estou aqui.\vEu vou te recom-\vpensar com isso!",
  ["_Route16FlyHouseFearowText"] = "FEAROW: Kyueen!",
  ["_Route16Gate1FGamblerText"] = "Como você entrou?\nBom trabalho!",
  ["_Route16Gate1FGuardCyclingRoadExplanationText"] = "A ROTA DO CICLISMO\né um caminho\vladeira abaixo\vpela costa. É uma\vbela pedalada.",
  ["_Route16Gate1FGuardNoPedestriansAllowedText"] = "Nenhum pedestre é\npermitido na\vROTA DO CICLISMO!",
  ["_Route16Gate1FGuardWaitUpText"] = "Com licença! Espe-\nre aí, por favor!",
  ["_Route16Gate2FLeftBinocularsText"] = "Olhando pelos\nbinóculos.\fÉ o CENTRO COMER-\nCIAL DE CELADON!",
  ["_Route16Gate2FLittleBoyText"] = "Estou indo dar uma\npedalada com a\vminha namorada!",
  ["_Route16Gate2FLittleGirlText"] = "Nós vamos pedalar\njuntos!",
  ["_Route16Gate2FRightBinocularsText"] = "Olhando pelos\nbinóculos.\fÉ uma longa trilha\nsobre a água!",
  ["_Route16SignText"] = "ROTA 16\nCIDADE DE CELADON\v-CIDADE DE FUCHSIA",
  ["_Route16SnorlaxReturnedToMountainsText"] = "SNORLAX já se\nacalmou! Com um\vgrande bocejo,\vele retornou para\vas montanhas!",
  ["_Route16SnorlaxWokeUpText"] = "SNORLAX acordou!\fEstá furioso e\nquer batalhar!",
  ["_Route16Text7"] = "Esse POKéMON\ndorminhoco está\vbloqueando\va passagem!",
  ["_Route16biker4BattleText"] = "Ei, você me\natropelou!",
  ["_Route17Biker10AfterBattleText"] = "Eu quero capturar\num SONINHO!",
  ["_Route17Biker10BattleText"] = "Sai fora, menino!\nEstou cansadão!",
  ["_Route17Biker10EndBattleText"] = "Está\nsatisfeito?",
  ["_Route17Biker1AfterBattleText"] = "Coisa boa mesmo é\nficar de boa na\vROTA DO CICLISMO!",
  ["_Route17Biker1BattleText"] = "Não dá lucro lutar\ncom criancinhas!",
  ["_Route17Biker1EndBattleText"] = "Perdi\nfeio!",
  ["_Route17Biker2AfterBattleText"] = "Eu posso te dar\numa barrigada pra\vbem longe daqui!",
  ["_Route17Biker2BattleText"] = "O que você quer,\nmoleque?",
  ["_Route17Biker2EndBattleText"] = "Uoou!",
  ["_Route17Biker3AfterBattleText"] = "Eu amo correr\nladeira abaixo!",
  ["_Route17Biker3BattleText"] = "Você está indo\npara FUCHSIA?",
  ["_Route17Biker3EndBattleText"] = "Fiquei\nfrito e tostado!",
  ["_Route17Biker4AfterBattleText"] = "Está procurando\npor uma aventura?",
  ["_Route17Biker4BattleText"] = "Somos MOTOQUEIROs!\nRumo às estrelas!",
  ["_Route17Biker4EndBattleText"] = "Fui\ndefumado!",
  ["_Route17Biker5AfterBattleText"] = "Peguei meu VOLTORB\nna USINA ELÉTRICA\vabandonada.",
  ["_Route17Biker5BattleText"] = "Deixe meu VOLTORB\neletrocutar você!",
  ["_Route17Biker5EndBattleText"] = "Estou\nchocado!",
  ["_Route17Biker6AfterBattleText"] = "Acho que alguns\nPOKéMON precisam\vde PEDRAs elemen-\vtais para evoluir.",
  ["_Route17Biker6BattleText"] = "Meu POKéMON não\nevolui! Por quê?",
  ["_Route17Biker6EndBattleText"] = "Me\ndiga o porquê!",
  ["_Route17Biker7AfterBattleText"] = "Tenho certeza que\nperdi peso nessa!",
  ["_Route17Biker7BattleText"] = "Estou precisando\nde um exercício!",
  ["_Route17Biker7EndBattleText"] = "Ufa!\nBom aquecimento!",
  ["_Route17Biker8AfterBattleText"] = "Prepare-se para\nlutar pela sua fé!",
  ["_Route17Biker8BattleText"] = "Seja rebelde!",
  ["_Route17Biker8EndBattleText"] = "Aargh!",
  ["_Route17Biker9AfterBattleText"] = "A descida dificul-\nta a direção aqui!",
  ["_Route17Biker9BattleText"] = "Bela BICICLETA!\nComo é o guidão?",
  ["_Route17Biker9EndBattleText"] = "Puxa!",
  ["_Route17CyclingRoadEndsSignText"] = "ROTA DO CICLISMO\nFim da ladeira!",
  ["_Route17NoticeSign1Text"] = "É um aviso!\fFique alerta para\nitens perdidos!",
  ["_Route17NoticeSign2Text"] = "É um aviso!\fNão arremesse o\njogo longe, em\vvez disso, arre-\vmesse POKé BOLAS.",
  ["_Route17SignText"] = "ROTA 17\nCIDADE DE CELADON\v-CIDADE DE FUCHSIA",
  ["_Route17TrainerTips1Text"] = "DICAS PARA\nTREINADORES\fTodos os POKéMON\nsão únicos.\fAté mesmo POKéMON\ndo mesmo tipo e\vnível crescem de\vformas diferentes.",
  ["_Route17TrainerTips2Text"] = "DICAS PARA\nTREINADORES\fPressione o botão\nA ou B para ficar\vparado na descida.",
  ["_Route18CooltrainerM1AfterBattleText"] = "Eu queria ter uma\nBICICLETA!",
  ["_Route18CooltrainerM1BattleText"] = "Eu sempre checo\ntoda área gramada\và procura de\vnovos POKéMON.",
  ["_Route18CooltrainerM1EndBattleText"] = " \nTch!",
  ["_Route18CooltrainerM2AfterBattleText"] = "Também caço os\nPOKéMON marinhos\vnos domingos!",
  ["_Route18CooltrainerM2BattleText"] = "Curucuu!\nO que achou do meu\vcanto de pássaro?",
  ["_Route18CooltrainerM2EndBattleText"] = "Eu\ntinha que tentar!",
  ["_Route18CooltrainerM3AfterBattleText"] = "Esse é meu local\nfavorito de caçar\vPOKéMON!",
  ["_Route18CooltrainerM3BattleText"] = "Essa é minha área!\nSaia já daqui!",
  ["_Route18CooltrainerM3EndBattleText"] = "\nDroga!",
  ["_Route18CyclingRoadSignText"] = "ROTA DO CICLISMO\nEntrada Proibida\vpara pedestres!",
  ["_Route18Gate1FGuardCyclingRoadUphillText"] = "ROTA DO CICLISMO é\num longo caminho\vladeira acima.",
  ["_Route18Gate1FGuardExcuseMeText"] = "Com licença!",
  ["_Route18Gate1FGuardYouNeedABicycleText"] = "Você precisa de\numa BICICLETA\vpara entrar na\vROTA DO CICLISMO!",
  ["_Route18Gate2FLeftBinocularsText"] = "Olhando pelos\nbinóculos.\fAo oeste se vê a\nCIDADE DE PALLET!",
  ["_Route18Gate2FRightBinocularsText"] = "Olhando pelos\nbinóculos.\fAlgumas pessoas\nnadando ao sul!",
  ["_Route18SignText"] = "ROTA 17\nCIDADE DE CELADON\v-CIDADE DE FUCHSIA",
  ["_Route19CooltrainerM1AfterBattleText"] = "Obrigado, menino!\nEstou pronto para\vir nadar!",
  ["_Route19CooltrainerM1BattleText"] = "Preciso me aquecer\nantes de ir nadar!",
  ["_Route19CooltrainerM1EndBattleText"] = "Agora\nestou aquecido!",
  ["_Route19CooltrainerM2AfterBattleText"] = "Tome cuidado com\nos TENTACOOL!",
  ["_Route19CooltrainerM2BattleText"] = "Calma aí! Não vá\nter um treco!",
  ["_Route19CooltrainerM2EndBattleText"] = "Ooh!\nFoi refrescante!",
  ["_Route19SignText"] = "ROTA MARÍTIMA 19\nCIDADE DE FUCHSIA\f- ILHAS ESPUMA\nDO MAR",
  ["_Route19Swimmer1AfterBattleText"] = "Nado melhor que\nmuitos POKéMON!",
  ["_Route19Swimmer1BattleText"] = "Eu adoro nadar!\nE você?",
  ["_Route19Swimmer1EndBattleText"] = "Caí\nde barriga!",
  ["_Route19Swimmer2AfterBattleText"] = "Eu consigo ver al-\ngumas ilhas daqui!",
  ["_Route19Swimmer2BattleText"] = "O que é aquilo\nalém do horizonte?",
  ["_Route19Swimmer2EndBattleText"] = "Glub!\nGlub!",
  ["_Route19Swimmer3AfterBattleText"] = "Preciso de uma\nVARA para pescar\vPOKéMON marinhos!",
  ["_Route19Swimmer3BattleText"] = "Eu tentei mergu-\nlhar para pegar\vPOKéMON, mas não\vfoi uma boa ideia!",
  ["_Route19Swimmer3EndBattleText"] = "Socorro!",
  ["_Route19Swimmer4AfterBattleText"] = "Estou olhando para\no mar para esque-\vcer dessa derrota!",
  ["_Route19Swimmer4BattleText"] = "Socorro!",
  ["_Route19Swimmer4EndBattleText"] = "Ooh!\nTraumático!",
  ["_Route19Swimmer5AfterBattleText"] = "Estou olhando para\no mar para esque-\vcer dessa derrota!",
  ["_Route19Swimmer5BattleText"] = "Eu olho para o mar\npara esquecer dos\vmeus problemas!",
  ["_Route19Swimmer5EndBattleText"] = "Ooh!\nTraumático!",
  ["_Route19Swimmer6AfterBattleText"] = "Meu namorado quis\nir nadando até \vas ILHAS ESPUMA\vDO MAR.",
  ["_Route19Swimmer6BattleText"] = "Ah!\nEu perdi!",
  ["_Route19Swimmer6EndBattleText"] = "Fiquei\nchocada!",
  ["_Route19Swimmer7AfterBattleText"] = "Me deu uma cãibra!\nGlub, glub...",
  ["_Route19Swimmer7BattleText"] = "Essas águas são\ntraiçoeiras!",
  ["_Route19Swimmer7EndBattleText"] = "Ooh!\nPerigoso!",
  ["_Route19Swimmer8AfterBattleText"] = "LAPRAS é tão gran-\nde que te deixa\vseco até na água.",
  ["_Route19Swimmer8BattleText"] = "Nadei até aqui,\nmas foi cansativo.",
  ["_Route19Swimmer8EndBattleText"] = "Estou\nexausta...",
  ["_Route1SignText"] = "ROTA 1\nCIDADE DE PALLET-\vCIDADE DE VIRIDIAN",
  ["_Route1Youngster1AlsoGotPokeballsText"] = "Também temos\nPOKé BOLAs para\vcapturar POKéMON!",
  ["_Route1Youngster1GotPotionText"] = "{PLAYER} recebeu\n{RAM:wStringBuffer}!",
  ["_Route1Youngster1MartSampleText"] = "Oi! Eu trabalho na\nLOJA POKéMON.\fÉ uma lojinha de\nconveniências,\vvenha nos visitar\vlá na CIDADE\vDE VIRIDIAN.\fJá sei, vou te dar\numa amostrinha!\vAqui está!",
  ["_Route1Youngster1NoRoomText"] = "Parece que você já\nnão tem espaço!",
  ["_Route1Youngster2Text"] = "Vê esses barrancos\nao longo da rota?\fParece assustador,\nmas você pode\vpular deles.\fAssim você vai\npoder chegar na\vCIDADE DE PALLET\vbem mais rápido.",
  ["_Route20CooltrainerMAfterBattleText"] = "Meus pássaros não\npodem VOAR agora!",
  ["_Route20CooltrainerMBattleText"] = "Montar um POKéMON\nparece divertido!",
  ["_Route20CooltrainerMEndBattleText"] = "Essa\nnão!",
  ["_Route20SeafoamIslandsSignText"] = "ILHAS ESPUMA\nDO MAR",
  ["_Route20Swimmer1AfterBattleText"] = "Eu também queria\npoder SURFAR com\vmeus POKéMON!",
  ["_Route20Swimmer1BattleText"] = "A água é mais\nrasa aqui.",
  ["_Route20Swimmer1EndBattleText"] = "Tchibum!",
  ["_Route20Swimmer2AfterBattleText"] = "Tem uma caverna\nenorme embaixo\vdessa ilha.",
  ["_Route20Swimmer2BattleText"] = "Pode\nparar!",
  ["_Route20Swimmer2EndBattleText"] = "Pode\nparar!",
  ["_Route20Swimmer3AfterBattleText"] = "Quer ficar boiando\ncomigo?",
  ["_Route20Swimmer3BattleText"] = "Adoro ficar boian-\ndo com os peixes!",
  ["_Route20Swimmer3EndBattleText"] = "Ai!",
  ["_Route20Swimmer4AfterBattleText"] = "Olha só meu\ncorpão definido!",
  ["_Route20Swimmer4BattleText"] = "Você também está\nde férias?",
  ["_Route20Swimmer4EndBattleText"] = "Sem\nmisericórdia!",
  ["_Route20Swimmer5AfterBattleText"] = "Eu deveria estar\nfortalecendo meus\vPOKéMON, não eu!",
  ["_Route20Swimmer5BattleText"] = "Olha só meu\ncorpão definido!",
  ["_Route20Swimmer5EndBattleText"] = "Covarde!",
  ["_Route20Swimmer6AfterBattleText"] = "Montar um POKéMON\nparece divertido!",
  ["_Route20Swimmer6BattleText"] = "Por que você está\nmontado em um\vPOKéMON? Você não\vsabe nadar?",
  ["_Route20Swimmer6EndBattleText"] = "Au!\nFui naufragado!",
  ["_Route20Swimmer7AfterBattleText"] = "Meu namorado me\ndeu algumas péro-\vlas enormes!",
  ["_Route20Swimmer7BattleText"] = "Essa\nnão!",
  ["_Route20Swimmer7EndBattleText"] = "Meus pássaros não\npodem VOAR agora!",
  ["_Route20Swimmer8AfterBattleText"] = "POKéMON selvagem\ntomaram conta da\vmansão abandonada\vna ILHA CINNABAR!",
  ["_Route20Swimmer8BattleText"] = "Eu vim até aqui\nnadando, desde a\vILHA CINNABAR!",
  ["_Route20Swimmer8EndBattleText"] = "Estou\ntão desapontada!",
  ["_Route20Swimmer9AfterBattleText"] = "CINNABAR é uma\nilha vulcânica!",
  ["_Route20Swimmer9BattleText"] = "Lá em CINNABAR, ao\noeste daqui, tem\vum LABORATÓRIO de\vpesquisa POKéMON.",
  ["_Route20Swimmer9EndBattleText"] = "Espere!",
  ["_Route21Fisher1AfterBattleText"] = "Não consigo pescar\nnada que preste!",
  ["_Route21Fisher1BattleText"] = "Quer saber se os\npeixes estão\vmordendo a isca?",
  ["_Route21Fisher1EndBattleText"] = "Droga!",
  ["_Route21Fisher2AfterBattleText"] = "Parece que só vou\npegar MAGIKARP!",
  ["_Route21Fisher2BattleText"] = "Acho que peguei\num grandão!",
  ["_Route21Fisher2EndBattleText"] = "Droga,\noutro MAGIKARP!",
  ["_Route21Fisher3AfterBattleText"] = "Eu só fiquei ner-\nvoso pois não\vconsigo pescar\vnada.",
  ["_Route21Fisher3BattleText"] = "Ei, não assuste\nos peixes!",
  ["_Route21Fisher3EndBattleText"] = "Perdão!\nFoi sem querer!",
  ["_Route21Fisher4AfterBattleText"] = "Ei! Algo mordeu\na isca! Isso!",
  ["_Route21Fisher4BattleText"] = "Me faça companhia\naté eu pegar algo!",
  ["_Route21Fisher4EndBattleText"] = "Isso\nmatou um tempo.",
  ["_Route21Swimmer1AfterBattleText"] = "Eu gosto das\nmontanhas também!",
  ["_Route21Swimmer1BattleText"] = "O mar me limpa\nde corpo e alma!",
  ["_Route21Swimmer1EndBattleText"] = "Aiai!",
  ["_Route21Swimmer2AfterBattleText"] = "Tá olhando o quê?\nPareço uma boia\vfurada? Sai daqui!",
  ["_Route21Swimmer2BattleText"] = "Qual o problema de\neu estar nadando?",
  ["_Route21Swimmer2EndBattleText"] = "Golpe\nbaixo!",
  ["_Route21Swimmer3AfterBattleText"] = "Onde você capturou\nos seus POKéMON?",
  ["_Route21Swimmer3BattleText"] = "Eu capturei todos\nos meus POKéMON\vaqui no mar!",
  ["_Route21Swimmer3EndBattleText"] = "Afundei!\nHomem ao mar!!",
  ["_Route21Swimmer4AfterBattleText"] = "Estou acabado!\nMas ainda preciso\vpedalar e correr\vna maratona!",
  ["_Route21Swimmer4BattleText"] = "Estou no meio de\numa competição\vde triatlo!",
  ["_Route21Swimmer4EndBattleText"] = "Puff...\npuff...puff...",
  ["_Route21Swimmer5AfterBattleText"] = "Estou queimado que\nnem um camarão!",
  ["_Route21Swimmer5BattleText"] = "Ahh! Sinta só esse\nsol e o vento!",
  ["_Route21Swimmer5EndBattleText"] = "Opa!\nEu perdi!",
  ["_Route22GateGuardGoRightAheadText"] = "Oh! Essa é a\nINSÍGNIA ROCHEDO!\vVá em frente!",
  ["_Route22GateGuardICantLetYouPassText"] = "\fRegras são regras.\nNão posso deixar\vvocê passar.",
  ["_Route22GateGuardNoBoulderbadgeText"] = "Apenas treinadores\nrealmente talen-\vtosos que podem\vseguir em frente.\fVocê precisa da\nINSÍGIA ROCHEDO\vpara prosseguir!",
  ["_Route22PokemonLeagueSignText"] = "LIGA POKéMON\nPortão de Entrada",
  ["_Route22Rival1DefeatedText"] = "Ahh!\nVocê só teve\vsorte!",
  ["_Route22Rival1VictoryText"] = "{RIVAL}: O quê?\nPor que eu tenho\vdois POKéMON?\fVocê deveria estar\ncapturando mais\valguns também!",
  ["_Route22Rival2DefeatedText"] = "O quê!?\fEu fui\ndescuidado!",
  ["_Route22Rival2VictoryText"] = "{RIVAL}: Hahaha!\n{PLAYER}! Esse\vfoi seu melhor?\vVocê nem chega\vaos meus pés!\fVá treinar um\npouco! Perdedor!",
  ["_Route22RivalAfterBattleText1"] = "Eu ouvi que na\nLIGA POKéMON tem\vmuitos treinado-\vres bem durões!\fTenho que bolar\num plano pra\vpassar por eles!\fEu devia parar de\nficar enrolando e\vseguir em frente!",
  ["_Route22RivalAfterBattleText2"] = "Isso foi um bom\naquecimento! Já\vestou pronto para\va LIGA POKéMON!\f{PLAYER}, você\nprecisa praticar!\fMas ei, você já\nsabia! Estou me\vmandando! Falou!",
  ["_Route22RivalBeforeBattleText1"] = "{RIVAL}: Ei!\n{PLAYER}!\fEstá indo para\na LIGA POKéMON?\fEsqueça! Você\nprovavelmente não\vtem nenhuma\vINSÍGNIA ainda!\fO guarda não vai\nte deixar passar.\fFalando nisso, seu\nPOKéMON já ficou\vmais forte?",
  ["_Route22RivalBeforeBattleText2"] = "{RIVAL}: O quê?\n{PLAYER}! Mas que\vsurpresa te ver\vpor aqui!\fEntão você está\nindo para a\vLIGA POKéMON?\fVocê coletou todas\nas 8 INSÍGNIAs?\vQue legal!\fEntão acho que vou\nte dar uma surra,\v{PLAYER}, para me\vaquecer para a\vLIGA POKéMON!\fVamos nessa!",
  ["_Route23GoRightAheadText"] = "\fCerto, então! Por\nfavor, prossiga!",
  ["_Route23OhThatIsTheBadgeText"] = "Você só poderá\npassar por aqui\vse possuir a\v{RAM:wNameBuffer}!\fOh! Essa é a\n{RAM:wNameBuffer}!",
  ["_Route23VictoryRoadGateSignText"] = "ROTA DA VITÓRIA\n- LIGA POKéMON",
  ["_Route23YouDontHaveTheBadgeYetText"] = "Você só poderá\npassar por aqui\vse possuir a\v{RAM:wNameBuffer}!\fEi, você não tem a\n{RAM:wNameBuffer}!\fPrecisa dela para\nchegar até a\vLIGA POKéMON!",
  ["_Route24CooltrainerF1AfterBattleText"] = "Dei meu melhor,\nentão não posso\vme arrepender!",
  ["_Route24CooltrainerF1BattleText"] = "Eu sou a Nº4!\nFicando cansado?",
  ["_Route24CooltrainerF1EndBattleText"] = "Eu também\nperdi!",
  ["_Route24CooltrainerF2AfterBattleText"] = "Dei meu melhor, e\nnão me arrependo!",
  ["_Route24CooltrainerF2BattleText"] = "Sou a segunda!\nAgora é sério!",
  ["_Route24CooltrainerF2EndBattleText"] = "Como eu\npude perder?",
  ["_Route24CooltrainerM1DefeatedText"] = "Arrgh!\nVocê é bom!",
  ["_Route24CooltrainerM1JoinTeamRocketText"] = "Aproveitando, que\ntal se juntar a\vEQUIPE ROCKET?\fSomos um grupo que\nse dedica ao mal\vusando POKéMON!\fQuer entrar?\fTem certeza?\fQual é, se\njunte a nós!\fEstou mandando\nvocê participar!\fTá, você precisa\nser convencido!\fEu vou fazer\numa oferta\virrecusável!",
  ["_Route24CooltrainerM1NoRoomText"] = "Você não tem\nespaço pra isso!",
  ["_Route24CooltrainerM1ReceivedNuggetText"] = "{PLAYER} recebeu\numa {RAM:wStringBuffer}!",
  ["_Route24CooltrainerM1YouBeatOurContestText"] = "Parabéns!\nVocê derrotou os\v5 competidores!",
  ["_Route24CooltrainerM1YouCouldBecomeATopLeaderText"] = "Com essa aptidão,\nvocê poderia ser\vum grande líder\vna EQUIPE ROCKET!",
  ["_Route24CooltrainerM1YouJustEarnedAPrizeText"] = "\fE ganhou um prêmio\nfabuloso!",
  ["_Route24CooltrainerM2AfterBattleText"] = "Eu me escondi aqui\nporque as pessoas\vlá da ponte me\vassustaram!",
  ["_Route24CooltrainerM2BattleText"] = "Vi seus feitos\naqui da grama!",
  ["_Route24CooltrainerM2EndBattleText"] = "Eu nem\npisquei!",
  ["_Route24CooltrainerM3AfterBattleText"] = "Dei meu melhor, e\nnão me arrependo!",
  ["_Route24CooltrainerM3BattleText"] = "OK! Eu sou o Nº5!\nE vou te esmagar!",
  ["_Route24CooltrainerM3EndBattleText"] = "Uau!\nFoi demais!",
  ["_Route24Youngster1AfterBattleText"] = "Dei meu melhor, e\nnão me arrependo!",
  ["_Route24Youngster1BattleText"] = "Aqui vai o Nº3!\nNão será fácil!",
  ["_Route24Youngster1EndBattleText"] = "Uou!\nFui esmagado!",
  ["_Route24Youngster2AfterBattleText"] = "Dei meu melhor, e\nnão me arrependo!",
  ["_Route24Youngster2BattleText"] = "Essa é a PONTE DA\nPEPITA! Derrote\vos 5 treinadores\ve ganhe um prêmio\vfabuloso!\fPensa que pode\nnos derrotar?",
  ["_Route24Youngster2EndBattleText"] = "Au!\nEssa foi boa!",
  ["_Route25BillSignText"] = "CHALÉ DO MAR\nBILL mora aqui!",
  ["_Route25CooltrainerF1AfterBattleText"] = "Meu namorado podia\nser bom assim!",
  ["_Route25CooltrainerF1BattleText"] = "Oi! Meu namorado\né tão descolado!",
  ["_Route25CooltrainerF1EndBattleText"] = "Eu fui\ndescuidada!",
  ["_Route25CooltrainerF2AfterBattleText"] = "Você veio da\nMONTANHA DA LUA?\vPosso ficar com\vum CLEFAIRY?",
  ["_Route25CooltrainerF2BattleText"] = "Minha amiga tem um\nPOKéMON fofinho.\vEstou com inveja!",
  ["_Route25CooltrainerF2EndBattleText"] = "Não sou\numa invejosa!",
  ["_Route25CooltrainerMAfterBattleText"] = "Bom. Minha garota\nvai me reanimar.",
  ["_Route25CooltrainerMBattleText"] = "Eu sou um cara bem\ndescolado. Eu até\vtenho um namorada!",
  ["_Route25CooltrainerMEndBattleText"] = "Ah,\ndroga...",
  ["_Route25Hiker1AfterBattleText"] = "Droga!\nUm ZUBAT me\vme mordeu quando\veu estava lá.",
  ["_Route25Hiker1BattleText"] = "Acabei de descer a\nMONTANHA DA LUA,\vmas estou pronto!",
  ["_Route25Hiker1EndBattleText"] = "Você\ntreinou duro!",
  ["_Route25Hiker2AfterBattleText"] = "O colecionador tem\nmuitos tipos \vraros de POKéMON.",
  ["_Route25Hiker2BattleText"] = "Vim para ver o tal\ncolecionador de\vPOKéMON que vive\vno chalé adiante!",
  ["_Route25Hiker2EndBattleText"] = "Você\nme pegou.",
  ["_Route25Hiker3AfterBattleText"] = "A trilha abaixo é\num atalho para a\vCIDADE DE\vCERULEAN.",
  ["_Route25Hiker3BattleText"] = "Está indo visitar\no BILL? Antes,\vvamos batalhar!",
  ["_Route25Hiker3EndBattleText"] = "Você\né bom.",
  ["_Route25Youngster1AfterBattleText"] = "Todos os POKéMON\ntêm fraquezas.\vÉ bom treinar\vtipos diferentes.",
  ["_Route25Youngster1BattleText"] = "Treinadores locais\nvêm aqui para\vpraticar!",
  ["_Route25Youngster1EndBattleText"] = "Você\nfoi decente.",
  ["_Route25Youngster2AfterBattleText"] = "No St.ANA, eu vi\ntreinadores do\vmundo todo.",
  ["_Route25Youngster2BattleText"] = "Papai me levou a\numa grande festa\va bordo do navio\vSt.ANA na CIDADE\vDE VERMILION!",
  ["_Route25Youngster2EndBattleText"] = "Não\nestou bravo!",
  ["_Route25Youngster3AfterBattleText"] = "Se seu POKéMON\nficar confuso ou\vcair no sono,\vtroque-o!",
  ["_Route25Youngster3BattleText"] = "Eu sabia que iria\nbatalhar com você!",
  ["_Route25Youngster3EndBattleText"] = "Eu já\nsabia que iria\vperder também!",
  ["_Route2DiglettsCaveSignText"] = "CAVERNA DOS\nDIGLETTs",
  ["_Route2GateOaksAideFlashExplanationText"] = "A MO - CLARÃO\nilumina até mesmo\va mais escura\vdas cavernas.",
  ["_Route2GateYoungsterText"] = "Quando um POKéMON\naprender CLARÃO,\vvocê poderá atra-\vvessar o TÚNEL\vROCHOSO.",
  ["_Route2SignText"] = "Ei! Eu te vi\nna FLORESTA\vDE VIRIDIAN!",
  ["_Route2TradeHouseScientistText"] = "Um POKéMON que\ndesmaiou não pode\vbatalhar. Mas\vainda pode usar\vuma das técnicas\vespeciais, como\va de CORTAR!",
  ["_Route3CooltrainerF1AfterBattleText"] = "Pare de me encarar\nse você não quer\vbatalhar!",
  ["_Route3CooltrainerF1BattleText"] = "Você estava me\nencarando, não é?",
  ["_Route3CooltrainerF1EndBattleText"] = "Seu\nmalvado!",
  ["_Route3CooltrainerF2AfterBattleText"] = "Se quiser evitar\nas batalhas,\vnão deixe que as\vpessoas te vejam!",
  ["_Route3CooltrainerF2BattleText"] = "Esse olhar que\nvocê me deu, é\vtão intrigante!",
  ["_Route3CooltrainerF2EndBattleText"] = "Seja mais\ngentil!",
  ["_Route3CooltrainerF3AfterBattleText"] = "A ROTA 4 fica do\noutro lado da\vMONTANHA DA LUA.",
  ["_Route3CooltrainerF3BattleText"] = "Eca! Você encostou\nem mim?",
  ["_Route3CooltrainerF3EndBattleText"] = "Só isso?",
  ["_Route3SignText"] = "ROTA 3\nMONTANHA DA LUA\vEM FRENTE",
  ["_Route3Text1"] = "Ai ai! Eu tropecei\nnum POKéMON ro-\vchoso, o GEODUDE!",
  ["_Route3Youngster1AfterBattleText"] = "Aqui tem outros\ntipos de POKéMON\valém daqueles\vda floresta!",
  ["_Route3Youngster1BattleText"] = "Eu vim pegar um\nPOKéMON cogumelo!",
  ["_Route3Youngster1EndBattleText"] = "Ah! Meu\nquerido POKéMON\vcogumelo!",
  ["_Route3Youngster2AfterBattleText"] = "Você está guardan-\ndo seus POKéMON\vno PC? Cada POKé-\vCAIXA pode conter\vaté 20 POKéMON!",
  ["_Route3Youngster2BattleText"] = "Oi! Eu gosto de\ncalções! Eles são\vconfortáveis e\vfáceis de vestir!",
  ["_Route3Youngster2EndBattleText"] = "Eu não\nacredito nisso!",
  ["_Route3Youngster3AfterBattleText"] = "Se a POKéCAIXA\ndo PC ficar lota-\vda, é só trocar\vpor outra CAIXA!",
  ["_Route3Youngster3BattleText"] = "É um treinador?\nEntão, batalhe!",
  ["_Route3Youngster3EndBattleText"] = "Se\neu tivesse novos\vPOKéMON, eu teria\vvencido!",
  ["_Route3Youngster4AfterBattleText"] = "Eu sempre uso\ncalções, até\vmesmo no inverno!",
  ["_Route3Youngster4BattleText"] = "Ei! Você não está\nusando calções!",
  ["_Route3Youngster4EndBattleText"] = "Perdi!\nPerdi! Perdi!",
  ["_Route3Youngster5AfterBattleText"] = "POKéMON treinados\nsão mais fortes\vque os selvagens!",
  ["_Route3Youngster5BattleText"] = "Agora você vai\nenfrentar o meu\vnovo POKéMON!",
  ["_Route3Youngster5EndBattleText"] = "\nPerdi até a fome!",
  ["_Route4CooltrainerF1Text"] = "Ai ai! Eu tropecei\nnum POKéMON ro-\vchoso, o GEODUDE!",
  ["_Route4CooltrainerF2AfterBattleText"] = "Talvez não tenha\nmais nenhum\vcogumelo aqui.\fAcho que peguei\ntodos eles.",
  ["_Route4CooltrainerF2BattleText"] = "Eu vim pegar um\nPOKéMON cogumelo!",
  ["_Route4CooltrainerF2EndBattleText"] = "Ah! Meu\nquerido POKéMON\vcogumelo!",
  ["_Route4MtMoonSignText"] = "MONTANHA DA LUA\nTúnel de Entrada",
  ["_Route4SignText"] = "ROTA 4\nMONTANHA DA LUA -\vCIDADE DE CERULEAN",
  ["_Route5UndergroundPathSignText"] = "TÚNEL SUBTERRÂNEO\nCERULEAN -\vVERMILION",
  ["_Route6CooltrainerAfterBattleText"] = "Cochichos...\nCochichos...",
  ["_Route6CooltrainerF1BattleText"] = "Com licença! Essa\né uma conversa\vparticular!",
  ["_Route6CooltrainerF1EndBattleText"] = "Ahh!\nOdeio perder!",
  ["_Route6CooltrainerF2AfterBattleText"] = "Quero ficar mais\nforte! Qual o\vseu segredo?",
  ["_Route6CooltrainerF2BattleText"] = "Eu? Bom, OK.\nVamos brincar!",
  ["_Route6CooltrainerF2EndBattleText"] = "Não\ndeu certo!",
  ["_Route6CooltrainerM1BattleText"] = "Quem está aí?\nPare de nos\vbisbilhotar!",
  ["_Route6CooltrainerM1EndBattleText"] = "Eu\nnunca ganho!",
  ["_Route6CooltrainerM2AfterBattleText"] = "Eu deveria carre-\ngar mais POKéMON\vcomigo por segu-\vrança.",
  ["_Route6CooltrainerM2BattleText"] = "Hã? Você quer\nconversar comigo?",
  ["_Route6CooltrainerM2EndBattleText"] = "Eu\nnão comecei isso!",
  ["_Route6UndergroundPathSignText"] = "TÚNEL SUBTERRÂNEO\nCERULEAN -\vVERMILION",
  ["_Route6Youngster1AfterBattleText"] = "Gosto de insetos,\nentão vou voltar\vpara a FLORESTA\vDE VIRIDIAN.",
  ["_Route6Youngster1BattleText"] = "Não tem muitos\ninsetos por aqui.",
  ["_Route6Youngster1EndBattleText"] = "Não!\nTá de brincadeira\vcomigo?!",
  ["_Route6Youngster2AfterBattleText"] = "Meus POKéMON são\nfracos? Ou será\vque eu sou ruim?",
  ["_Route6Youngster2BattleText"] = "Nunca te vi\npor aqui!\vVocê é bom?",
  ["_Route6Youngster2EndBattleText"] = "Você\né bom demais!",
  ["_Route7UndergroundPathSignText"] = "TÚNEL SUBTERRÂNEO\nCIDADE DE CELADON\v- CIDADE DE\vLAVENDER",
  ["_Route8CooltrainerF1AfterBattleText"] = "Quando os POKéMON\ncrescem, ficam\vfeiosos demais!\vAcho que não\vdeveriam evoluir!",
  ["_Route8CooltrainerF1BattleText"] = "Por quê?\nPor quê??",
  ["_Route8CooltrainerF1EndBattleText"] = "Eu\nnão comecei isso!",
  ["_Route8CooltrainerF2AfterBattleText"] = "Eu acho que PIDGEY\ne RATTATA são\vfofinhos também!",
  ["_Route8CooltrainerF2BattleText"] = "MEOWTH é tão fofo,\nmiau, miau, miau!",
  ["_Route8CooltrainerF2EndBattleText"] = "Miau!",
  ["_Route8CooltrainerF3AfterBattleText"] = "O vigia dos por-\ntões da CIDADE DE\vSAFFRON não nos\vdeixou passar.\vEle é tão malvado!",
  ["_Route8CooltrainerF3BattleText"] = "Estamos passando\nvergonha parados\vaqui feito bobos!",
  ["_Route8CooltrainerF3EndBattleText"] = "Olha o que\nvocê fez!",
  ["_Route8CooltrainerF4AfterBattleText"] = "Pare!\nNão seja malvado\vcom meu CLEFAIRY!",
  ["_Route8CooltrainerF4BattleText"] = "Quem é um POKéMON\nrechonchudo e\vmuito fofinho?",
  ["_Route8CooltrainerF4EndBattleText"] = "Pare!\fNão seja tão mau\ncom meu CLEFAIRY!",
  ["_Route8Gambler1AfterBattleText"] = "Dona Sorte não\nestá comigo hoje!",
  ["_Route8Gambler1BattleText"] = "Tudo certo! Vamos\nrolar os dados!",
  ["_Route8Gambler1EndBattleText"] = "Droga!\nTirei pouco!",
  ["_Route8Gambler2AfterBattleText"] = "Apostas e POKéMON\nsão como comer\vamendoins! Não\vconsigo parar!",
  ["_Route8Gambler2BattleText"] = "Sou um jogador e\napostador, cara!",
  ["_Route8Gambler2EndBattleText"] = "Perdi\na grande jogada!",
  ["_Route8SuperNerd1AfterBattleText"] = "Cochichos...\nCochichos...",
  ["_Route8SuperNerd1BattleText"] = "Você parece ser\nbom com POKéMON,\vque tal testamos\vessa química?",
  ["_Route8SuperNerd1EndBattleText"] = "Au!\nExplodiu tudo!",
  ["_Route8SuperNerd2AfterBattleText"] = "Vá com GRIMER\nprimeiro...e...\v...e...então...",
  ["_Route8SuperNerd2BattleText"] = "Precisa de estra-\ntégia para vencer!",
  ["_Route8SuperNerd2EndBattleText"] = "Não\ntem lógica nisso!",
  ["_Route8SuperNerd3AfterBattleText"] = "Estamos presos\naqui por causa\vdos portões da\vCIDADA DE SAFFRON.",
  ["_Route8SuperNerd3BattleText"] = "Escola é legal,\ne POKéMON também.",
  ["_Route8SuperNerd3EndBattleText"] = "Eu vou\nficar na escola.",
  ["_Route8UndergroundSignText"] = "Ouvi dizer que o\nCLEFAIRY evolui\vquando exposto a\vuma PEDRA DA LUA.",
  ["_Route9CooltrainerF1AfterBattleText"] = "Precisa de luz se\nquiser atravessar\vaquele túnel\vescuro a seguir.",
  ["_Route9CooltrainerF1BattleText"] = "Você tem POKéMON\ncom você!\vVocê é meu!",
  ["_Route9CooltrainerF1EndBattleText"] = "Você\nme enganou!",
  ["_Route9CooltrainerF2AfterBattleText"] = "Você é obviamente\nmuito talentoso!\vBoa sorte pra\vvocê!",
  ["_Route9CooltrainerF2BattleText"] = "Não se atreva a\npegar leve!",
  ["_Route9CooltrainerF2EndBattleText"] = "Não!\nVocê é demais!",
  ["_Route9CooltrainerM1AfterBattleText"] = "Continue andando!",
  ["_Route9CooltrainerM1BattleText"] = "Quem vem aí com\nesses POKéMON\vbonitões?",
  ["_Route9CooltrainerM1EndBattleText"] = "Apagado\nfeito um fósforo!",
  ["_Route9CooltrainerM2AfterBattleText"] = "Você também vai\nao TÚNEL ROCHOSO?",
  ["_Route9CooltrainerM2BattleText"] = "Estou indo para\no TÚNEL ROCHOSO\vpara chegar em\vLAVENDER...",
  ["_Route9CooltrainerM2EndBattleText"] = "Não\nvejo a hora!",
  ["_Route9Hiker1AfterBattleText"] = "Você teve muita\ncoragem ao me\venfrentar, não é?",
  ["_Route9Hiker1BattleText"] = "Uahaha! Ótimo!\nEu estava ficando\ventediado, hehe!",
  ["_Route9Hiker1EndBattleText"] = "Manda\nmais, hehe!\fAh, espere. Estou\nsem POKéMON!",
  ["_Route9Hiker2AfterBattleText"] = "Hahaha! Você é\nmesmo valente!",
  ["_Route9Hiker2BattleText"] = "Hahaha!\nEstá se achando\vum valentão?!",
  ["_Route9Hiker2EndBattleText"] = "O que\nfoi isso?",
  ["_Route9Hiker3AfterBattleText"] = "Hahahaha!\nSorrir é o melhor\vremédio!",
  ["_Route9Hiker3BattleText"] = "Hahahaha!\nBora lá, carinha!",
  ["_Route9Hiker3EndBattleText"] = "Haha!\nMe venceu mesmo!",
  ["_Route9SignText"] = "ROTA 9\nCIDADE DE CERULEAN\vTÚNEL ROCHOSO",
  ["_Route9Youngster1AfterBattleText"] = "Acho que vou ter\nque colecionar\vmais que apenas\vinsetos se quiser\vficar forte...",
  ["_Route9Youngster1BattleText"] = "Acordei bem cedo\ntodo dia só para\vver meus POKéMON\vsaindo dos seus\vcasulos!",
  ["_Route9Youngster1EndBattleText"] = "QUÊ?\nMas que grande\vperda de tempo!",
  ["_Route9Youngster2AfterBattleText"] = "Se você não gosta\nde POKéMON inseto,\vvocê me enoja!",
  ["_Route9Youngster2BattleText"] = "Vai, meu super\nPOKéMON inseto!",
  ["_Route9Youngster2EndBattleText"] = "\nMeus insetos...",
  ["_SSAnne1FRoomsCooltrainerFAfterBattleText"] = "Você feriu os meus\nqueridos POKéMON\vestrangeiros!\fEu exijo que você\ncure eles em um\vCENTRO POKéMON!",
  ["_SSAnne1FRoomsCooltrainerFBattleText"] = "Eu coleciono POKé-\nMON de todas as\vpartes do mundo!",
  ["_SSAnne1FRoomsCooltrainerFEndBattleText"] = "Ah, não!\nRodei o mundo\vtodo por esses!",
  ["_SSAnne1FRoomsGentleman1AfterBattleText"] = "Você deveria ser\nmais gentil com\vos amigos!",
  ["_SSAnne1FRoomsGentleman1BattleText"] = "Eu sempre viajo\nsozinho em minhas\vjornadas!\fMeus POKéMON são\nmeus únicos\vamigos!",
  ["_SSAnne1FRoomsGentleman1EndBattleText"] = "Meus,\nmeus amigos...",
  ["_SSAnne1FRoomsGentleman2AfterBattleText"] = "Quero ficar\nsozinho! Saia!",
  ["_SSAnne1FRoomsGentleman2BattleText"] = "Seu pentelho!\nComo é atrevido!",
  ["_SSAnne1FRoomsGentleman2EndBattleText"] = "Humph!\nCriança rude!",
  ["_SSAnne1FRoomsGentleman3Text"] = "Chiu! Eu sou um\nagente secreto da\vPOLÍCIA GLOBAL!\fEstou atrás da\nEQUIPE ROCKET!",
  ["_SSAnne1FRoomsGirl1Text"] = "Garçom, eu vou\nquerer uma torta\vde cereja,\vpor favor!",
  ["_SSAnne1FRoomsGirl2Text"] = "Estamos viajando\nao redor do mundo\vinteiro.",
  ["_SSAnne1FRoomsLittleGirlText"] = "Eu sempre viajo \ncom o WIGGLYTUFF!",
  ["_SSAnne1FRoomsMiddleAgedManText"] = "Eu sempre viajo \ncom o WIGGLYTUFF!",
  ["_SSAnne1FRoomsWigglytuffText"] = "WIGGLYTUFF: Wiggly\nwiggly!",
  ["_SSAnne1FRoomsYoungsterAfterBattleText"] = "Me deixe ser seu\namigo, OK?\fDaí podemos trocar\nPOKéMON!",
  ["_SSAnne1FRoomsYoungsterBattleText"] = "Eu amo POKéMON!\nE você?",
  ["_SSAnne1FRoomsYoungsterEndBattleText"] = "Uau! \nVocê é bom!",
  ["_SSAnne1FSailorText"] = "Os passageiros são\nincansáveis!\fVocê provavelmente\nserá desafiado\vpelos entediados!",
  ["_SSAnne1FWaiterText"] = "Bonjour!\nSou le garçom\vdeste navio!\fFicarei feliz em\nte servir em tudo\vque precisar!\fAh! Le tipo\nsilencioso!",
  ["_SSAnne2FRivalCutMasterText"] = "{RIVAL}: Ouvi\ndizer que havia\vum mestre na téc-\vnica de CORTAR\va bordo.\fMas ele é só um\nvelhote enjoado!\fMas CORTAR é algo\nrealmente útil!\fVocê deveria ir\nver esse velhote!\fFalou aí, tô indo\nnessa!",
  ["_SSAnne2FRivalDefeatedText"] = "Humph!\fPelo menos está\ntreinando bem os\vseus POKéMON!",
  ["_SSAnne2FRivalText"] = "{RIVAL}: Bonjour!\n{PLAYER}!\fImagina só te ver\npor aqui!\f{PLAYER}, você foi\nmesmo convidado?\fE sua POKéDEX,\ncomo vai?\fEu já capturei\n40 tipos, cara!\fTipos diferentes\nestão por toda\va parte!\fVasculhe pelas\náreas gramadas!",
  ["_SSAnne2FRivalVictoryText"] = "{PLAYER}! Você\nficou enjoado?\fVocê precisa se\nrecompor, cara!",
  ["_SSAnne2FRoomsBeautyText"] = "Ouvi dizer que\nmuitas pessoas\venjoam no mar!",
  ["_SSAnne2FRoomsBrunetteGirlText"] = "O CAPITÃO parecia\nmeio doente e\vpálido!",
  ["_SSAnne2FRoomsCooltrainerFAfterBattleText"] = "Oh, adorei seu\nPOKéMON fortinho!",
  ["_SSAnne2FRoomsCooltrainerFBattleText"] = "Eu não te vi\nna festa.",
  ["_SSAnne2FRoomsCooltrainerFEndBattleText"] = "Pega leve!\n ",
  ["_SSAnne2FRoomsFisherAfterBattleText"] = "Festa?\fAs festividades do\ncruzeiro já foram\vencerradas.",
  ["_SSAnne2FRoomsFisherBattleText"] = "Olha só o que\neu fisguei!",
  ["_SSAnne2FRoomsFisherEndBattleText"] = "Estou\nsem nada!",
  ["_SSAnne2FRoomsGentleman1AfterBattleText"] = "15 anos atrás, eu\nteria vencido!",
  ["_SSAnne2FRoomsGentleman1BattleText"] = "Competir contra os\njovens mantém a\vminha juventude.",
  ["_SSAnne2FRoomsGentleman1EndBattleText"] = "Boa\nluta! Ah, eu já\vestou me sentindo\vjovem novamente!",
  ["_SSAnne2FRoomsGentleman2AfterBattleText"] = "Eu prefiro um\nraro e forte.",
  ["_SSAnne2FRoomsGentleman2BattleText"] = "Qual você prefere,\num POKéMON raro\vou um forte?",
  ["_SSAnne2FRoomsGentleman2EndBattleText"] = "Meus\ncumprimentos!",
  ["_SSAnne2FRoomsGentleman3Text"] = "Em todas as minhas\nviagens eu nunca\vvi um POKéMON\vdormir tanto\vquanto esse aqui!\fEle era mais ou\nmenos assim!",
  ["_SSAnne2FRoomsGentleman4Text"] = "Ah, sim, eu já vi\nalguns POKéMON\vtransportando as\vpessoas através\vda água!",
  ["_SSAnne2FRoomsGentleman5Text"] = "Você já foi na\nZONA DO SAFARI\vda CIDADE DE\vFUCHSIA?\fTem vários tipos\nraros de POKéMON!",
  ["_SSAnne2FRoomsGrampsText"] = "Um POKéMON pode\nCORTAR pequenos\varbustos.",
  ["_SSAnne2FRoomsLittleBoyText"] = "Papai e eu achamos\na ZONA DO SAFARI\vespetacular!",
  ["_SSAnne2FWaiterText"] = "Esse navio é um\ncruzeiro luxuoso\vpara treinadores!\fEm cada porto, nós\ndamos festas aos\vtreinadores que\vforam convidados!",
  ["_SSAnne3FSailorText"] = "Nosso CAPITÃO é um\ngrande mestre\vespadachim!\fEle até ensina a\ntécnica de CORTAR\vaos POKéMON!",
  ["_SSAnneB1FRoomsFisherAfterBattleText"] = "Eu queria te usar\ncomo meu assis-\vtente de pesca!",
  ["_SSAnneB1FRoomsFisherBattleText"] = "Olá, estranho!\nVenha conversar!\fTodos os meus\nPOKéMON vieram\vdo mar!",
  ["_SSAnneB1FRoomsFisherEndBattleText"] = "Droga!\nDeixei essa\vescapar!",
  ["_SSAnneB1FRoomsMachokeText"] = "MACHOKE: Gwoh!\nGoggoh!",
  ["_SSAnneB1FRoomsSailor1AfterBattleText"] = "Haha! Quer ser um\nmarinheiro, cara?",
  ["_SSAnneB1FRoomsSailor1BattleText"] = "Sabe o que dizem\nsobre marinheiros\ve brigas!",
  ["_SSAnneB1FRoomsSailor1EndBattleText"] = "Certo!\nBoa briga, cara!",
  ["_SSAnneB1FRoomsSailor2AfterBattleText"] = "Meu orgulho de\nmarinheiro está\vem jogo!",
  ["_SSAnneB1FRoomsSailor2BattleText"] = "Meu orgulho de\nmarinheiro está\vem jogo!",
  ["_SSAnneB1FRoomsSailor2EndBattleText"] = "Seu\nespírito de luta\vme afundou!",
  ["_SSAnneB1FRoomsSailor3AfterBattleText"] = "Nós marinheiros\ntemos POKéMON\vtambém!",
  ["_SSAnneB1FRoomsSailor3BattleText"] = "Seu\nespírito de luta\vme afundou!",
  ["_SSAnneB1FRoomsSailor3EndBattleText"] = "OK, \nvocê não é ruim.",
  ["_SSAnneB1FRoomsSailor4AfterBattleText"] = "Nós capturamos os\nnossos POKéMON\vem alto mar!",
  ["_SSAnneB1FRoomsSailor4BattleText"] = "Gosto de meninos\nemburrados assim\vcomo você!",
  ["_SSAnneB1FRoomsSailor4EndBattleText"] = "OK, \nvocê não é ruim.",
  ["_SSAnneB1FRoomsSailor5AfterBattleText"] = "Mano, você vai\nandar na prancha\vse perder essa!",
  ["_SSAnneB1FRoomsSailor5BattleText"] = "Gosto de meninos\nemburrados assim\vcomo você!",
  ["_SSAnneB1FRoomsSailor5EndBattleText"] = "Argh!\nEu perdi!",
  ["_SSAnneB1FRoomsSuperNerdText"] = "Meu parceiro,\nMACHOKE, é super\vforte!\fEle tem uma super\nFORÇA capaz de\vempurrar até\vpedras gigantes!",
  ["_SSAnneBowCooltrainerMText"] = "Urgh. Eu estou me\nsentindo enjoado.\fPor isso vim aqui\nfora pegar um ar.",
  ["_SSAnneBowSailor1Text"] = "Esfregar o convés\né trabalho duro!",
  ["_SSAnneBowSailor2AfterBattleText"] = "Quantas espécies\nde POKéMON você\vacha que existem?",
  ["_SSAnneBowSailor2BattleText"] = "E aí, maninho!\fVamos fazer\num teste!",
  ["_SSAnneBowSailor2EndBattleText"] = "Você é\nimpressionante!",
  ["_SSAnneBowSailor3AfterBattleText"] = "Meu amigo me disse\nque existem 100\vtipos de POKéMON.\vMas eu acho que\vexistem bem mais.",
  ["_SSAnneBowSailor3BattleText"] = "Espere aí!\nFicou enjoado?",
  ["_SSAnneBowSailor3EndBattleText"] = "Eu\nfui descuidado!",
  ["_SSAnneBowSuperNerdText"] = "A festa acabou.\nO barco partirá\vem breve.",
  ["_SSAnneCaptainsRoomCaptainHM01NoRoomText"] = "Ah, não! Você não\ntem espaço pra\vcarregar isso!",
  ["_SSAnneCaptainsRoomCaptainIFeelMuchBetterText"] = "CAPITÃO: Ufa!\nObrigado! Já me\vsinto bem melhor!\fVocê quer ver\nminha técnica\vde CORTAR?\fEu poderia te\nmostrar se não\vestivesse mal...\fJá sei! Você pode\nficar com isso!\fEnsine isso para\num POKéMON e o\vveja CORTAR a\vqualquer hora!",
  ["_SSAnneCaptainsRoomCaptainNotSickAnymoreText"] = "CAPITÃO: Ufa!\fAgora que já não\nestou mais tão\venjoado, acho que\vé hora de partir.",
  ["_SSAnneCaptainsRoomCaptainReceivedHM01Text"] = "{PLAYER} recebeu\n{RAM:wStringBuffer}!",
  ["_SSAnneCaptainsRoomRubCaptainsBackText"] = "CAPITÃO: Ooargh...\nNão me sinto bem.\vUrrp! Enjoado...\f{PLAYER} esfregou\nas costas do\vCAPITÃO!\fEsfrega-esfrega...\nEsfrega-esfrega...",
  ["_SSAnneCaptainsRoomSeasickBookText"] = "Como Não Ficar\nEnjoado no Mar...\vO CAPITÃO estava\vlendo isso!",
  ["_SSAnneCaptainsRoomTrashText"] = "Eca! Não deveria\nter olhado isso!",
  ["_SSAnneKitchenCook1Text"] = "Você, mon petit!\nEstamos ocupados!\vSaia do caminho!",
  ["_SSAnneKitchenCook2Text"] = "Eu vi uma bola bem\nestranha no lixo.",
  ["_SSAnneKitchenCook3Text"] = "Estou tão ocupado\nque fiquei tonto!",
  ["_SSAnneKitchenCook4Text"] = "Hum-de-hum-de-\nho...\fEu descasco\nbatatas todo dia!\vHum-hum...",
  ["_SSAnneKitchenCook5Text"] = "Já ouviu falar no\nSNORLAX?\fTudo que ele faz é\ncomer e dormir!",
  ["_SSAnneKitchenCook6Text"] = "Snif...Sniff...\fEu só descasco\ncebolas...\vSnif...",
  ["_SSAnneKitchenCook7MainCourseIsText"] = "Er-hem! Oui eu\nsou le CHEF!\fLe prato principal\nde hoje é...",
  ["_SSTicketNoRoomText"] = "Você já está cheio\nde coisas, amigão!",
  ["_SSTicketReceivedText"] = "{PLAYER} recebeu o\n{RAM:wStringBuffer}!",
  ["_SafariZoneAngryText"] = "Trocar {NUM:wDayCareTotalCost, 2 | LEADING_ZEROES | LEFT_ALIGN}\npor {RAM:wNameBuffer} ?",
  ["_SafariZoneCenterRestHouseGirlText"] = "SARA: Pra onde\nmeu namorado,\vERIK, foi?",
  ["_SafariZoneCenterRestHouseScientistText"] = "Vim pegar POKéMON\npara dar de pre-\vsente em casa!",
  ["_SafariZoneCenterRestHouseSignText"] = "CASA DE\nDESCANSO",
  ["_SafariZoneCenterTrainerTipsSignText"] = "DICAS PARA\nTREINADORES\fAperte o Botão\nSTART para ver o\vtempo restante!",
  ["_SafariZoneEastRestHouseRockerText"] = "Eu capturei uma\nCHANSEY!\fSó isso já faz\ntudo valer a pena!",
  ["_SafariZoneEastRestHouseScientistText"] = "Quantos você já\npegou? Eu estou\vficando cansado\vde tanto trabalho.",
  ["_SafariZoneEastRestHouseSignText"] = "ÁREA 2",
  ["_SafariZoneEastRestHouseSilphWorkerMText"] = "Ufa! Fiquei até\ncansado de tanta\vdiversão!",
  ["_SafariZoneEastSignText"] = "CASA DE\nDESCANSO",
  ["_SafariZoneEastTrainerTipsText"] = "DICAS PARA\nTREINADORES\fO tempo restante\ndiminui conforme\vvocê anda!",
  ["_SafariZoneEatingText"] = "{RAM:wEnemyMonNick}\nestá comendo!",
  ["_SafariZoneGateSafariZoneWorker1CallYouOnThePAText"] = "\fNós te chamaremos\npelo rádio quando\vacabar seu tempo\vou BOLAS SAFARI!",
  ["_SafariZoneGateSafariZoneWorker1GoodHaulComeAgainText"] = "Você teve um bom\npasseio?\vVolte sempre!",
  ["_SafariZoneGateSafariZoneWorker1GoodLuckText"] = "Boa sorte!",
  ["_SafariZoneGateSafariZoneWorker1LeavingEarlyText"] = "Saindo mais cedo?",
  ["_SafariZoneGateSafariZoneWorker1NotEnoughMoneyText"] = "Oops! Sem dinheiro\nsuficiente!",
  ["_SafariZoneGateSafariZoneWorker1PleaseComeAgainText"] = "OK! Volte sempre\npor favor!",
  ["_SafariZoneGateSafariZoneWorker1ReturnSafariBallsText"] = "Por favor devolva\nqualquer BOLA\vSAFARI que sobrou.",
  ["_SafariZoneGateSafariZoneWorker1Text"] = "Seja bem-vindo à\nZONA DO SAFARI!",
  ["_SafariZoneGateSafariZoneWorker1ThatllBe500PleaseText"] = "Vai custar ¥500\npor favor!\fSó podemos usar um\ntipo especial de\vPOKé BOLA aqui.\f{PLAYER} recebeu\n30 BOLAS SAFARI!",
  ["_SafariZoneGateSafariZoneWorker1WouldYouLikeToJoinText"] = "Por apenas ¥500,\nvocê pode pegar\vtodo POKéMON que\vquiser no parque!\fGostaria de entrar\nna caçada?",
  ["_SafariZoneGateSafariZoneWorker2FirstTimeHereText"] = "Olá! É a primeira\nvez que vem aqui?",
  ["_SafariZoneGateSafariZoneWorker2SafariZoneExplanationText"] = "A ZONA DO SAFARI\ntem 4 áreas.\fCada área tem\ndiferentes tipos\vde POKéMON. Use\vBOLAS SAFARI para\vcapturá-los!\fQuando você ficar\nsem tempo ou sem\vBOLAS SAFARI, é o\vfim do passeio!\fAntes de entrar,\nabra uma nova\vPOKéCAIXA no PC\vpara que tenha\vespaço para pegar\vnovos POKéMON!",
  ["_SafariZoneGateSafariZoneWorker2YoureARegularHereText"] = "Desculpe, você já\né cliente antigo!",
  ["_SafariZoneNorthRestHouseGentlemanText"] = "Meu EEVEE evoluiu\npara FLAREON!\fMas o EEVEE do\nmeu amigo virou\vum VAPOREON!\vPor que será?",
  ["_SafariZoneNorthRestHouseSafariZoneWorkerText"] = "Vá para a área\nmais afastada da\vZONA DO SAFARI.\vVocê ganhará um\vbelo prêmio!",
  ["_SafariZoneNorthRestHouseScientistText"] = "Você pode ficar\ncom qualquer item\vque encontrar no\vno chão daqui.\fMas seu tempo vai\nacabar rápido se\vtentar pegar eles\vtodos de uma vez!",
  ["_SafariZoneNorthRestHouseSignText"] = "CASA DE\nDESCANSO",
  ["_SafariZoneNorthSignText"] = "ÁREA 2",
  ["_SafariZoneNorthTrainerTips1Text"] = "DICAS PARA\nTREINADORES\fA CASA SECRETA\nestá em frente!",
  ["_SafariZoneNorthTrainerTips2Text"] = "DICAS PARA\nTREINADORES\fOs POKéMON se\nescondem na grama!\fAnde pelas áreas\ngramadas para \vespantá-los.",
  ["_SafariZoneNorthTrainerTips3Text"] = "DICAS PARA\nTREINADORES\fGanhe uma MO\nencontrando a\vCASA SECRETA!",
  ["_SafariZoneSecretHouseFishingGuruHM03ExplanationText"] = "MO03 contém\nSURFAR!\fOs POKéMON serão\ncapazes de te \vtransportar atra-\vvés da água!\fE essa MO não\né descartável!\vVocê pode usar\vvárias vezes!\fVocê é realmente\nsortudo por ter\vganho um prêmio\vtão fabuloso!",
  ["_SafariZoneSecretHouseFishingGuruHM03NoRoomText"] = "Você não tem\nespaço para esse\vfabuloso prêmio!",
  ["_SafariZoneSecretHouseFishingGuruReceivedHM03Text"] = "{PLAYER} recebeu\na {RAM:wStringBuffer}!",
  ["_SafariZoneSecretHouseFishingGuruYouHaveWonText"] = "AVISO DE\nPROCURA-SE\fPor favor, ajude\na encontrar a\vDENTADURA perdida\vdo DIRETOR da \vZONA DO SAFARI.\vEla está por aqui\vem algum lugar.\fOfereço Premiação!\nContato: DIRETOR",
  ["_SafariZoneWestFindWardensTeethSignText"] = "AVISO DE\nPROCURA-SE\fPor favor, ajude\na encontrar a\vDENTADURA perdida\vdo DIRETOR da \vZONA DO SAFARI.\vEla está por aqui\vem algum lugar.\fOfereço Premiação!\nContato: DIRETOR",
  ["_SafariZoneWestRestHouseCooltrainerMText"] = "Use as ISCAs para\ndeixar os POKéMON\vmais fáceis de\vcapturar.",
  ["_SafariZoneWestRestHouseScientistText"] = "Atirando PEDRAs\nnum POKéMON pode\vfazer ele fugir,\vmas será mais\vfácil de capturar.",
  ["_SafariZoneWestRestHouseSignText"] = "CASA DE\nDESCANSO",
  ["_SafariZoneWestRestHouseSilphWorkerFText"] = "Eu andei bastante,\nmas não vi nenhum\vPOKéMON que eu\vqueria pegar.",
  ["_SafariZoneWestSignText"] = "CASA DE\nDESCANSO",
  ["_SafariZoneWestTrainerTipsText"] = "DICAS PARA\nTREINADORES\fCampanha de Explo-\nração do SAFARI!\fProcure pela\nCASA SECRETA!",
  ["_SaffronCityFightingDojoSignText"] = "DOJO DE ARTES\nMARCIAIS",
  ["_SaffronCityGentlemanText"] = "Eu vim voando com\nmeu PIDGEOT quan-\vdo eu li a res-\vpeito da SILPH.\fJá acabou?\nEu perdi toda\va ação.",
  ["_SaffronCityGymSignText"] = "GINÁSIO POKéMON\nDE SAFFRON\vLÍDER: SABRINA\fA Mestra dos\nPOKéMON Psíquicos!",
  ["_SaffronCityMrPsychicsHouseSignText"] = "CASA DO\nSR. PSÍQUICO",
  ["_SaffronCityPidgeotText"] = "PIDGEOT: Pi pipii!",
  ["_SaffronCityPokecenterGuyText1"] = "Seria ótimo se a\nELITE DOS QUATRO\vviesse esmagar a\vEQUIPE ROCKET!",
  ["_SaffronCityPokecenterGuyText2"] = "EQUIPE ROCKET se\nmandou! Nós já\vestamos seguros!\vIsso é demais!",
  ["_SaffronCityRockerText"] = "Eu vi o LÍDER dos\nROCKET fugindo do\vprédio da SILPH.",
  ["_SaffronCityRocket1Text"] = "O que você quer?\nSuma daqui!",
  ["_SaffronCityRocket2Text"] = "O CHEFE disse que\nvai dominar essa\vcidade inteira!",
  ["_SaffronCityRocket3Text"] = "Saia já do meu\ncaminho!",
  ["_SaffronCityRocket4Text"] = "SAFFRON pertence\na EQUIPE ROCKET!",
  ["_SaffronCityRocket5Text"] = "Ser mal faz eu me\nsentir tão vivo!",
  ["_SaffronCityRocket6Text"] = "Au! Olha por onde\nanda!",
  ["_SaffronCityRocket7Text"] = "Com a SILPH sob\nnosso controle,\vnós poderemos\vexplorar POKéMON\vpor todo o mundo!",
  ["_SaffronCityRocket8Text"] = "Eu sou um guarda\nde segurança.\fCrianças suspeitas\nnão podem entrar!",
  ["_SaffronCityRocket9Text"] = "...\nRonc...\fAha! Ele está ti-\nrando uma soneca!",
  ["_SaffronCityScientistText"] = "Você derrotou a\nEQUIPE ROCKET\vtoda sozinho?\vIsso é incrível!",
  ["_SaffronCitySignText"] = "CIDADE DE SAFFRON\nUma Brilhante\ve Dourada Terra\vde Comércio.",
  ["_SaffronCitySilphCoLatestProductSignText"] = "O último produto\nda SILPH CO.!\fAinda sem data\nde lançamento...",
  ["_SaffronCitySilphCoSignText"] = "PRÉDIO COMERCIAL\nda SILPH CO.",
  ["_SaffronCitySilphWorkerFText"] = "Agora as pessoas\nvão voltar a vir\vpara SAFFRON.",
  ["_SaffronCitySilphWorkerMText"] = "Isso! A EQUIPE\nROCKET já era!\vJá é seguro andar\vaqui fora!",
  ["_SaffronCityTrainerTips1Text"] = "DICAS PARA\nTREINADORES\fCURA TOTAL pode\ncurar todos os\vmales POKéMON,\vcomo queimaduras,\vsono e veneno.\fCusta um pouco\nmais, porém é bem\vmais conveniente.",
  ["_SaffronCityTrainerTips2Text"] = "DICAS PARA\nTREINADORES\fA GRANDE BOLA\noferece índices\vde captura bem\vmais aprimorados.\fExperimente elas\nem POKéMON que\vsão mais difíceis\vde se capturar.",
  ["_SaffronGateGuardGeeImThirstyText"] = "Eu estou de guarda\naqui o dia todo.\fMas nossa, como\nestou com sede!\fAh, espere aí, \nessa passagem\vestá bloqueada.",
  ["_SaffronGateGuardImParchedText"] = "Argh, cara!\nEstou sedento!\v...\vHã? Posso ficar\vcom essa bebida?\vNossa, obrigado!",
  ["_SaffronGateGuardThanksForTheDrinkText"] = "Oi, obrigado pela\nbebida geladinha!",
  ["_SaffronGateGuardYouCanGoOnThroughText"] = "\f...\nGlub glub...\v...\vGulp...\vSe quiser pode ir\vem frente para\vSAFFRON...\v...\vVocê pode passar\và vontade. Eu vou\vcompartilhar isso\vaqui com todos os\voutros guardas!",
  ["_SaffronGymChanneler1AfterBattleText"] = "Em uma batalha de\niguais, aquele\vcom mais força de\vvontade vencerá!\fSe você quer der-\nrotar a SABRINA,\vfoque na vitória!",
  ["_SaffronGymChanneler1BattleText"] = "SABRINA é mais\njovem do que eu,\vmas eu a respeito!",
  ["_SaffronGymChanneler1EndBattleText"] = "Não\nfui o bastante!",
  ["_SaffronGymChanneler2AfterBattleText"] = "Tenho que ensinar\ntécnicas melhores\vaos meus POKéMON!",
  ["_SaffronGymChanneler2BattleText"] = "POKéMON se moldam\nà aparência de\vseu treinador.\fSeus POKéMON devem\nser durões, então!",
  ["_SaffronGymChanneler2EndBattleText"] = "Eu\nsabia!",
  ["_SaffronGymChanneler3AfterBattleText"] = "Eu já sabia que\nisso iria aconte-\vcer assim.",
  ["_SaffronGymChanneler3BattleText"] = "Você e eu, nossos\nPOKéMON devem\vbatalhar!",
  ["_SaffronGymChanneler3EndBattleText"] = "Eu\nperdi afinal!",
  ["_SaffronGymGuideBeatSabrinaText"] = "Poderes psíquicos,\nhmm?\fSe eu tivesse\nisso, teria feito\vuma boa nota nos\vcaça-níqueis!",
  ["_SaffronGymGuideChampInMakingText"] = "E aí! Campeão em\nconstrução!\fOs POKéMON da LÍ-\nDER SABRINA usam\vpoderes psíquicos\vem vez de força!\fPOKéMON Lutadores\nsão fracos contra\vgolpes psíquicos!\fVão virar geleia\nantes mesmo de\vmirar o soco!",
  ["_SaffronGymSabrinaMarshBadgeInfoText"] = "A INSÍGNIA PÂNTANO\nfará POKéMON\vaté o {SLOT:BB}70 te\vobedecerem!\fMas POKéMON mais\nfortes que isso\vficarão ariscos,\vignorando suas\vordens durante\va batalha!\fBasta não elevar\ndemais os seus\vPOKéMON!\fEspere, por favor,\nleve essa MT com\vvocê também!",
  ["_SaffronGymSabrinaPostBattleAdviceText"] = "Todo mundo têm po-\nderes psíquicos!\vAs pessoas apenas\vnão percebem isso!",
  ["_SaffronGymSabrinaReceivedMarshBadgeText"] = "Estou\nchocada!\vMas uma derrota\vé uma derrota.\fEu admito que não\nme esforcei o su-\vficiente para ga-\vrantir a vitória!\fVocê conquistou a\nINSÍGNIA PÂNTANO!",
  ["_SaffronGymSabrinaReceivedTM46Text"] = "{PLAYER} recebeu\na MT46!",
  ["_SaffronGymSabrinaTM46NoRoomText"] = "Sua bolsa já está\ncheia de itens!",
  ["_SaffronGymSabrinaText"] = "Eu tive uma visão\nda sua chegada!\fEu tenho poderes\npsíquicos desde\vquando eu era\vuma criança.\fPrimeiro aprendi a\nentortar colheres\vcom minha mente.\fEu não gosto de\nlutar, mas já que\vvocê quer, eu vou\vte mostrar meus\vpoderes psíquicos!",
  ["_SaffronGymYoungster1AfterBattleText"] = "POKéMON Psíquicos\ntemem apenas os\vdo tipo Inseto!",
  ["_SaffronGymYoungster1BattleText"] = "Nosso poder oculto\nte assusta?",
  ["_SaffronGymYoungster1EndBattleText"] = "Não\nprevi isso!",
  ["_SaffronGymYoungster2AfterBattleText"] = "SABRINA acabou de\ntrucidar o MESTRE\vDO CARATÊ aqui do\vprédio ao lado!",
  ["_SaffronGymYoungster2BattleText"] = "Você sabia que\napenas força não\vé o bastante?",
  ["_SaffronGymYoungster2EndBattleText"] = "Eu não\nacredito nisso!",
  ["_SaffronGymYoungster3AfterBattleText"] = "Antigamente tinham\n2 GINÁSIOS POKé-\vMON em SAFFRON.\fO DOJO DE ARTES\nMARCIAIS da porta\vao lado perdeu\vseu título quando\vnós os dizimamos!",
  ["_SaffronGymYoungster3BattleText"] = "SABRINA é jovem,\nmas ela também é\vnossa LÍDER!\fVocê não chegará\naté ela tão\vfacilmente!",
  ["_SaffronGymYoungster3EndBattleText"] = "Eu\nperdi a minha\vconcentração!",
  ["_SaffronGymYoungster4AfterBattleText"] = "Isso mesmo! Eu\nusei telepatia\vpara ler a sua\vmente!",
  ["_SaffronGymYoungster4BattleText"] = "O GINÁSIO POKéMON\nDE SAFFRON é fa-\vmoso por seus\vparanormais!\fVocê quer ver a\nSABRINA!\vEu posso ver isso!",
  ["_SaffronGymYoungster4EndBattleText"] = "Arrgh!",
  ["_SaffronMartCooltrainerFText"] = "REVIVER é caro,\nmas recupera um\vPOKéMON desmaiado!",
  ["_SaffronMartSuperNerdText"] = "Para espantar os\nPOKéMON fracos, o\vREPEL. MÁXIMO\vdura bem mais que\vo SUPERREPELENTE.",
  ["_SaffronPidgeyHouseBrunetteGirlText"] = "Obrigado por me\nescrever. Espero\vte ver em breve!\fEi! Não leia a\nminha carta!",
  ["_SaffronPidgeyHousePaperText"] = "Me deram de\npresente um\vMAIS PP.\fÉ usado para\naumentar os PP\vde uma técnica!",
  ["_SaffronPidgeyHousePidgeyText"] = "PIDGEY: Curucuu!",
  ["_SaffronPidgeyHouseYoungsterText"] = "A IMITADORA é\nfofinha! Vou dar\vuma POKéBONECA\vpara ela!",
  ["_SaffronPokecenterBeautyText"] = "POKéMON crescem de\nnível em veloci-\vdades diferentes,\vvariando entre\vcada espécie.",
  ["_SaffronPokecenterGentlemanText"] = "SILPH CO. é muito\nfamosa. Por isso\vatraiu a atenção\vda EQUIPE ROCKET!",
  ["_SandshrewDexEntry"] = "Cava fundo no solo\nem locais áridos e\ndistantes da água.\fEle emerge para a\nsuperfície apenas\npara caçar comida",
  ["_SandslashDexEntry"] = "Se enrola em uma\nbola espinhenta\nquando é ameaçado,\fassim pode rolar\ntanto para atacar\nquanto escapar",
  ["_SaveOptionText"] = "A opção de SALVAR\nestá na tela de\vMENU.",
  ["_SavingEnergyText"] = "{USER}\nnão está mais{SCROLL}inabilitada!",
  ["_ScaredText"] = "{RAM:wBattleMonNick} está\ncom medo de mexer!",
  ["_ScytherDexEntry"] = "Ágil e rápido como\num ninja, é capaz\nde criar a ilusão\fde haver mais de\num dele, enquanto\nfatia suas presas",
  ["_SeadraDexEntry"] = "É capaz de nadar\nrapidamente para\ntrás usando suas\fnadadeiras peito-\nrais em forma de\nasas e sua cauda",
  ["_SeafoamIslandsB4FArticunoBattleText"] = "Gyaoo!",
  ["_SeafoamIslandsB4FBouldersSignText"] = "Rochedos podem\nalterar o fluxo\vda água!",
  ["_SeafoamIslandsB4FDangerSignText"] = "PERIGO! Região de\ncorrenteza forte!",
  ["_SeakingDexEntry"] = "Durante a estação\nde acasalamento no\noutono, são vistos\fnadando poderosa-\nmente rio acima e\nem riachos",
  ["_SeelDexEntry"] = "O chifre protube-\nrante de sua cabe-\nça é muito duro.\fEle é usado para\natravessar grossos\nblocos de gelo",
  ["_SentToBoxText"] = "Sem espaço para\nmais POKéMON!\v{RAM:wBoxMonNicks} foi\venviado para a\vPOKéCAIXA{RAM:wStringBuffer} no PC!",
  ["_ShallWeHealYourPokemonText"] = "Aqui nós podemos\nrecuperar os seus\vPOKéMON de volta\và saúde plena!",
  ["_ShellderDexEntry"] = "Sua concha dura\nrepele qualquer\ntipo de ataque.\fSó fica vulnerável\nquando a sua con-\ncha está aberta",
  ["_ShroudedInMistText"] = "PC está\nenvolto em névoa!",
  ["_SilphCo10FGiovanniILostAgainText"] = "Arrgh!!\nPerdi de novo!?",
  ["_SilphCo10FPorygonText"] = "Tem um POKéMON\nnesse monitor!",
  ["_SilphCo10FRocketAfterBattleText"] = "Boa tentativa, mas\na Sala de Reu-\vniões fica no\vandar de cima.",
  ["_SilphCo10FRocketBattleText"] = "Bem-vindo ao 10º\nandar! Que bom\vque você chegou!",
  ["_SilphCo10FRocketEndBattleText"] = "Fiquei\natordoado!",
  ["_SilphCo10FScientistAfterBattleText"] = "Ficou satisfeito\nem me derrotar?\vEntão vá pra casa!",
  ["_SilphCo10FScientistBattleText"] = "Já chega dos seus\njoguinhos!",
  ["_SilphCo10FScientistEndBattleText"] = "Minhas\nvidas acabaram!",
  ["_SilphCo10FSilphWorkerFImScaredText"] = "Buááááá!\nEstou assustada!",
  ["_SilphCo10FSilphWorkerFQuietAboutMyCryingText"] = "Buááááá!\nEstou assustada!",
  ["_SilphCo11FBeautyText"] = "SECRETÁRIA: Muito\nobrigada por nos\vresgatar!\fNós admiramos a\nsua coragem.",
  ["_SilphCo11FGiovanniText"] = "Ah, {PLAYER}!\nEntão voltamos a\vnos encontrar!\fO PRESIDENTE e eu\nestamos discutin-\vdo uma proposta\vcomercial que é\virrecusável.\fMantenha seu nariz\nfora dos assuntos\vdos adultos...\fOu, prepare-se\npara encrenca!",
  ["_SilphCo11FGiovanniYouRuinedOurPlansText"] = "Que se exploda!\nVocê arruinou os\vnossos planos com\va SILPH!\fMas a EQUIPE\nROCKET jamais irá\vperecer!\f{PLAYER}! Nunca\nse esqueça que\vtodos os POKéMON\vexistem para a\vEQUIPE ROCKET!\fEu me vou, mas\neu retornarei!",
  ["_SilphCo11FRocket1AfterBattleText"] = "Então, você quer\nver meu CHEFE?",
  ["_SilphCo11FRocket1BattleText"] = "Pare aí mesmo!\nNão se mova!",
  ["_SilphCo11FRocket1EndBattleText"] = "Não...\nPor favor!",
  ["_SilphCo11FRocket2AfterBattleText"] = "Tome cuidado, meu\nCHEFE gosta de\vPOKéMON fortes!",
  ["_SilphCo11FRocket2BattleText"] = "Alto! Você tem\nhora marcada com\vmeu CHEFE?",
  ["_SilphCo11FRocket2EndBattleText"] = "Aaah!\nDemolido!",
  ["_SilphCo11FSilphPresidentMasterBallDescriptionText"] = "PRESIDENTE:\nVocê não pode\vcomprar isso em\vlugar nenhum!\fÉ nosso protótipo\nsecreto da POKé\vBOLA MESTRA!\fEla vai capturar\nqualquer POKéMON\vsem nunca falhar!\fMas deve manter\nisso em segredo,\ventretanto.",
  ["_SilphCo11FSilphPresidentNoRoomText"] = "Você não tem\nespaço pra isso.",
  ["_SilphCo11FSilphPresidentReceivedMasterBallText"] = "{PLAYER} recebeu\num {RAM:wStringBuffer}!",
  ["_SilphCo11FSilphPresidentText"] = "PRESIDENTE: Muito\nobrigado por\vsalvar a SILPH!\fEu nunca irei me\nesquecer que você\vnos salvou quando\vcorríamos perigo!\fTenho que lhe\nagradecer de\valguma forma!\fComo eu sou rico,\nposso te dar\vqualquer coisa!\fAqui, talvez isso\nseja suficiente!",
  ["_SilphCo1FLinkReceptionistText"] = "Bem-vindo!\fNosso PRESIDENTE\nestá na sala de\vreuniões do 11º\vandar!",
  ["_SilphCo2FRocket1AfterBattleText"] = "Blocos em formato\nde losango são\vteleportadores!\fUsam tecnologia de\nponta para trans-\vportar pessoas!",
  ["_SilphCo2FRocket1BattleText"] = "Nenhuma criança é\npermitida aqui!",
  ["_SilphCo2FRocket1EndBattleText"] = "Forte!",
  ["_SilphCo2FRocket2AfterBattleText"] = "SILPH CO. vai se\nunir a EQUIPE\vROCKET!",
  ["_SilphCo2FRocket2BattleText"] = "Ei, garoto! O que\nfaz aqui?",
  ["_SilphCo2FRocket2EndBattleText"] = "Eu me\natrapalhei!",
  ["_SilphCo2FScientist1AfterBattleText"] = "Eu trabalho para\nos dois, SILPH e\vEQUIPE ROCKET!",
  ["_SilphCo2FScientist1BattleText"] = "Socorro! Sou só um\nfuncionário aqui.",
  ["_SilphCo2FScientist1EndBattleText"] = "Como\nvocê sabia que eu\vera um ROCKET?",
  ["_SilphCo2FScientist2AfterBattleText"] = "Consegue resolver\nesse labirinto?",
  ["_SilphCo2FScientist2BattleText"] = "Área restrita!\nVá pra casa!",
  ["_SilphCo2FScientist2EndBattleText"] = "Você\né bom.",
  ["_SilphCo2FSilphWorkerFReceivedTM36Text"] = "{PLAYER} recebeu\n{RAM:wStringBuffer}!",
  ["_SilphCo2FSilphWorkerFTM36ExplanationText"] = "MT36 contém\nAUTODESTRUIÇÃO!\fÉ poderosa, mas o\nPOKéMON que usar\vessa técnica irá\vdesmaiar!\vSeja cauteloso.",
  ["_SilphCo2FSilphWorkerFTM36NoRoomText"] = "Você não tem\nespaço pra isso.",
  ["_SilphCo3FRocketAfterBattleText"] = "Uma dica? Você\npoderá abrir\vportas com o\vCARTÃO-CHAVE!",
  ["_SilphCo3FRocketBattleText"] = "Pare de se meter\nconosco, pivete!",
  ["_SilphCo3FRocketEndBattleText"] = "\nEu desisto!",
  ["_SilphCo3FScientistAfterBattleText"] = "Humph...\fA EQUIPE ROCKET me\ndisse que se eu\vajudasse, eles me\vdeixariam estudar\vPOKéMON raros!",
  ["_SilphCo3FScientistBattleText"] = "Eu apoio a EQUIPE\nROCKET mais do\vque a SILPH CO.!",
  ["_SilphCo3FScientistEndBattleText"] = "Você me\npegou de jeito!",
  ["_SilphCo3FSilphWorkerMWhatShouldIDoText"] = "Eu trabalho para\na SILPH. O que eu\vposso fazer?",
  ["_SilphCo3FSilphWorkerMYouSavedUsText"] = "{PLAYER}! Você e\nseus POKéMON\vnos salvaram!",
  ["_SilphCo4FRocket1AfterBattleText"] = "Uahahaha!\nMeu CHEFE estava\vde olho aqui\vnesse lugar!",
  ["_SilphCo4FRocket1BattleText"] = "A EQUIPE ROCKET\ntomou controle da\vSILPH CO.!",
  ["_SilphCo4FRocket1EndBattleText"] = "Arrgh!",
  ["_SilphCo4FRocket2AfterBattleText"] = "É melhor eu ir\navisar o CHEFE\vlá no 11º andar!",
  ["_SilphCo4FRocket2BattleText"] = "Intruso avistado!",
  ["_SilphCo4FRocket2EndBattleText"] = "Quem\né você?",
  ["_SilphCo4FScientistAfterBattleText"] = "As portas estão\ntrancadas eletro-\vnicamente! \vUm CARTÃO-CHAVE\vvai abri-las!",
  ["_SilphCo4FScientistBattleText"] = "Meu POKéMON é meu\nmeu leal soldado!",
  ["_SilphCo4FScientistEndBattleText"] = "Droga!\nPOKéMON fracote!",
  ["_SilphCo4FSilphWorkerMImHidingText"] = "Sshiuu! Não vê que\nestou escondido?",
  ["_SilphCo4FSilphWorkerMTeamRocketIsGoneText"] = "Hã? A EQUIPE \nROCKET já se foi?",
  ["_SilphCo5FPokemonReport1Text"] = "É um RELATÓRIO\nPOKéMON!\fLABORATÓRIO POKéMON\ncriou PORYGON, o\vprimeiro POKéMON\vde realidade\vvirtual.",
  ["_SilphCo5FPokemonReport2Text"] = "É um RELATÓRIO\nPOKéMON!\fFoi confirmada a\nexistência de\vmais de 160\vtécnicas POKéMON.",
  ["_SilphCo5FPokemonReport3Text"] = "É um RELATÓRIO\nPOKéMON!\f4 POKéMON evoluem\napenas quando\vsão trocados pelo\vacessório chamado\v‘link-cable.'",
  ["_SilphCo5FRockerAfterBattleText"] = "Você ainda está\nno 5º andar. É um\vlongo caminho até\vo meu CHEFE!",
  ["_SilphCo5FRockerBattleText"] = "O quê? Não era\npra ter nenhuma\vcriança aqui!",
  ["_SilphCo5FRockerEndBattleText"] = "Ai\ncaramba!",
  ["_SilphCo5FRocket1AfterBattleText"] = "Não é sábio entrar\nnuma briga contra\va EQUIPE ROCKET!",
  ["_SilphCo5FRocket1BattleText"] = "Eu ouvi que uma\ncriança estava\vzanzando por aí.",
  ["_SilphCo5FRocket1EndBattleText"] = "Booom!",
  ["_SilphCo5FRocket2AfterBattleText"] = "Isso me fez\nlembrar...\fKOFFING evolui\npara WEEZING!",
  ["_SilphCo5FRocket2BattleText"] = "Coff...\nCoff...",
  ["_SilphCo5FRocket2EndBattleText"] = "Coff...\nCoff...",
  ["_SilphCo5FScientistAfterBattleText"] = "Nós trabalhamos na\nPOKé BOLA suprema\vque pode capturar\vqualquer POKéMON!",
  ["_SilphCo5FScientistBattleText"] = "Nós estudamos a\ntecnologia das\vPOKé BOLAS nesse\vandar!",
  ["_SilphCo5FScientistEndBattleText"] = "Droga!\nQue estouro!",
  ["_SilphCo5FSilphWorkerMThatsYouRightText"] = "É melhor eu ir\navisar o CHEFE\vlá no 11º andar!",
  ["_SilphCo5FSilphWorkerMYoureOurHeroText"] = "EQUIPE ROCKET está\nalvoroçada atrás\vde um intruso.\vÉ você, não é?",
  ["_SilphCo6FRocket1AfterBattleText"] = "Não importa!\nMeus irmãos vão\vme vingar!",
  ["_SilphCo6FRocket1BattleText"] = "Eu sou um dos 4\nIRMÃOS ROCKET!",
  ["_SilphCo6FRocket1EndBattleText"] = "Meu\nfogo apagou!",
  ["_SilphCo6FRocket2AfterBattleText"] = "Se você defende a\njustiça, você\vtraiu o mal!",
  ["_SilphCo6FRocket2BattleText"] = "Você ousa trair\na EQUIPE ROCKET?",
  ["_SilphCo6FRocket2EndBattleText"] = "\nSeu traidor!",
  ["_SilphCo6FScientistAfterBattleText"] = "FILIAL DE TIKSI?\nFica na Rússia,\vno meio do nada!",
  ["_SilphCo6FScientistBattleText"] = "Aquele PRESIDENTE\nfedorento!\fEle não deveria\nter me mandado\vpara a FILIAL DE\vTIKSI!",
  ["_SilphCo6FScientistEndBattleText"] = "Droga!",
  ["_SilphCo6FSilphWorkerF1HaveToMarryHimText"] = "Fiquei com pena\ndele, e agora vou\vme casar com ele!",
  ["_SilphCo6FSilphWorkerF1SuchACowardText"] = "Olha pra ele!\nMas que covarde!",
  ["_SilphCo6FSilphWorkerF2TeamRocketConquerWorldText"] = "A EQUIPE ROCKET\nestá tentando\vdominar o mundo\vusando POKéMON!",
  ["_SilphCo6FSilphWorkerF2TeamRocketRanText"] = "A EQUIPE ROCKET\nfugiu por causa\vde você!",
  ["_SilphCo6FSilphWorkerM1BackToWorkText"] = "Bem, agora eu acho\nmelhor eu voltar\vao trabalho!",
  ["_SilphCo6FSilphWorkerM1TookOverTheBuildingText"] = "Os ROCKETs vieram\ne tomaram conta\vdo prédio todo!",
  ["_SilphCo6FSilphWorkerM3TargetedSilphText"] = "Eles devem ter\nvisado a SILPH\vdevido aos nossos\vprodutos POKéMON.",
  ["_SilphCo6FSilphWorkerM3WorkForSilphText"] = "Venha trabalhar na\nSILPH quando você\vficar mais velho!",
  ["_SilphCo6FSilphWorkerMHelpMePleaseText"] = "Oh, querida...\nQuerida, me ajude\vpor favor!",
  ["_SilphCo6FSilphWorkerMWeGotEngagedText"] = "Agora nós estamos\nnoivos! Heheh!",
  ["_SilphCo7FRivalDefeatedText"] = "Oh, ho!\nEntão você está\vpronto para o\vCHEFE dos ROCKET!",
  ["_SilphCo7FRivalGoodLuckToYouText"] = "Bem, {PLAYER}!\fEstou indo nessa!\n\fChecando minha\nPOKéDEX, pude\vver quais são os\vmais fortes e co-\vmo eles evoluem!\fEu estou indo para\na LIGA POKéMON\vpara derrubar a\vELITE DOS QUATRO!\fEu irei me tornar\no treinador mais\vpoderoso do mundo!\fBoa sorte pra você\ntambém, {PLAYER}!\vFica de boa!\vFalous!",
  ["_SilphCo7FRivalText"] = "{RIVAL}: Por que\ndemorou, {PLAYER}?",
  ["_SilphCo7FRivalVictoryText"] = "{RIVAL}: Como eu\nposso dizer isso?\fVocê não é bom o\nbastante para\vbrincar com gente\vgrande!",
  ["_SilphCo7FRivalWaitedHereText"] = "{RIVAL}: Hahaha!\nImaginei que você\vapareceria se eu\vo esperasse aqui!\fAcho que a EQUIPE\nROCKET te atrasou\vum pouco! Não que\veu me importe!\fEu te vi aqui em\nSAFFRON, então eu\vresolvi conferir\vse você melhorou!",
  ["_SilphCo7FRocket1AfterBattleText"] = "Você não vai achar\nmeu CHEFE se só\vzanzar por aí!",
  ["_SilphCo7FRocket1BattleText"] = "Essa não! Eu sinto\ncheiro de um rato!",
  ["_SilphCo7FRocket1EndBattleText"] = "Não con-\nsigo ver nada!",
  ["_SilphCo7FRocket2AfterBattleText"] = "Não importa.\nMeus irmãos vão \vretribuir o favor!",
  ["_SilphCo7FRocket2BattleText"] = "Eu sou um dos 4\nIRMÃOS ROCKET!",
  ["_SilphCo7FRocket2EndBattleText"] = "Aahh!\nIrmãos, eu perdi!",
  ["_SilphCo7FRocket3AfterBattleText"] = "Vá pra casa, antes\nque meu CHEFE\vfique irritado!",
  ["_SilphCo7FRocket3BattleText"] = "Essa não! Eu sinto\ncheiro de um rato!",
  ["_SilphCo7FRocket3EndBattleText"] = "Tudo bem!\nEu perdi!",
  ["_SilphCo7FScientistAfterBattleText"] = "Apesar da sua\nidade, você é um\vtreinador muito\vtalentoso!",
  ["_SilphCo7FScientistBattleText"] = "Heheh!\fVocê me confundiu\ncom um funcio-\vnário da SILPH?",
  ["_SilphCo7FScientistEndBattleText"] = "Estou\nacabado!",
  ["_SilphCo7FSilphWorkerM1HaveThisPokemonText"] = "Ah! Oi! Você não é\nda EQUIPE ROCKET!\vVocê veio para\vme salvar?\vPuxa, obrigado!\fQuero que você\nfique com esse\vPOKéMON por estar\vnos salvando.",
  ["_SilphCo7FSilphWorkerM1IsOurPresidentOkText"] = "O CHEFE da EQUIPE\nROCKET foi para a\vsala de reuniões!\vSerá que nosso\vPRESIDENTE está\vem segurança?",
  ["_SilphCo7FSilphWorkerM1LaprasDescriptionText"] = "É um LAPRAS.\nEle é muito inte-\vligente.\fNós o mantínhamos\nno laboratório,\vmas ele ficará\vmuito melhor fora\vdaqui e com você!\fEu acho que você\nserá um ótimo\vtreinador para\vesse LAPRAS!\fEle é um ótimo\nnadador. Pode até\vte dar uma carona!",
  ["_SilphCo7FSilphWorkerM1SavedText"] = "Finalmente salvo!\nMuito obrigado!",
  ["_SilphCo7FSilphWorkerM2AfterTheMasterBallText"] = "A EQUIPE ROCKET\nestá atrás da\vBOLA MESTRA que\vpode capturar\vqualquer POKéMON!",
  ["_SilphCo7FSilphWorkerM2CancelledMasterBallText"] = "Nós cancelamos o\nprojeto da BOLA\vMESTRA por culpa\vda EQUIPE ROCKET.",
  ["_SilphCo7FSilphWorkerM3ItWouldBeBadText"] = "Seria ruim se a\nEQUIPE ROCKET\vdominasse a SILPH\vou nossos POKéMON!",
  ["_SilphCo7FSilphWorkerM3YouChasedOffTeamRocketText"] = "Uau! Você botou a\nEQUIPE ROCKET pra\vcorrer sozinho?",
  ["_SilphCo7FSilphWorkerM4ItsReallyDangerousHereText"] = "Ei, você! É muito\nperigoso aqui!\vVocê veio para me\vsalvar? Não vai\vconseguir!",
  ["_SilphCo7FSilphWorkerM4SafeAtLastText"] = "Finalmente salva!\nPuxa, obrigada!",
  ["_SilphCo8FRocket1AfterBattleText"] = "Se você não desis-\ntir, eu chamarei\vreforços!",
  ["_SilphCo8FRocket1BattleText"] = "É o mais longe que\nvocê vai chegar!",
  ["_SilphCo8FRocket1EndBattleText"] = "Talvez um\npouco mais longe!",
  ["_SilphCo8FRocket2AfterBattleText"] = "Eu vou deixar você\npara meus irmãos!",
  ["_SilphCo8FRocket2BattleText"] = "Eu sou um dos 4\nIRMÃOS ROCKET!",
  ["_SilphCo8FRocket2EndBattleText"] = "Ahhh!\nMeus irmãos!",
  ["_SilphCo8FScientistAfterBattleText"] = "Então, você acha\nque o prédio da\vSILPH parece um\vlabirinto?",
  ["_SilphCo8FScientistBattleText"] = "Você está nos cau-\nsando problemas!",
  ["_SilphCo8FScientistEndBattleText"] = "Hein?\nEu perdi?",
  ["_SilphCo8FSilphWorkerMSilphIsFinishedText"] = "Imagino se a SILPH\nestá acabada...",
  ["_SilphCo8FSilphWorkerMThanksForSavingUsText"] = "Obrigado por nos\nsalvar!",
  ["_SilphCo9FRocket1AfterBattleText"] = "Se eu tivesse\ncomeçado a ser um\vtreinador na sua\vidade...",
  ["_SilphCo9FRocket1BattleText"] = "Seus POKéMON pare-\ncem adorar você,\vjovenzinho!",
  ["_SilphCo9FRocket1EndBattleText"] = "Ghaaah!",
  ["_SilphCo9FRocket2AfterBattleText"] = "Meus irmãos vão\nme vingar!",
  ["_SilphCo9FRocket2BattleText"] = "Eu sou um dos 4\nIRMÃOS ROCKET!",
  ["_SilphCo9FRocket2EndBattleText"] = "Aarg!\nIrmãos, eu perdi!",
  ["_SilphCo9FScientistAfterBattleText"] = "Explorar os pontos\nfracos funcionam!\vEstude sobre os\vtipos elementais!",
  ["_SilphCo9FScientistBattleText"] = "Os seus POKéMON\npossuem vários\vpontos fracos!\vEu posso apontar\vtodos eles!",
  ["_SilphCo9FScientistEndBattleText"] = "Fiquei\ndesapontado!",
  ["_SkyAttackGlowingText"] = "\nestá brilhando!",
  ["_SlowbroDexEntry"] = "O SHELLDER que\nestá preso em sua\ncauda, parece se\falimentar dos res-\ntos deixados pelo\nseu hospedeiro",
  ["_SlowpokeDexEntry"] = "Inacreditavelmente\nlento e desligado.\nDemora 5 segundos\fpara que ele sinta\nalguma dor quando\nestá sob ataque",
  ["_SnorlaxDexEntry"] = "Muito preguiçoso.\nSó come e dorme.\nConforme aumenta\fseu peso enorme,\nfica cada vez mais\npreguiçoso",
  ["_SoYouWantPrizeText"] = "Então, você quer\n{RAM:wNameBuffer}?",
  ["_SorryNeedMoreCoinsText"] = "Oops! Você não tem\nespaço suficiente.",
  ["_SpearowDexEntry"] = "Come insetos em\náreas gramadas.\nEle bate suas asas\fem alta velocidade\npara se manter\npairando no ar",
  ["_SquirtleDexEntry"] = "Após nascer, suas\ncostas endurecem\nformando um casco.\fLança poderosos\njatos de espuma\npela boca",
  ["_StarmieDexEntry"] = "A pedra em seu\ncentro brilha com\nas sete cores do\farco-íris. Algumas\npessoas a usam\ncomo joia",
  ["_StartSlotMachineText"] = "Começar!",
  ["_StartedSleepingEffect"] = "{USER}\ncomeçou a dormir!",
  ["_StaryuDexEntry"] = "Um POKéMON enigmá-\ntico que pode re-\ngenerar qualquer\fapêndice de seu\ncorpo que for per-\ndido em batalha",
  ["_StatusChangesEliminatedText"] = "As alterações de\nATRIBUTOS foram{SCROLL}todas eliminadas!",
  ["_StoppedEvolvingText"] = "Hã? {RAM:wStringBuffer}\nparou de evoluir!",
  ["_StrengthsAndWeaknessesText"] = "Todos os tipos de\nPOKéMON possuem\vcertos pontos de\vvantagem ou\vfraqueza contra\voutros tipos.",
  ["_SubstituteBrokeText"] = "O SUBSTITUTO\nse quebrou!",
  ["_SubstituteText"] = "Um SUBSTITUTO\nfoi criado!",
  ["_SubstituteTookDamageText"] = "O SUBSTITUTO tomou\no dano no lugar{SCROLL}de ROCKET!",
  ["_SuckedHealthText"] = "Absorveu saúde de\nROCKET!",
  ["_SuperEffectiveText"] = "Foi supereficaz!",
  ["_SurfingGotOnText"] = "{PLAYER} subiu\nem {RAM:wNameBuffer}!",
  ["_SurfingNoPlaceToGetOffText"] = "Não tem lugar\npara descer!",
  ["_SwitchOnText"] = "Ligado!",
  ["_TM21ExplanationText"] = "\fMT21 contém\nMEGADRENO.\fMetade do dano\ncausado é drenado\ve irá curar o seu\vPOKéMON!",
  ["_TM24ExplanationText"] = "\fMT24 contém\nRELÂMPAGO!\fEnsine para um\nPOKéMON elétrico!",
  ["_TM34ExplanationText"] = "\fUma MT contém uma\ntécnica que pode\vser ensinada para\vum POKéMON!\fAs MT só funcionam\numa vez! Então\vao ensinar uma\vnova técnica,\vescolha o POKéMON\vcom cuidado!\fMT34 contém\nAGUARDAR!\fSeu POKéMON irá\nabsorver o dano\vrecebido durante\va batalha e então\vdevolver em dobro!",
  ["_TM46ExplanationText"] = "\fMT46 contém\nONDA PSÍQUICA!\vEssa técnica usa\vpoderosas ondas\vde energia psí-\vquica para causar\vdano!",
  ["_TangelaDexEntry"] = "Todo o seu corpo é\nenrolado por lar-\ngas vinhas que se\fparecem com algas\nmarinhas, que se\nbalançam ao andar",
  ["_TaurosDexEntry"] = "Quando ele tem um\ninimigo em mira,\navança furiosamen-\fte enquanto chico-\nteia seu corpo com\nseus longos rabos",
  ["_TeachMachineMoveText"] = "Ela contém\n{RAM:wStringBuffer}!\fQuer ensinar\n{RAM:wStringBuffer}\vpara um POKéMON?",
  ["_TentacoolDexEntry"] = "Deriva nos mares\nrasos. Pescadores\nque o pegam por\facidente acabam\nsendo punidos por\nseu ácido ardente",
  ["_TentacruelDexEntry"] = "Os tentáculos nor-\nmalmente se mantém\ncurtos. Mas quando\fcaça, se extendem\npara agarrar as\nsuas presas",
  ["_TextIDErrorText"] = "{NUM:hTextID, 1, 2} ERRO.",
  ["_Thanks1Text"] = "Ei, obrigado!",
  ["_Thanks2Text"] = "Obrigado!",
  ["_Thanks3Text"] = "Ah, que chato.",
  ["_ThrashingAboutText"] = "{USER}\nestá confusa!",
  ["_ThrewAwayItemText"] = "Jogou fora\n{RAM:wNameBuffer}.",
  ["_ThrewBaitText"] = "{PLAYER} jogou\numa ISCA.",
  ["_ThrewRockText"] = "{PLAYER} jogou\numa PEDRA.",
  ["_ThrowBallAtTrainerMonText1"] = "O treinador blo-\nqueou a BOLA!",
  ["_ThrowBallAtTrainerMonText2"] = "Não seja\num ladrão!",
  ["_TimesUpText"] = "RÁDIO:\nDing-dong!\fAcabou o tempo!",
  ["_TooImportantToTossText"] = "Isso é importante\ndemais! Não pode\vjogar fora assim!",
  ["_TooWeakSubstituteText"] = "Sem forças para\nusar SUBSTITUTO!",
  ["_TookInSunlightText"] = " está\nabsorvendo a{SCROLL}luz solar!",
  ["_TossHowManyText"] = "Quantos?",
  ["_TownMapText"] = "Um MAPA de KANTO.",
  ["_TradeCenterOpponentText"] = "!",
  ["_TradeForText"] = "Pelo {RAM:wStringBuffer}\nde {PLAYER},",
  ["_TradeSendsText"] = "{RAM:wLinkEnemyTrainerName} envia\n{RAM:wNameBuffer}.",
  ["_TradeTakeCareText"] = "Cuide bem de\n{RAM:wNameBuffer}.",
  ["_TradeTransferredText"] = "{RAM:wNameBuffer} foi\ntransferido.",
  ["_TradeWavesFarewellText"] = "{RAM:wLinkEnemyTrainerName} acena\nem despedida",
  ["_TradeWentToText"] = "{RAM:wStringBuffer} foi\npara {RAM:wLinkEnemyTrainerName}.",
  ["_TradeWillTradeText"] = "{RAM:wLinkEnemyTrainerName} vai\ntrocar {RAM:wNameBuffer}",
  ["_TradedForText"] = "{PLAYER} trocou\n{RAM:wInGameTradeGiveMonName} por\v{RAM:wInGameTradeReceiveMonName}!",
  ["_TradeforText"] = "por {RAM:wStringBuffer}\nde {PLAYER}.",
  ["_TrainerAboutToUseText"] = "{RAM:wTrainerName} vai\nusar\v{RAM:wEnemyMonNick}!\f{PLAYER} vai trocar\nde POKéMON?",
  ["_TrainerDefeatedText"] = "{PLAYER} derrotou\n{RAM:wTrainerName}!",
  ["_TrainerNameText"] = "{RAM:wNameBuffer}: ",
  ["_TrainerSentOutText"] = "{RAM:wTrainerName} enviou\n{RAM:wEnemyMonNick}!",
  ["_TrainerWantsToFightText"] = "{RAM:wTrainerName} quer\nlutar!",
  ["_TransformedText"] = "{USER}\nse transformou em{SCROLL}um {RAM:wNameBuffer}!",
  ["_TryingToLearnText"] = "{RAM:wLearnMoveMonName} está\ntentando aprender\v{RAM:wStringBuffer}!\fMas, {RAM:wLearnMoveMonName}\nnão pode aprender\vmais que 4 golpes!\fApague um golpe\nantigo pra abrir\vespaço pra {RAM:wStringBuffer}?",
  ["_TurnPageText"] = "Virar a página?",
  ["_TurnedAwayText"] = "{RAM:wBattleMonNick}\ndesviou o olhar!",
  ["_TurnedOnPC1Text"] = "{PLAYER} ligou\no PC.",
  ["_TurnedOnPC2Text"] = "{PLAYER} ligou\no PC.",
  ["_UnaffectedText"] = "{TARGET}\nnão foi afetado!",
  ["_UndergroundPathRoute6GirlText"] = "As pessoas vivem\nperdendo itens no\vTÚNEL SUBTERRÂNEO.",
  ["_UndergroundPathRoute7CopyUnusedGirlText"] = "Eu queri ir fazer\ncompras nas lojas\vde CELADON mas...\fTem tantas pessoas\nmau encaradas\vrondando por lá.",
  ["_UndergroundPathRoute7CopyUnusedGoesUnderSaffronText"] = "O TÚNEL SUBTERRÂNEO\npassa por baixo\vde SAFFRON e vai\vaté LAVENDER.\fSe quer ir para\nCERULEAN, vá para\vo prédio do outro\vlado da rua.",
  ["_UndergroundPathRoute7CopyUnusedMiddleAgedManText"] = "Veio aqui fazer\ncompra em CELADON?\fApenas saia e vá\nrumo ao oeste!",
  ["_UndergroundPathRoute7CopyUnusedTeamRocketHadAHideoutText"] = "A EQUIPE ROCKET\ntem um esconderi-\vjo secreto na\vCIDADE DE CELADON?",
  ["_UndergroundPathRoute7MiddleAgedManText"] = "Ouvi dizer que um\nPOKéMON sonolento\vapareceu perto da\vCIDADE DE CELADON.",
  ["_UndergroundPathRoute8GirlText"] = "O CENTRO COMERCIAL\nDE CELADON tem\vuma grande vari-\vedade de itens.",
  ["_UnleashedEnergyText"] = "{USER}\nestá confuso!",
  ["_UnusedBenchGuyText1"] = "Eu queria poder\ncapturar POKéMON.",
  ["_UnusedBenchGuyText2"] = "Estou cansado de\ntanta diversão...",
  ["_UnusedBenchGuyText3"] = "O gerente da SILPH\nestá escondido na\vZONA DO SAFARI.",
  ["_UnveiledGhostText"] = "Droga! O FANTASMA\nnão pode ser\videntificado!",
  ["_UseNextMonText"] = "Usar seu\npróximo POKéMON?",
  ["_UsedCutText"] = "{RAM:wNameBuffer} usou\nCORTAR em tudo!",
  ["_UsedInsteadText"] = "em vez disso,\v",
  ["_UsedMove1Text"] = "\nusou ",
  ["_UsedMove2Text"] = "\nusou ",
  ["_UsedStrengthText"] = "{RAM:wNameBuffer} usou\nFORÇA.",
  ["_VaporeonDexEntry"] = "Vive próximo da\nágua. Devido à sua\nlonga cauda com\fbarbatanas, às \nvezes é confundido\ncom uma sereia",
  ["_VendingMachineText1"] = "É uma máquina\nautomática para\vvenda de bebidas!\vVejamos o menu!",
  ["_VendingMachineText4"] = "Opa, sem dinheiro\nsuficiente!",
  ["_VendingMachineText5"] = "{RAM:wStringBuffer}\nsaiu!",
  ["_VendingMachineText6"] = "Não há espaço para\nmais coisas!",
  ["_VendingMachineText7"] = "Sem sede!",
  ["_VenomothDexEntry"] = "As escamas finas\ncomo pó que cobrem\nas suas asas são\fcoloridas para\nindicar o tipo de\nveneno que possui",
  ["_VenonatDexEntry"] = "Vive nas sombras \nde árvores altas,\nonde se alimenta\fde insetos. Ele é\natraído por luzes\ndurante a noite",
  ["_VenusaurDexEntry"] = "A planta floresce\nquando está absor-\nvendo a energia\fsolar. Ele se man-\ntém em movimento\na procura de luz",
  ["_VermilionCityBeautyText"] = "Somos cuidadosos\ncom a poluição!\fSoubemos que os \nGRIMER podem se\vmultiplicar em\vlama tóxica!",
  ["_VermilionCityGambler1DidYouSeeText"] = "Você já viu o\nSt.ANA ancorado\vno porto?",
  ["_VermilionCityGambler1SSAnneDepartedText"] = "Então, o St.ANA\njá partiu!\fEle vai voltar em\ncerca de um ano.",
  ["_VermilionCityGambler2Text"] = "Estou construindo\num prédio nesse\vlote de terra.\fMeu POKéMON está\nsocando a terra.",
  ["_VermilionCityGymSignText"] = "GINÁSIO POKéMON\nDE VERMILION\vLÍDER: TEN. SURGE\fO Relâmpago\nAmericano!",
  ["_VermilionCityHarborSignText"] = "PORTO DE VERMILION",
  ["_VermilionCityMachopStompingTheLandFlatText"] = "\fUm MACHOP está\npisoteando todo\vo terreno.",
  ["_VermilionCityMachopText"] = "MACHOP: Chuoh!\nChopchopchoph!",
  ["_VermilionCityNoticeSignText"] = "AVISO!\fA ROTA 12 pode\nestar bloqueada\vpor um POKéMON\vdorminhoco.\fDesvie através do\nTÚNEL ROCHOSO\vpara chegar na\vCIDADE DE\vLAVENDER.\fPOLÍCIA DE\nVERMILION",
  ["_VermilionCityPokemonFanClubSignText"] = "FÃ CLUBE POKéMON\nTodos os fãs de\vPOKéMON são \vbem-vindos!",
  ["_VermilionCitySailor1DoYouHaveATicketText"] = "Bem-vindo ao\nS.S. St.ANA!\fCom licença, você\npossui um bilhete\vde viagem?",
  ["_VermilionCitySailor1FlashedTicketText"] = "{PLAYER} mostrou o\nBILHETE DO NAVIO!\fÓtimo! Bem-vindo\nao S.S. St.ANA!",
  ["_VermilionCitySailor1ShipSetSailText"] = "O navio zarpou.",
  ["_VermilionCitySailor1WelcomeToSSAnneText"] = "Bem-vindo ao\nS.S. St.ANA!",
  ["_VermilionCitySailor1YouNeedATicketText"] = "{PLAYER} não tem o\nBILHETE DO NAVIO!\fDesculpe!\fVocê precisa de\num bilhete para\vembarcar.",
  ["_VermilionCitySailor2Text"] = "S.S. St.ANA é um\nfamoso e luxuoso\vnavio cruzeiro.\fEle nos visita em\nVERMILION uma vez\vpor ano.",
  ["_VermilionCitySignText"] = "CIDADE DE\nVERMILION\vA Cidade do\vPoente Requintado",
  ["_VermilionGymGentlemanAfterBattleText"] = "A porta não quer\nabrir?\fTenente SURGE é\nmuito cauteloso!",
  ["_VermilionGymGentlemanBattleText"] = "Quando eu estava\nno exército, o\vTenente SURGE era\vmeu comandante!",
  ["_VermilionGymGentlemanEndBattleText"] = "Pare!\nVocê é muito bom!",
  ["_VermilionGymGymGuideBeatLTSurgeText"] = "Ufa! Essa batalha\nfoi eletrizante!",
  ["_VermilionGymGymGuideChampInMakingText"] = "E aí! Aprendiz\nde Campeão!\fTEN. SURGE tem um\napelido. O chamam\vde o Relâmpago\vAmericano!\fSua especialidade\nsão os POKéMON\vde tipo Elétrico!\fPOKéMON voadores e\naquáticos estão\vem risco! E muito\vcuidado com a\vparalisia.\fTEN. SURGE é\nmuito cauteloso!\fTerá que decifrar\nseu código para\vchegar até ele!",
  ["_VermilionGymLTSurgePostBattleAdviceText"] = "Uma pequena dica,\nmenino!\fEletricidade é\nmuito poderosa!\fMas é inútil\ncontra POKéMON do\vtipo terrestre!",
  ["_VermilionGymLTSurgePreBattleText"] = "Ei, garoto! O que\nvocê pensa que\vfaz aqui?\fVocê não vai durar\nmuito em combate!\vIsso eu garanto!\fSabe, os POKéMON\nelétricos me \vsalvaram durante\va guerra!\fEles eletrocutaram\nmeus inimigos e\vos paralisaram!\fAssim como eu\nfarei com você!",
  ["_VermilionGymLTSurgeReceivedTM24Text"] = "{PLAYER} recebeu\na {RAM:wStringBuffer}!",
  ["_VermilionGymLTSurgeReceivedThunderBadgeText"] = "\nUou!\fMuito bom traba-\nlho, {PLAYER}!\fCerto, fique com a\nINSÍGNIA TROVÃO\vcomo prova de sua\vvitória!",
  ["_VermilionGymLTSurgeTM24NoRoomText"] = "Ei garoto, arrume\nalgum espaço aí\vnessa mochila!",
  ["_VermilionGymLTSurgeThunderBadgeInfoText"] = "A INSÍGNIA TROVÃO\nirá aumentar a\vVELOCIDADE dos\vseus POKéMON!\fTambém permite que\nseus POKéMON usem\va técnica VOAR a\vqualquer momento!\fVocê é especial,\ngaroto! Fique\vcom isso também!",
  ["_VermilionGymSailorAfterBattleText"] = "TEN. SURGE armou\ntrancas duplas!\vAqui vai a dica!\fQuando abrir a\n1ª tranca, a 2ª\vtranca estará bem\vao lado dessa!",
  ["_VermilionGymSailorBattleText"] = "Aqui não é lugar\npara crianças!",
  ["_VermilionGymSailorEndBattleText"] = "Uau!\nMe surpreendeu!",
  ["_VermilionGymSuperNerdAfterBattleText"] = "OK, vou falar!\fTEN. SURGE disse\nque escondeu os\vbotões que ativam\vas portas dentro\vde alguma coisa.",
  ["_VermilionGymSuperNerdBattleText"] = "Posso não ser um\nguerreiro mas eu\vsou muito bom\vcom eletricidade!",
  ["_VermilionGymSuperNerdEndBattleText"] = "Frito!",
  ["_VermilionGymTrashFailText"] = "Não! Só tem\nlixo aqui.\vEi! As trancas\veletrônicas\vse reativaram!",
  ["_VermilionGymTrashSuccessText1"] = "Ei! Tem um botão\nembaixo do lixo!\vFoi ativado!\fA 1ª tranca ele-\ntrônica se abriu!",
  ["_VermilionGymTrashSuccessText2"] = "Ei! Tem outro\nbotão debaixo\vdo lixo!\vFoi ativado!",
  ["_VermilionGymTrashSuccessText3"] = "A 2ª tranca ele-\ntrônica se abriu!\fA porta motorizada\nse abriu!",
  ["_VermilionGymTrashText"] = "Não, só tem\nlixo aqui.",
  ["_VermilionMartCooltrainerFText"] = "Eu acho que os\nPOKéMON podem ser\vbons ou maus.\vIsso vai depender\vdo seu treinador.",
  ["_VermilionMartCooltrainerMText"] = "Existem pessoas\nmás que usam os\vPOKéMON para\vfins criminosos.\fA EQUIPE ROCKET\nfaz tráfico de\vPOKéMON raros.\fEles também aban-\ndonam POKéMON que\vnão consideram \vpopulares ou\vúteis.",
  ["_VermilionOldRodHouseFishingGuruDoYouLikeToFishText"] = "Olá, eu sou o\nGURU DA PESCARIA!\fEu simplesmente\naaamo pescar!\fVocê também gosta\nde pescar?",
  ["_VermilionOldRodHouseFishingGuruFishingIsAWayOfLifeText"] = "\fPescar é um estilo\nde vida!\fDe mares aos rios,\nvá e pesque um\vgrandão, velho!",
  ["_VermilionOldRodHouseFishingGuruHowAreTheFishBitingText"] = "Olá, meu velho\namigo {PLAYER}!\fOs peixes estão\nfisgando muito?",
  ["_VermilionOldRodHouseFishingGuruNoRoomText"] = "Ah, não!\fVocê está sem\nespaço para\vmeu presente!",
  ["_VermilionOldRodHouseFishingGuruTakeThisText"] = "Gostei do seu\nestilo, velho!\fPegue isso e \nvá pescar!\f{PLAYER} recebeu\numa {RAM:wStringBuffer}!",
  ["_VermilionOldRodHouseFishingGuruThatsSoDisappointingText"] = "Ah... Isso é tão\ndecepcionante...",
  ["_VermilionPidgeyHouseLetterText"] = "Querida LILI, eu\nespero te ver\vnovamente.\fFiquei sabendo\nque a CIDADE DE\vSAFFRON está\vtendo problemas\vpor causa da\vEQUIPE ROCKET.\fVERMILION parece\nestar segura.",
  ["_VermilionPidgeyHousePidgeyText"] = "PIDGEY: Curucuu!",
  ["_VermilionPidgeyHouseYoungsterText"] = "Estou preparando\nmeu PIDGEY para\vvoar até a CIDADE\vDE SAFFRON, ao\vnorte, para en-\vtregar uma carta!",
  ["_VermilionPokecenterFishingGuruText"] = "Mesmo se tiverem o\nmesmo nível, os\vPOKéMON podem ter\vatributos bem\vdiferentes.\fUm POKéMON criado\npor um treinador\vé bem mais forte\vque um selvagem.",
  ["_VermilionPokecenterGuyText"] = "É verdade que um\nPOKéMON de nível\vmais alto será\vmais poderoso...\fMas todos POKéMON\npossuem fraquezas\vcontra alguns ti-\vpos específicos.\fEntão, não existe\num POKéMON que \vseja invencível.",
  ["_VermilionPokecenterSailorText"] = "Meu POKéMON foi\nenvenenado! Ele\vdesmaiou enquanto\veu caminhava!",
  ["_VictoryRoad1FCooltrainerFAfterBattleText"] = "Eu queria nunca\nter perdido para\vninguém!",
  ["_VictoryRoad1FCooltrainerFBattleText"] = "Imagino se você\nserá bom o sufi-\vciente pra mim!",
  ["_VictoryRoad1FCooltrainerFEndBattleText"] = "Eu\nperdi feio!",
  ["_VictoryRoad1FCooltrainerMAfterBattleText"] = "Eu admito, você é\nmelhor do que eu!",
  ["_VictoryRoad1FCooltrainerMBattleText"] = "Posso ver que você\né bom! Permita-me\vver exatamente o\vquão bom você é!",
  ["_VictoryRoad1FCooltrainerMEndBattleText"] = "Eu\ntinha uma chance.",
  ["_VictoryRoad2FCooltrainerMAfterBattleText"] = "Você merece mesmo\nestar aqui na\vROTA DA VITÓRIA!",
  ["_VictoryRoad2FCooltrainerMBattleText"] = "Vamos!\nVou te chicotear!",
  ["_VictoryRoad2FCooltrainerMEndBattleText"] = "Fui\nchicoteado!",
  ["_VictoryRoad2FHikerAfterBattleText"] = "Se estiver preso,\ntente mover algu-\vmas rochas por aí!",
  ["_VictoryRoad2FHikerBattleText"] = "ROTA DA VITÓRIA é\no teste final\vdos treinadores!",
  ["_VictoryRoad2FHikerEndBattleText"] = "Aiah!",
  ["_VictoryRoad2FMoltresBattleText"] = "Gyaoo!",
  ["_VictoryRoad2FSuperNerd1AfterBattleText"] = "{RIVAL} também\npassou por aqui!",
  ["_VictoryRoad2FSuperNerd1BattleText"] = "Ah, então você\nquer desafiar a\vELITE DOS QUATRO?",
  ["_VictoryRoad2FSuperNerd1EndBattleText"] = "Você\nme venceu!",
  ["_VictoryRoad2FSuperNerd2AfterBattleText"] = "Eu posso te vencer\nquando se trata\vde conhecimento\vsobre POKéMON!",
  ["_VictoryRoad2FSuperNerd2BattleText"] = "Se você conseguir\npassar por aqui,\vvocê poderá ir\venfrentar a\vELITE DOS QUATRO!",
  ["_VictoryRoad2FSuperNerd2EndBattleText"] = "Não!\nInacreditável!",
  ["_VictoryRoad2FSuperNerd3AfterBattleText"] = "Muitos treinadores\ndesistem do desa-\vfio aqui.",
  ["_VictoryRoad2FSuperNerd3BattleText"] = "A ROTA DA VITÓRIA\né muito difícil?",
  ["_VictoryRoad2FSuperNerd3EndBattleText"] = "Bem\nfeito!",
  ["_VictoryRoad3FCooltrainerF1AfterBattleText"] = "Você me mostrou o\nquão boa eu era!",
  ["_VictoryRoad3FCooltrainerF1BattleText"] = "Vou te mostrar o\nquão bom você é!",
  ["_VictoryRoad3FCooltrainerF1EndBattleText"] = "Eu\nestou furiosa!",
  ["_VictoryRoad3FCooltrainerF2AfterBattleText"] = "Enfrentar batalhas\ndifíceis, vai te\vdeixar mais forte!",
  ["_VictoryRoad3FCooltrainerF2BattleText"] = "Treinadores vivem\na procura de\vadversários mais\vpoderosos!",
  ["_VictoryRoad3FCooltrainerF2EndBattleText"] = "Oh!\nTão forte!",
  ["_VictoryRoad3FCooltrainerM1AfterBattleText"] = "Você derrotou\no GIOVANNI da\vEQUIPE ROCKET?",
  ["_VictoryRoad3FCooltrainerM1BattleText"] = "Eu ouvi alguns\nrumores sobre um\vgaroto prodígio!",
  ["_VictoryRoad3FCooltrainerM1EndBattleText"] = "Os\nrumores eram\vmesmo verdade!",
  ["_VictoryRoad3FCooltrainerM2AfterBattleText"] = "Todos os treina-\ndores aqui estão\va caminho da LIGA\vPOKéMON!\vSeja cuidadoso!",
  ["_VictoryRoad3FCooltrainerM2BattleText"] = "Apenas o escolhido\npode passar aqui!",
  ["_VictoryRoad3FCooltrainerM2EndBattleText"] = "Eu\nnão acredito!",
  ["_VictreebelDexEntry"] = "Dizem que vivem em\ncolônias enormes\nem mata fechada,\fapesar que ninguém\nnunca jamais tenha\nretornado de lá",
  ["_VileplumeDexEntry"] = "Quanto maior são\nsuas pétalas,\nmais pólen tóxico\firá armazenar. Sua\ncabeça fica pesada\ne difícil erguer",
  ["_ViridianBlackboardBurnText"] = "Uma queimadura\nreduz o poder de\vataque. E também\vcausa um dano\vcontínuo.\fQueimaduras se\nmantém mesmo\vapós as batalhas.\fUse ANTIQUEIMADURA\ncomo tratamento!",
  ["_ViridianBlackboardFrozenText"] = "Se congelado, um\nPOKéMON ficará\vimobilizado!\fE continuará\ncongelado após a\vbatalha acabar.\fUse ANTICONGELANTE\npara descongelar!",
  ["_ViridianBlackboardPoisonText"] = "Se for envenenado,\no POKéMON perderá\vpontos de saúde\vgradativamente.\fO veneno continua\nagindo mesmo após\vo fim da batalha.\fUse um ANTÍDOTO\npara curar o\venvenenamento!",
  ["_ViridianBlackboardPrlzText"] = "Paralisia deixa o\nPOKéMON lento e\vpode fazer ele\verrar o ataque!\fParalisia continua\napós as batalhas.\fUse ANTIPARALISIA\ncomo tratamento!",
  ["_ViridianBlackboardSleepText"] = "Um POKéMON não\nataca se estiver\vdormindo!\fPOKéMON continuam\ndormindo mesmo\vapós a batalha.\fUse DESPERTADOR\npara acordá-los!",
  ["_ViridianCityFisherReceivedTM42Text"] = "{PLAYER} recebeu\na MT42!",
  ["_ViridianCityFisherTM42ExplanationText"] = "MT42 contém COME-\nDOR DE SONHOS...\v...Ronc...",
  ["_ViridianCityFisherTM42NoRoomText"] = "Você já tem muita\ncoisa na mochila.",
  ["_ViridianCityGambler1GymAlwaysClosedText"] = "Esse GINÁSIO POKé-\nMON está sempre\vfechado.\fQuem será que pode\nser o seu LÍDER?",
  ["_ViridianCityGambler1GymLeaderReturnedText"] = "Enfim, o LÍDER do\nGINÁSIO voltou!",
  ["_ViridianCityGirlHasntHadHisCoffeeYetText"] = "Ah, Vovô! Não seja\ntão malvado!  É\vque ele ainda não\vtomou o seu café!",
  ["_ViridianCityGirlWhenIGoShopText"] = "Quando vou fazer\nminhas compras na\vCIDADE DE PEWTER,\vtenho que pegar o\vcaminho sinuoso\vda FLORESTA DE\vVIRIDIAN.",
  ["_ViridianCityGymLockedText"] = "A porta do GINÁSIO\nestá trancada...",
  ["_ViridianCityGymSignText"] = "GINÁSIO POKéMON DA\nCIDADE DE VIRIDIAN",
  ["_ViridianCityOldManHadMyCoffeeNowText"] = "Ahh, já tomei meu\ncafézinho e agora\vme sinto ótimo!\fMas é claro que\nvocê pode passar!\fVocê está com\npressa?",
  ["_ViridianCityOldManKnowHowToCatchPokemonText"] = "Vejo que você está\ncom uma POKéDEX.\fQuando você captu-\nrar um POKéMON, a\vsua POKéDEX será\vatualizada auto-\vmaticamente.\fQuê? Você não sabe\ncomo capturar\vPOKéMON?\fEntão eu vou\nte mostrar.",
  ["_ViridianCityOldManSleepyPrivatePropertyText"] = "Você não pode\npassar por aqui!\fÉ uma propriedade\nprivada!",
  ["_ViridianCityOldManTimeIsMoneyText"] = "Tudo bem! O tempo\né valioso...",
  ["_ViridianCityOldManYouNeedToWeakenTheTargetText"] = "Primeiro, você\nprecisa enfraque-\vcer o POKéMON.",
  ["_ViridianCityPokecenterGuyText"] = "CENTROS POKéMON\ncuram seus\vPOKéMON cansados,\fferidos ou\ndesmaiados!",
  ["_ViridianCitySignText"] = "CIDADE DE VIRIDIAN\nUm Eterno\vParaíso Verde",
  ["_ViridianCityTrainerTips1Text"] = "DICAS PARA\nTREINADORES\fCapture POKéMON\ne expanda sua\vcoleção!\fQuanto mais você\ntiver, mais fácil\vserão as batalhas!",
  ["_ViridianCityTrainerTips2Text"] = "DICAS PARA\nTREINADORES\fDurante a batalha\nos golpes dos\vPOKéMON são limi-\vtados pelos seus\vPONTOS DE PODER,\vtambém chamados\vde apenas PP.\fPara recuperar PP,\ndescanse seus\vPOKéMON cansados\vem um CENTRO\vPOKéMON!",
  ["_ViridianCityYoungster1Text"] = "Essa POKé BOLA na\nsua cintura...\vVocê tem POKéMON!\fÉ incrível poder\ncarregar e usar\vos POKéMON em\vqualquer hora\ve qualquer lugar!",
  ["_ViridianCityYoungster2YouWantToKnowAboutText"] = "Você quer saber\nmais sobre os 2\vtipos de lagartas\vPOKéMON?",
  ["_ViridianForestLeavingSignText"] = "DEIXANDO A FLORES-\nTA DE VIRIDIAN\vCIDADE DE PEWTER\vEM FRENTE",
  ["_ViridianForestNorthGateGrampsText"] = "Você reparou nos\narbustos ao longo\vda rota?\fVocê pode CORTAR\neles usando uma\vtécnica especial\vde um POKéMON.",
  ["_ViridianForestNorthGateSuperNerdText"] = "Muitos POKéMON\nvivem apenas em\vflorestas e\vcavernas.\fVocê precisa olhar\npor toda parte se\vquiser pegar mais\vtipos diferentes.",
  ["_ViridianForestSouthGateGirlText"] = "Você está indo\npara a FLORESTA\vDE VIRIDIAN?\vTenha cuidado, é\vum labirinto\vnatural.",
  ["_ViridianForestSouthGateLittleGirlText"] = "RATTATA pode ser\npequeno, mas sua\vmordida é forte!\vJá levou uma?",
  ["_ViridianForestTrainerTips1Text"] = "DICAS PARA\nTREINADORES\fSe quiser evitar\nbatalhas, fique\vfora das áreas\vcom grama alta!",
  ["_ViridianForestTrainerTips2Text"] = "DICAS PARA\nTREINADORES\fSe quiser evitar\nbatalhas, fique\vfora das áreas\vcom grama alta!",
  ["_ViridianForestTrainerTips3Text"] = "Para envenenamento\nuse ANTÍDOTO!\vCompre um nas\vLOJAS POKéMON!",
  ["_ViridianForestTrainerTips4Text"] = "DICAS PARA\nTREINADORES\fEntre em contato\ncom o PROF.\vCARVALHO para ele\vavaliar a sua\vPOKéDEX!",
  ["_ViridianForestUseAntidoteSignText"] = "Para envenenamento\nuse ANTÍDOTO!\vCompre um nas\vLOJAS POKéMON!",
  ["_ViridianForestYoungster1Text"] = "Eu vim aqui com\nalguns amigos!\fVieram em busca de\nbatalhas POKéMON!",
  ["_ViridianForestYoungster2AfterBattleText"] = "Chiu! Você vai es-\npantar os insetos!",
  ["_ViridianForestYoungster2BattleText"] = "Ei! Você tem\nPOKéMON! Vamos\vbatalhar!",
  ["_ViridianForestYoungster2EndBattleText"] = "Não!\nMeu CATERPIE não\vconseguiu vencer!",
  ["_ViridianForestYoungster3AfterBattleText"] = "Hã?\nEu fiquei sem\vnenhum POKéMON!",
  ["_ViridianForestYoungster3BattleText"] = "Hã?\nEu fiquei sem\vnenhum POKéMON!",
  ["_ViridianForestYoungster3EndBattleText"] = "Ei! Não vou deixar\nvocê escapar se\vfor um treinador!",
  ["_ViridianForestYoungster4AfterBattleText"] = "Às vezes, você\npode encontrar\vcoisas no chão!\fEstou procurando\npor algo que eu\vdeixei cair!",
  ["_ViridianForestYoungster4BattleText"] = "Ei, espere aí!\nPor que a pressa?",
  ["_ViridianForestYoungster4EndBattleText"] = "Eu\ndesisto! Você\vé bom nisso!",
  ["_ViridianForestYoungster5Text"] = "Fiquei sem POKé\nBOLAs para pegar\vmais POKéMON!\fÉ bom sempre ter\nalgumas reservas!",
  ["_ViridianGymCooltrainerM1AfterBattleText"] = "Você precisa de\nmais poder para\venfrentar o LÍDER\vDO GINÁSIO!",
  ["_ViridianGymCooltrainerM1BattleText"] = "Hehe! Você já deve\nestar sem gás a\vessa hora!",
  ["_ViridianGymCooltrainerM1EndBattleText"] = "Eu\nfiquei sem gás!",
  ["_ViridianGymCooltrainerM2AfterBattleText"] = "O LÍDER vai me\nrepreender por\vessa derrota!",
  ["_ViridianGymCooltrainerM2BattleText"] = "Quem é talentoso\nde verdade vence\vcom estilo!",
  ["_ViridianGymCooltrainerM2EndBattleText"] = "Eu\nescorreguei!",
  ["_ViridianGymCooltrainerM3AfterBattleText"] = "Você só poderá ir\nna LIGA POKéMON\vse derrotar nosso\vLÍDER DE GINÁSIO!",
  ["_ViridianGymCooltrainerM3BattleText"] = "O GINÁSIO POKéMON\nde VIRIDIAN es-\vteve fechado por\vmuito tempo, mas\vagora, o nosso\vLÍDER voltou!",
  ["_ViridianGymCooltrainerM3EndBattleText"] = "Eu\nfui derrotado?",
  ["_ViridianGymGiovanniEarthBadgeInfoText"] = "A INSÍGNIA TERRA\nfaz os POKéMON de\vqualquer nível te\vobedecerem!\fÉ a evidência da\nsua maestria como\vtreinador POKéMON!\fCom ela, você\npoderá entrar na\vLIGA POKéMON!\fE isto aqui, é um\npresente meu para\vo seu desafio à\vLIGA POKéMON!",
  ["_ViridianGymGiovanniPostBattleAdviceText"] = "Tendo perdido, não\npoderei mais\vencarar meus\vsubordinados!\vA EQUIPE ROCKET\vestá acabada,\vpara sempre!\fIrei dedicar minha\nvida ao estudo\vdos POKéMON!\fQue possamos nos\nencontrar nova-\vmente um dia!\vAdeus!",
  ["_ViridianGymGiovanniPreBattleText"] = "Fwahahaha! Esse é\nmeu esconderijo!\fEu planejei res-\nsucitar a EQUIPE\vROCKET aqui!\fMas você me pegou\nnovamente! Então\vque seja! Dessa\vvez não vou me\vsegurar!\fMais uma vez,\nvocê enfrentará\vGIOVANNI, o maior\vdos treinadores!",
  ["_ViridianGymGiovanniReceivedEarthBadgeText"] = "Ha!\nEssa batalha foi\vmesmo intensa!\vVocê venceu! Como\vprova, aqui está\va INSÍGNIA TERRA!",
  ["_ViridianGymGiovanniReceivedTM27Text"] = "{PLAYER} recebeu\na MT27!",
  ["_ViridianGymGiovanniTM27ExplanationText"] = "\fMT27 contém \nFISSURA!\vIsso derrota um\vPOKéMON com ape-\vnas um golpe!\fEu a criei quando\neu ainda cuidava\vdesse GINÁSIO, há\vmuito tempo...",
  ["_ViridianGymGiovanniTM27NoRoomText"] = "Você não tem mais\nespaço pra isso!",
  ["_ViridianGymGuidePostBattleText"] = "Estou chocado!\nGIOVANNI era o\vLÍDER do GINÁSIO?",
  ["_ViridianGymGuidePreBattleText"] = "E aí! Campeão em\nconstrução!\fNem mesmo eu sei\na identidade do\vLÍDER do GINÁSIO\vde VIRIDIAN!\fEsse vai ser o\nmais difícil de\vtodos os LÍDERES\vde GINÁSIO!\fOuvi dizer que os\ntreinadores aqui\vgostam de POKéMON\vdo tipo terra!",
  ["_ViridianGymHiker1AfterBattleText"] = "Ainda não sou\ndigno!",
  ["_ViridianGymHiker1BattleText"] = "Caratê é o estilo\nsupremo das artes\vmarciais!",
  ["_ViridianGymHiker1EndBattleText"] = "Argh!",
  ["_ViridianGymHiker2AfterBattleText"] = "Se meus POKéMON\nfossem bons de\vcaratê como eu...",
  ["_ViridianGymHiker2BattleText"] = "Caratê é o estilo\nsupremo das artes\vmarciais!",
  ["_ViridianGymHiker2EndBattleText"] = "\nAtchim!",
  ["_ViridianGymHiker3AfterBattleText"] = "LIGA POKéMON?\nVocê? Não fique\vtão convencido!",
  ["_ViridianGymHiker3BattleText"] = "Eu sou o REI DO\nCARATÊ! Seu fim\vserá aqui comigo!",
  ["_ViridianGymHiker3EndBattleText"] = "Ayah!",
  ["_ViridianGymRocker1AfterBattleText"] = "Você sabe a iden-\ntidade do nosso\vLÍDER DE GINÁSIO?",
  ["_ViridianGymRocker1BattleText"] = "POKéMON e eu, nós\nfazemos músicas\vincríveis juntos!",
  ["_ViridianGymRocker1EndBattleText"] = "Eu\nescorreguei!",
  ["_ViridianGymRocker2AfterBattleText"] = "Calma! Eu só fui\ndescuidado!",
  ["_ViridianGymRocker2BattleText"] = "Seus POKéMON vão\nse acovardar com\vo estalo do meu\vchicote!",
  ["_ViridianGymRocker2EndBattleText"] = "Au!\nQue chicotada!",
  ["_ViridianMartClerkParcelQuestText"] = "Você conhece o\nPROF.CARVALHO,\vnão é?\fA encomenda dele\nchegou. Você pode\ventregar pra ele?\f{PLAYER} recebeu\na ENCOMENDA para\vo PROF.CARVALHO!",
  ["_ViridianMartClerkSayHiToOakText"] = "Certo! Diga ao\nPROF.CARVALHO\vque eu disse olá.",
  ["_ViridianMartClerkYouCameFromPalletTownText"] = "Ei! Você veio da\nCIDADE DE PALLET?",
  ["_ViridianMartCooltrainerMText"] = "Ah, não! As POÇÕES\nestão esgotadas.",
  ["_ViridianMartYoungsterText"] = "Essa loja vende\nvários ANTÍDOTOs.",
  ["_ViridianNicknameHouseBaldingGuyText"] = "Colocar apelidos é\nmuito legal, mas\vdifícil também.\fNomes simples são\nmais fáceis de\vlembrar.",
  ["_ViridianNicknameHouseLittleGirlText"] = "Meu papai ama\nPOKéMON também.",
  ["_ViridianNicknameHouseSpearowText"] = "PIU-PIU: Piuuu!",
  ["_ViridianNicknameHouseSpearySignText"] = "SPEAROW\nNome: PIU-PIU",
  ["_ViridianPokecenterCooltrainerMText"] = "Tem um CENTRO\nPOKéMON em todas\vas cidades\va seguir.\fEles não cobram\nnem um tostão!",
  ["_ViridianPokecenterGentlemanText"] = "Você pode usar o\nPC ali no canto.\fA recepcionista me\ncontou. É muita\vgentileza!",
  ["_ViridianSchoolBlackboardText1"] = "O quadro negro\ndescreve as\valterações de\vESTADO POKéMON\vdurante batalhas.",
  ["_ViridianSchoolBlackboardText2"] = "Qual tópico você\ngostaria de ler?",
  ["_ViridianSchoolHouseBrunetteGirlText"] = "Nossa! Estou ten-\ntando memorizar\vminhas anotações.",
  ["_ViridianSchoolHouseCooltrainerFText"] = "Atenção!\fLeia a lousa com\nbastante atenção!",
  ["_ViridianSchoolNotebookText1"] = "Lendo o\ncaderno!\fPrimeira página...\fPOKé BOLAs são\nusadas para\vcapturar POKéMON.\fVocê pode carregar\naté 6 POKéMON.\fPessoas que criam\ne fazem batalhas\vcom os POKéMON\vsão chamadas de\vTREINADORES {PK}{MN}.",
  ["_ViridianSchoolNotebookText2"] = "Segunda página...\fCapturar POKéMON\nsaudáveis é mais\vdifícil, então\venfraqueça-os!\fAlterações de\nESTADO, como\venvenenamento e\vqueimadura são\vbem úteis também.",
  ["_ViridianSchoolNotebookText3"] = "Terceira página...\fOs treinadores\nPOKéMON procuram\voutros para fazer\vbatalhas POKéMON.\fAs batalhas são\nconstantes nos\vGINÁSIOS POKéMON.",
  ["_ViridianSchoolNotebookText4"] = "Quarta página...\fO objetivo dos\ntreinadores é\vderrotar os 8\vLÍDERES dos\vGINÁSIOS POKéMON.\fPara conquistarem\no direito de\venfrentar...\fA ELITE DOS QUATRO\nda LIGA POKéMON!",
  ["_ViridianSchoolNotebookText5"] = "MENINA: Ei! Pare\nde bisbilhotar\vminhas anotações!",
  ["_VitaminNoEffectText"] = "Não faz mais\nnenhum efeito.",
  ["_VitaminStatRoseText"] = "O {RAM:wStringBuffer} de\n{RAM:wNameBuffer} subiu.",
  ["_VoltorbDexEntry"] = "Geralmente encon-\ntrado em usinas\nelétricas. Facil-\fmente confundido\ncom uma POKé BOLA,\nataca os curiosos",
  ["_VulpixDexEntry"] = "Em seu nascimento,\npossui apenas uma\ncauda. Ela então\fse divide a partir\nda ponta enquanto\nele envelhece",
  ["_WannaTrade1Text"] = "Estou procurando\npor um {RAM:wInGameTradeGiveMonName}!\fQuer trocar por\num {RAM:wInGameTradeReceiveMonName}? ",
  ["_WannaTrade2Text"] = "Olá! Gostaria\nde trocar seu\v{RAM:wInGameTradeGiveMonName} por\vum {RAM:wInGameTradeReceiveMonName}?",
  ["_WannaTrade3Text"] = "Olá! O seu velho\namigo {RAM:wInGameTradeGiveMonName}\vé mesmo incrível!",
  ["_WardensHouseDisplayMerchandiseText"] = "Produtos POKéMON\nantigos...\fParecem ser discos\nholográficos...",
  ["_WardensHouseDisplayPhotosAndFossilsText"] = "Fotos de POKéMON\ne fósseis.",
  ["_WardensHouseWardenGaveTheGoldTeethText"] = "{PLAYER} entregou\na DENTADURA para\vo DIRETOR!",
  ["_WardensHouseWardenGibberish1Text"] = "DIRETOR: Hif fuff\nhefifoo!\fHe pefi ha feefafu\nfaf ha hafahi ho.\vHeff hee fwee!",
  ["_WardensHouseWardenGibberish2Text"] = "Ah howhee ho hoo!\nEef ee hafahi ho!",
  ["_WardensHouseWardenGibberish3Text"] = "Hã? He ohay heh\nha hoo ee haheh!",
  ["_WardensHouseWardenHM04ExplanationText"] = "DIRETOR: A MO04\ncontém FORÇA!\fIsso permite que\nseu POKéMON possa\vmover grandes\vrochas do seu\vcaminho fora das\vbatalhas.\fAh, sim, você já\nencontrou a CASA\vSECRETA da ZONA\vDO SAFARI?\fSe você achar,\nganhará uma MO!\fOuvi dizer que é a\nrara MO de SURFAR.",
  ["_WardensHouseWardenHM04NoRoomText"] = "Sua mochila já\nestá lotada!",
  ["_WardensHouseWardenReceivedHM04Text"] = "{PLAYER} recebeu\na {RAM:wStringBuffer}!",
  ["_WardensHouseWardenTeethPoppedInHisTeethText"] = "\fO DIRETOR colocou\na sua DENTADURA!",
  ["_WardensHouseWardenThanksText"] = "DIRETOR: Obrigado,\ngaroto! Ninguém\vconseguia enten-\vder uma palavra\vque eu dizia.\fEu não conseguia\ntrabalhar assim.\vAceite isso como\vrecompensa pela\vsua ajuda.",
  ["_WarpToLastPokemonCenterText"] = "Voltou direto para\num CENTRO POKéMON.",
  ["_WartortleDexEntry"] = "Se esconde na água\npara observar suas\npresas desatentas.\fAo nadar, move as\nsuas orelhas para\nse equilibrar",
  ["_WasBlownAwayText"] = "O vento levou\nROCKET longe!",
  ["_WasSeededText"] = "{TARGET}\nse esquivou desse{SCROLL}ataque!",
  ["_WeedleDexEntry"] = "Comumente achado\nem florestas,\ncomendo folhas.\fPossui um afiado\ne venenoso ferrão\nem sua cabeça",
  ["_WeepinbellDexEntry"] = "Cospe Pó VENENOSO\npara imobilizar o\ninimigo e então\ffinalizá-lo com\nseus poderosos\nborrifos de ÁCIDO",
  ["_WeezingDexEntry"] = "Quando dois tipos\nde gases venenosos\nse encontram, dois\fKOFFINGs se fundem\nem um WEEZING após\nmuitos anos",
  ["_WhatDoYouWantText"] = "O que você quer\nfazer?",
  ["_WhatGoesAroundComesAroundText"] = "Tudo que sobe\ntem que descer!",
